import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/20/","title":"第 20 课 · 篇章阅读 Passage Reading | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 20 课 · 篇章阅读 Passage Reading","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/20/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 02 · 题型技巧 / 第三课 题型技巧 · 第三课 15 篇完整精读篇章（课件 p2-199，主讲 Betty 老师）——每篇依次过词汇、原文、译文、长句、练习：先把握段落主旨，再用句法拆解长句，最后通过练习检验词汇、从句、非谓语、指代和语篇逻辑。 考点地图 · 点击跳转 方法...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 20 课 · 篇章阅读 Passage Reading\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/20/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 20 课 · 篇章阅读 Passage Reading"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 02 · 题型技巧 / 第三课 题型技巧 · 第三课 15 篇完整精读篇章（课件 p2-199，主讲 Betty 老师）——每篇依次过词汇、原文、译文、长句、练习：先把握段落主旨，再用句法拆解长句，最后通过练习检验词汇、从句、非谓语、指代和语篇逻辑。 考点地图 · 点击跳转 方法..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 20 课 · 篇章阅读 Passage Reading"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/20/"}]]},"readingTime":{"minutes":188.4,"words":56521},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/20.md","headers":[]}`),u={name:`20.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0020-passage-reading.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 02 · 题型技巧 / 第三课`,-1)]),l[18]||=r(`<p>题型技巧 · 第三课</p><p>15 篇完整精读篇章（课件 p2-199，主讲 Betty 老师）——每篇依次过词汇、原文、译文、长句、练习：先把握段落主旨，再用句法拆解长句，最后通过练习检验词汇、从句、非谓语、指代和语篇逻辑。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>方法</strong>：通读定主题 → 分层读段落 → 拆解长句 → 原文定位作答 → 译文复盘（五步闭环）</a></li><li><a href="#pt-2"><strong>篇目</strong>：15 篇完整篇章，每篇配词汇 / 词组、英文原文、课件中文译文、长句分析、课堂练习与翻译练习</a></li><li><a href="#pt-3"><strong>练习</strong>：课堂练习 93 题（每篇 6–8 题，课件未附答案，答案与解析为笔记整理补充）+ 每篇翻译练习</a></li></ol></div><h2 id="精读方法-五步" tabindex="-1"><a class="header-anchor" href="#精读方法-五步"><span>精读方法（五步）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 精读方法（五步）</p><ul><li><strong>目标</strong>：把精读流程固定成五步：通读定主题 → 分层读段落 → 拆解长句 → 原文定位作答 → 译文复盘；本节重点解决前两步与长句拆解，用 Passage 1 的三段与课件原解析的长句做示范。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>篇章精读五步法</code> <code>通读定主题（标题 + 首段 + 段首句）</code> <code>段落功能与连接关系（转折 / 因果 / 举例 / 递进）</code> <code>长句拆解：主干先行，修饰后理</code> <code>原文定位作答（题干关键词回原文，证据唯一）</code> <code>译文复盘与错因归类（词汇 / 结构 / 逻辑定位）</code></li></ul></div><h3 id="精读方法-五步-·-小步学" tabindex="-1"><a class="header-anchor" href="#精读方法-五步-·-小步学"><span>精读方法（五步） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 0 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>篇章阅读：先抓主线，再拆长句</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>标题定向，段首定位：Passage 1 三段的骨架怎么一眼看出</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>长句拆解：先拎主干，再挂修饰（课件原解析三步示范）</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>题回原文，证据唯一：答案要同时过语义、语法、上下文三关</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li></ol></details><p><strong>自己说一遍</strong>：合上书说清五步的顺序，并各举一句：一句能说明「段首句给主题、段尾句给落点」，一句能示范「先划同位语与插入语，再找主干主谓宾」。</p><div class="hint-container tip"><p class="hint-container-title">标题定向，段首定位：Passage 1 三段的骨架怎么一眼看出</p><p><strong>句意</strong>：Fall in Love with English 讲的是「一个讨厌英语的高中生最后爱上英语」的过程：标题已经给出走向，读正文只是把「从讨厌到爱上」的中间过程填出来。</p><p><strong>拆解</strong></p><ul><li>标题 Fall in Love with English 给出结果与态度：从厌烦到喜欢，这是一篇「问题—转机—结果」的记叙文</li><li>第 1 段段首 Li Hua, a high-school student, was tired of his parents&#39; constant nagging about his English learning 定下「问题」，段尾 his test scores were disappointing, which further frustrated him 把困境收住</li><li>第 2 段段首 One day, his close friend Wang Tao noticed his low spirits 是「转机」，段中的 First / Second / Third 三条是方法</li><li>第 3 段段首 Inspired by Wang Tao&#39;s words, Li Hua started to change his learning methods 是「结果」，段尾 More importantly 把主题从分数抬回到「真正爱上英语」</li></ul><p><strong>语法</strong>：段落功能只有四类：提出现象、给出原因、举例佐证、收束结论。判据是信号词——转折（however、but、yet）、因果（because、therefore、as a result）、举例（for example、such as）、递进（more importantly、also）。段首句多给主题，段尾句多给落点，两句合看就知道这一段在干什么。</p><p>正例：As a result, his test scores were disappointing, which further frustrated him.（as a result 提示前面是原因、这里是结果）；More importantly, he had truly fallen in love with English.（more importantly 提示递进，全文主旨落在这一句）；First … Second … Third …（编号提示这一段是并列的三条建议） 反例：把第 2 段的三条建议当成作者的主张 ×（提建议的是 Wang Tao，作者只是转述）；只读第 1 段首句就下结论「文章在讲父母唠叨」×（段尾 disappointed / frustrated 才是这一段真正的落点） 适用边界：段落功能问的是「这一段主要在做什么」，不是「这一段里有哪些句子」。一段里可以同时有举例和转折，此时以段首主题句与段末收束句共同指向的那件事为准；只有两句指向冲突时，才需要读段中细节来定夺。</p><p><strong>口诀</strong>：标题定向，段首定位 —— 标题告诉你文章要去哪，段首句告诉你这一段在做什么。两句话读完再进细节，比逐句硬译快得多，也不会读懂了每句却答错整篇。</p></div><div class="hint-container tip"><p class="hint-container-title">长句拆解：先拎主干，再挂修饰（课件原解析三步示范）</p><p><strong>句意</strong>：Li Hua, a high-school student, was tired of his parents&#39; constant nagging about his English learning. 意思是「李华是一名高中生，他对父母不断唠叨他学英语感到厌烦」。</p><p><strong>拆解</strong></p><ul><li>第一刀划同位语：a high-school student 是对 Li Hua 的解释，用逗号隔开，删掉不影响句子成立</li><li>第二刀找主干：Li Hua 是主语，was tired of 是谓语部分，his parents&#39; constant nagging about his English learning 是宾语</li><li>第三刀处理宾语内部：nagging 是中心词，his parents&#39; 是修饰语，about his English learning 是介词短语作后置定语</li><li>同一篇里 He then shared some of his own learning tips, saying, &#39;First, try to find English materials that you&#39;re really interested in.&#39; 的主干是 He shared some tips，saying… 是现在分词短语作伴随状语，其中 that you&#39;re really interested in 是定语从句修饰 English materials</li><li>再如 More importantly, he had truly fallen in love with English, seeing it as a key to unlocking a wealth of knowledge and fun. —— More importantly 是插入语，主干是 he had fallen in love with English，seeing it as… 是伴随状语</li></ul><p><strong>语法</strong>：拆解顺序固定：主语 → 谓语 → 宾语 → 同位语与插入语 → 从句 → 非谓语修饰。能还原成从句的（分词短语、定语从句）按从句读，不能还原的（同位语、插入语、more importantly 这类评论性状语）直接划掉。三层成分分清楚，再长的句子也只剩「谁做了什么」。</p><p>正例：Li Hua, a high-school student, was tired of … → 主干 Li Hua was tired of …（同位语划掉）；He then shared some of his own learning tips, saying, &#39;…&#39; → 主干 He shared some tips（分词短语作伴随状语）；More importantly, he had truly fallen in love with English, seeing it as a key to … → 主干 he had fallen in love with English 反例：把 a high-school student 当成第二个主语 ×（逗号隔开的同位语不另起主谓）；把 saying 当成谓语 ×（逗号后无连词，第二个动词必须非谓语化）；把 More importantly 当成句子成分去分析 ×（它是评论性插入语，删掉句子仍然完整） 适用边界：「先划掉再读」只对真正的插入成分有效：同位语、评论性状语、and 并列的另一半可以暂时划掉。定语从句和被修饰的名词关系紧密，划掉会丢信息，要按从句读完整（which further frustrated him 就是结果，删了会丢掉因果关系）。</p><p><strong>口诀</strong>：主干先行，修饰后理 —— 先找主谓宾，再逐块往回挂修饰；每挂一块就归类：同位语、插入语、定语从句、分词状语，还是介词短语。归了类才知道它管谁。</p></div><div class="hint-container tip"><p class="hint-container-title">题回原文，证据唯一：答案要同时过语义、语法、上下文三关</p><p><strong>句意</strong>：Across the country, an average of 30,000 people die from smoking every year. 这类单句填空题，答案必须同时满足三件事：中文译得通、语法结构对、与句子其它部分不打架。</p><p><strong>拆解</strong></p><ul><li>语义关最先过：把四个选项分别译成中文放回空处，读得通的先留下</li><li>语法关第二过：主语单复数、时态、语态、从句结构逐项核对——悬空代词、残缺结构一律排除</li><li>上下文关最后过：同一句里的时间状语、原因从句、代词回指都是约束，比如 since 提示主句用现在完成时，for + 一段时间提示用延续性动词</li><li>三关都过的选项才唯一；只过一两关的，正是命题人留给「靠语感蒙」的坑</li></ul><p><strong>语法</strong>：单句语法题的定位句就是空所在的那一句，线索也都在句内或紧邻的前后句：时间状语（since、so far、by the end of、in the past two years）、逻辑连词（not…until、as soon as、unless）、代词（if only you had not told him 里的 him 回指前文）。定语从句、名词性从句这类题还要多过一关：从句缺什么成分。</p><p>正例：The unemployment rate in this district has fallen from 30% to 20% in the past two years.（in the past two years 提示现在完成时）；Not until I began to work did I realize how much time I had wasted.（Not until 置句首，主句部分倒装） 反例：只看搭配不看时间：in the past two years 后填 had fallen ×（过去完成时需要「过去的过去」参照点）；只看语感不看语态：the coat is cheap enough 里填 were ×（主语单数用 is） 适用边界：「证据唯一」是要求，不是每次都能立刻实现：个别题两个选项都能讲通一点，这时要回到最硬的语法约束上（时态呼应、主谓一致、从句成分），用能定下来的那一关做决断，并在复盘时把这类题记成「存疑」而不是强行记住答案。</p><p><strong>口诀</strong>：题回原文，证据唯一；译文复盘，错因归类 —— 做完一定要用译文复盘：把错题归到词汇（词不认识）、结构（成分没拆开）、逻辑定位（句子找对但读反了）三类中的一类。归了类，同一个错才不会犯第二次。</p></div><ol><li><strong>通读定主题</strong>：先读标题、首段与每段首句，用一句中文概括文章在讲什么。</li><li><strong>分层读段落</strong>：标出转折、因果、举例、递进等连接关系，确认每段在全文中的功能。</li><li><strong>拆解长句</strong>：先找主干主谓宾，再处理从句、非谓语、同位语和插入成分。</li><li><strong>原文定位作答</strong>：题干关键词回到原文，答案必须同时满足语义、语法和上下文。</li><li><strong>用译文复盘</strong>：做完再展开课件译文与答案；对照错题记录是词汇、结构还是逻辑定位失误。</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>标题定向，段首定位；主干先行，修饰后理；题回原文，证据唯一；译文复盘，错因归类。</strong></p></div><h2 id="篇章索引" tabindex="-1"><a class="header-anchor" href="#篇章索引"><span>篇章索引</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 篇章索引</p><ul><li><strong>目标</strong>：把 15 篇按题材与体裁过一遍，建立「标题→体裁→读法」的对应：记叙文抓过程线，说明文抓定义与分类，议论文抓作者立场，应用建议类抓小标题与编号。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>通读定主题（标题 + 首段 + 段首句）</code> <code>语境线索：指代、复现、搭配</code></li></ul></div><h3 id="篇章索引-·-小步学" tabindex="-1"><a class="header-anchor" href="#篇章索引-·-小步学"><span>篇章索引 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 0 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>篇章阅读：先抓主线，再拆长句</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>体裁决定读法：15 篇刚好覆盖四种最常考的题材</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li></ol></details><p><strong>自己说一遍</strong>：说出四种体裁各配什么读法，并指出索引表里哪几篇属于同一类；再各举一个「定义句」和「让步句」的句式样子。</p><div class="hint-container tip"><p class="hint-container-title">体裁决定读法：15 篇刚好覆盖四种最常考的题材</p><p><strong>句意</strong>：课件的篇章索引表把 15 篇并排列出：Fall in Love with English、Successful Language Learners、Artificial Satellites、Emily and Innovative Prosthetic Technology、How Junk Food Companies Make Their Products Addictive、The Founding of Subway Sandwich、Vincent van Gogh、Technology and Parental Involvement、Student Cheating、Passenger Pigeons、Guide Dogs for the Mind、Two Kinds of Popularity、A Report Warns of a Global Food Crisis、Smart Buildings Against Earthquakes、Attitudes toward AI in the Workplace。</p><p><strong>拆解</strong></p><ul><li>成长叙事类：Fall in Love with English、Vincent van Gogh、The Founding of Subway Sandwich —— 读时间线（生于何地、何时做了什么、结果如何），考点多在事件先后与人物身份</li><li>学习与教育说明类：Successful Language Learners、Technology and Parental Involvement、Student Cheating —— 读分类与建议，考点多在「几点原因/几点建议」的对应</li><li>科技与环保说明类：Artificial Satellites、Emily and Innovative Prosthetic Technology、Smart Buildings Against Earthquakes、Passenger Pigeons、A Report Warns of a Global Food Crisis —— 读定义、原理与数据，考点多在数字与因果关系</li><li>社会观察类：How Junk Food Companies Make Their Products Addictive、Two Kinds of Popularity、Guide Dogs for the Mind、Attitudes toward AI in the Workplace —— 读作者立场与让步，考点多在 however / although 后的真正态度</li></ul><p><strong>语法</strong>：同一体裁的读法固定：记叙文先画时间轴，说明文先划定义句（X is / X refers to / X means），议论文先找立场句与让步句（Although…, 主句才是重点），建议类先数编号（First / Second / Third 与 1. / 2. / 3.）。读法一旦对上体裁，定位速度会明显变快。</p><p>正例：The word business also refers to an organization that provides these goods and services.（定义句，后文解释都围着它转）；Although he is young, he knows a lot about science.（让步句，主句才是作者要说的）；First of all, successful language learners are independent learners.（编号 + 主题句，本段下面都是它的展开） 反例：在说明文里逐词翻译却找不到定义句 ×（漏掉 X refers to 这类骨架句，文章会读成散的）；在议论文里把让步部分当成作者观点 ×（Although 从句是作者承认的对方立场） 适用边界：体裁读法是「先猜后证」的提速工具，不是判决书：同一篇里可能既叙事又说明（Vincent van Gogh 就有梵高生平 + 画作评价两部分），落笔填空前仍要回到具体句子验证一次，不能凭体裁标签直接选答案。</p><p><strong>口诀</strong>：记叙画线，说明划线，议论找立场，建议数编号 —— 四句话对应四种体裁的第一动作。先做第一动作，再进细节，比一上来就逐句翻译省一半时间。</p></div><table><thead><tr><th>Passage</th><th>主题</th><th>Passage</th><th>主题</th></tr></thead><tbody><tr><td>1</td><td>Fall in Love with English</td><td>9</td><td>Student Cheating</td></tr><tr><td>2</td><td>Successful Language Learners</td><td>10</td><td>Passenger Pigeons</td></tr><tr><td>3</td><td>Artificial Satellites</td><td>11</td><td>Guide Dogs for the Mind</td></tr><tr><td>4</td><td>Emily and Innovative Prosthetic Technology</td><td>12</td><td>Two Kinds of Popularity</td></tr><tr><td>5</td><td>How Junk Food Companies Make Their Products Addictive</td><td>13</td><td>A Report Warns of a Global Food Crisis</td></tr><tr><td>6</td><td>The Founding of Subway Sandwich</td><td>14</td><td>Smart Buildings Against Earthquakes</td></tr><tr><td>7</td><td>Vincent van Gogh</td><td>15</td><td>Attitudes toward AI in the Workplace</td></tr><tr><td>8</td><td>Technology and Parental Involvement</td><td></td><td></td></tr></tbody></table><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 易错清单</p><ul><li><strong>目标</strong>：把课件列出的五条高频易错转成可执行的自检动作：三关齐过、先主干后修饰、答案来源要诚实、修订口径要标注、复盘要归因。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>答案三关：语义、语法、上下文</code> <code>原文定位作答（题干关键词回原文，证据唯一）</code></li></ul></div><h3 id="易错清单-·-小步学" tabindex="-1"><a class="header-anchor" href="#易错清单-·-小步学"><span>易错清单 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 0 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>篇章阅读：先抓主线，再拆长句</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>三关齐过：干扰项往往只错一关</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>诚实标注：课件未附答案与最小修订口径</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li></ol></details><p><strong>自己说一遍</strong>：说出答案三关各查什么，并解释「干扰项常常只错一关」是什么意思；再说明本课练习答案的来源标注规则。</p><div class="hint-container tip"><p class="hint-container-title">三关齐过：干扰项往往只错一关</p><p><strong>句意</strong>：He told me that she would catch the early bus. 意思是「他告诉我她会赶早班车」；这一题四个选项分别是 which、whether、why、that，语义都还沾边，但只有 that 能让从句完整、语气成立。</p><p><strong>拆解</strong></p><ul><li>语义关：which 要「哪一个」，从句里没有可选的几项；why 要「为什么」，前文没问原因；whether 要「是否」，句中已经是确定的陈述</li><li>语法关：从句 she would catch the early bus 主谓宾齐全，不缺主语也不缺宾语，因此不能用连接代词</li><li>上下文关：主句 He told me 是陈述转述，后面接事实性内容，用只起连接作用、不充当成分的 that</li><li>三关依次过一遍，四个选项能一次排掉三个，不必靠语感</li></ul><p><strong>语法</strong>：干扰项的常见设计就是「只错一关」：结构对但语义反（however 放错段位）、语义对但语法错（主谓不一致）、语法对但上下文冲突（时态与时间状语打架）。因此每道题都要把三关依次过一遍，只在有时间压力时才允许先过最硬的那一关。</p><p>正例：He told me that she would catch the early bus.（从句完整 + 陈述语气 → that）；I wonder whether he will agree to this plan or not.（与 or not 连用 → whether） 反例：He told me why she would catch the early bus ×（语义关：前文没问原因）；I wonder if he will agree to this plan or not ×（习惯上与 or not 连用更规范的是 whether） 适用边界：三关的优先级不是固定的：时态、主谓一致、从句成分这类硬语法关永远优先；语义与上下文两关在「两个选项都讲得通」时才拿来决胜。把硬关放最后，是很多人时间不够的根源。</p><p><strong>口诀</strong>：先过硬关，再过软关 —— 硬关指时态、语态、主谓一致、从句缺不缺成分；软关指中文译得顺不顺、语气合不合。硬关能定案就别犹豫，软关留给两可时用。</p></div><div class="hint-container tip"><p class="hint-container-title">诚实标注：课件未附答案与最小修订口径</p><p><strong>句意</strong>：本课 15 篇原文、词汇、词组、长句解析与翻译练习都按课件收录；而课堂练习 93 题课件只给了题目，没有给答案——答与解析都是笔记整理补充的。</p><p><strong>拆解</strong></p><ul><li>凡课件未附答案的题，正确项的解析里都写明「来源：课件未附答案，本条为笔记补充解析」，方便你判断这条解析的分量</li><li>个别源题在整理时对明显文字或数值矛盾做了最小修订：例如第 9 篇第 6 题把百分比的增减方向修正为「从 30% 降至 20%」，解析里也标了修订口径</li><li>遇到两个选项都讲得通的情况，解析会在正确项里写「存疑：……」，说明还有哪种理解也成立、本题为什么按课件口径取这个答案</li><li>题干或选项本身残缺的题目不改写、不补造，只按现有文字解析</li></ul><p><strong>语法</strong>：教学补充的底线是「来源可追溯」：课件给的（原文、译文、长句分析、翻译练习）与笔记补的（练习答案、解析、方法）必须分开标注。这样你在复盘时才能分清哪些是权威依据、哪些是可以再讨论的判断。</p><p>正例：The unemployment rate in this district has fallen from 30% to 20% in the past two years.（整理时已修正原题百分比的增减方向）；来源：课件未附答案，本条为笔记补充解析 反例：把笔记补的答案当成课件原答案，遇到矛盾时不敢质疑 ×；两个选项都能讲通却只给一个答案、不提存疑 × 适用边界：「最小修订」只处理明显自相矛盾处（数字方向、明显笔误），不动原文、不改题干结构；凡改动都同时写进题干旁的括注与解析里。不能确定是不是笔误的，一律保留原样并写「存疑」。</p><p><strong>口诀</strong>：课件给的标课件，笔记补的标笔记 —— 看到「来源：课件未附答案」就知道这条解析是整理出来的判断；看到括注里的修订口径，就知道原题这里本来有毛病。</p></div><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p>答案必须同时满足<strong>语义、语法和上下文</strong>三关；题干关键词回原文定位，证据唯一</p></li><li><p>拆长句先找主干主谓宾，再处理从句、非谓语、同位语和插入成分</p></li><li><p>课件未附练习答案，本课答案与解析均为笔记整理补充——先自己判断再对答案</p></li><li><p>个别源题在整理时已对明显文字或数值矛盾做最小修订，并在题干与解析中标明修订口径</p></li><li><p>做完用译文复盘，把错因归类为词汇、结构或逻辑定位失误；每篇完成「词汇 → 原文 → 译文 → 长句 → 练习 → 错因」闭环，不只背孤立答案</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 课堂练习</p><ul><li><strong>目标</strong>：用 15 篇的 93 道课堂练习把本课的语法与词汇考点过一遍：每题先判空（缺什么成分），再过三关（语义、语法、上下文），做完回到该篇的译文与长句分析复盘。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>答案三关：语义、语法、上下文</code> <code>词义猜测：构词与上下文</code> <code>语境线索：指代、复现、搭配</code></li></ul></div><h3 id="课堂练习-·-小步学" tabindex="-1"><a class="header-anchor" href="#课堂练习-·-小步学"><span>课堂练习 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>篇章阅读：先抓主线，再拆长句</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>课堂练习怎么用：先判空，再过三关，最后读译文</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：挑一篇自己错的题最多的 Passage，用一句话说出它的考点归属（从句连接词 / 时态 / 非谓语 / 虚拟 / 倒装 / 主谓一致 / 词义辨析），并说出那道错题错在哪一关。</p><div class="hint-container tip"><p class="hint-container-title">课堂练习怎么用：先判空，再过三关，最后读译文</p><p><strong>句意</strong>：课件把 15 篇完整篇章配了 93 道课堂练习，每题都给中文提示（如「天太黑了。我分辨不出这是男孩还是女孩。」），做题时先用中文提示确定句意，再回到英文句子判断空处要填什么。</p><p><strong>拆解</strong></p><ul><li>第一步判空：空处缺的是谓语、连词、关系词、非谓语还是词义？缺什么成分决定候选范围</li><li>第二步过三关：语义（中文提示说的是什么意思）、语法（时态、语态、主谓一致、从句成分）、上下文（时间状语、逻辑连词、代词回指）</li><li>第三步读译文：每篇练习之后都有课件原译与长句分析，做完立刻对照，把错题归到词汇、结构、逻辑定位三类</li><li>本课练习覆盖的高频考点依次是：从句连接词与关系词、比较级、时态（含完成时与完成进行时）、非谓语、虚拟语气、倒装、主谓一致、词语辨析</li></ul><p><strong>语法</strong>：本课练习的定位句是「空所在的那一句」，线索全在句内或紧邻处；但做题方法仍走精读五步里的定位与复盘两步。同一篇里的题目按考点扎堆出现（如第 3 篇 6 题全考现在完成时、第 9 篇 6 题全考完成时与完成进行时），做完一篇就顺手把该考点归纳成一句话，比零散记答案有效。</p><p>正例：第 3 篇集中考现在完成时：has gone to / has been to、since 从句、in the past two years、for + 延续性动词；第 9 篇集中考完成时与完成进行时：for months → has been preparing；so far → have seen；第 12 篇集中考倒装与主谓一致：Not until…did I realize、Only with hard work can you…、the number of…was 反例：逐题孤立记答案，不看同篇考点 ×（换个句子又不会）；只看语法不看语义：The book tells us about the author&#39;s life as well as about his writings 里填 also ×（also 是副词，不能连接两个并列的 about 短语） 适用边界：「同篇考点扎堆」是本课练习的编排特点，不是英语本身的规律。做熟之后要能反过来：拿到一个新的句子，先判考什么，再调对应的方法，而不是等考点摆好队。</p><p><strong>口诀</strong>：先判空，再过三关，最后读译文 —— 判空决定候选范围，三关决定最终选项，译文决定这次错误该归到哪一类。三步都做完才算真正做完一道题。</p></div><p>以下 15 篇英文原文全部按课件收录（部分图片型页面已逐页视觉核对后转录）。每篇结构固定：原文 → 中文译文（课件原译，折叠区）→ 词汇 / 词组 → 长句分析（课件原解析）→ 课堂练习 → 翻译练习（课件原题与原译）。课堂练习为课件原题，课件未附答案，答案与解析为笔记整理补充。</p><h3 id="passage-1-·-fall-in-love-with-english-教材-p5" tabindex="-1"><a class="header-anchor" href="#passage-1-·-fall-in-love-with-english-教材-p5"><span>Passage 1 · Fall in Love with English（教材 P5）</span></a></h3><p>Li Hua, a high-school student, was tired of his parents&#39; constant nagging about his English learning. Every day, they would remind him to recite words, practice grammar, and do more exercises. This made Li Hua feel stressed and rebellious. In class, he found it hard to concentrate. The long lists of grammar rules seemed like a jumbled mess in his head, and new words slipped from his memory as soon as he learned them. His English teacher, due to the large class size, couldn&#39;t pay enough attention to his individual problems. As a result, his test scores were disappointing, which further frustrated him.</p><p>One day, his close friend Wang Tao noticed his low spirits. Wang Tao, who was good at English, decided to have a heart-to-heart talk with him. Wang Tao said, &quot;Li Hua, I know you&#39;re struggling with English, but don&#39;t worry. English is not just about boring rules. It&#39;s like a window to a whole new world. We can learn about different cultures, watch amazing movies, and read interesting stories in English.&quot; He then shared some of his own learning tips. &quot;First, try to find English materials that you&#39;re really interested in. For example, if you like science fiction, read English science-fiction novels. Second, make learning a habit. Set aside a little time each day, like 30 minutes, to practice English. It could be reading a short passage, listening to an English song, or watching a short video. Third, don&#39;t be afraid to make mistakes. Every mistake is a chance to learn and improve.&quot;</p><p>Inspired by Wang Tao&#39;s words, Li Hua started to change his learning methods. He downloaded some English podcasts about his favorite topics, such as basketball and astronomy. He also joined an English-learning club at school, where he could communicate with other students in English. Slowly, he found that English was becoming more and more interesting. He could understand the lyrics of his favorite English songs, and he even started to write short stories in English. As time went by, his English improved significantly. He was no longer afraid of English tests, and his scores gradually rose. More importantly, he had truly fallen in love with English, seeing it as a key to unlocking a wealth of knowledge and fun.</p><details class="hint-container details"><summary>展开课件中文译文 · 爱上英语</summary><p>李华是一名高中生，他对父母总是唠叨他学英语感到厌烦。每天，他们都会提醒他背单词、练习语法、多做习题。这让李华感到压力很大，还产生了逆反心理。在课堂上，他很难集中注意力。一长串的语法规则在他脑子里就像一团乱麻，新学的单词他转眼就忘。由于班级人数太多，英语老师无法充分关注他的个人问题。结果，他的考试成绩很不理想，这让他愈发沮丧。</p><p>有一天，他的好朋友王涛注意到他情绪低落。王涛英语很好，决定和他促膝长谈。王涛说：“李华，我知道你在英语学习上很吃力，但别担心。英语不只是枯燥的规则。它就像一扇通往全新世界的窗户。我们可以通过英语了解不同的文化，看精彩的电影，读有趣的故事。”然后他分享了一些自己的学习小贴士。“首先，试着找一些你真正感兴趣的英语材料。比如，如果你喜欢科幻小说，就去读英语科幻小说。其次，养成学习的习惯。每天留出一点时间，比如 30 分钟来练习英语。可以是读一小段文章、听一首英文歌或者看一段短视频。第三，别怕犯错。每一个错误都是学习和提高的机会。”</p><p>受王涛的话启发，李华开始改变学习方法。他下载了一些关于自己喜欢的话题，比如篮球和天文学的英语播客。他还加入了学校的英语学习俱乐部，在那里他可以和其他同学用英语交流。慢慢地，他发现英语变得越来越有趣。他能听懂自己喜欢的英文歌的歌词了，甚至开始用英语写短篇小说。随着时间的推移，他的英语水平显著提高。他不再害怕英语考试，成绩也逐渐提升。更重要的是，他真正爱上了英语，把它视为开启知识与乐趣宝库的一把钥匙。</p></details><p><strong>词汇</strong>：nagging（唠叨；nag 的现在分词）· recite（背诵；朗诵）· rebellious（叛逆的；反抗的）· concentrate（集中注意力）· jumbled（混乱的；杂乱的）· frustrated（沮丧的；挫败的）· heart-to-heart（坦率的；诚恳的）· articulate（善于表达的；口才好的）· insight（洞察力；领悟）· profound（深刻的；意义深远的）</p><p><strong>词组</strong>：be tired of（厌烦；厌倦）· slip from one&#39;s memory（从记忆中消失）· pay attention to（注意；重视）· have a heart-to-heart talk with（与……坦诚交谈）· set aside（留出；拨出）· make mistakes（犯错）· fall in love with（爱上）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>Li Hua, <strong>a high-school student</strong>, was tired of his parents&#39; constant nagging about his English learning. —— Li Hua 是主语；a high-school student 是同位语；was tired of 是谓语部分；his parents&#39; constant nagging about his English learning 是宾语。</p></li><li><p>He then shared some of his own learning tips, <strong>saying</strong>, &quot;First, try to find English materials <strong>that you&#39;re really interested in</strong>.&quot; —— saying… 是现在分词短语作伴随状语；其中 that you&#39;re really interested in 是定语从句，修饰先行词 English materials。</p></li><li><p>More importantly, he had truly fallen in love with English, <strong>seeing it as a key to unlocking a wealth of knowledge and fun</strong>. —— More importantly 是插入语；seeing it as… 是现在分词短语作伴随状语。</p></li></ol></div><p><strong>It is so dark. I can’t find out ______ it’s a boy ______ a girl. （天太黑了。我分辨不出这是男孩还是女孩。）</strong></p><ul><li>A. if, and</li><li>B. that, and</li><li>C. either, or</li><li>D. whether, or</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（whether, or）</strong> —— whether…or… 是「是……还是……」的固定搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ if 可以表「是否」，但不能与 and 搭配构成选择；if ... and ... 既无此结构，也与「是男孩还是女孩」的句意不符。干扰点：只记住 if 能引导「是否」宾语从句。</li><li>B ❌ that 引导的是陈述事实，而这里是要在两个选项之间做选择，语义冲突。</li><li>C ❌ either ... or ... 是并列连词，连接两个对等的词或短语，不能引导整个宾语从句，位置和词性都不对。干扰点：中文都是「或」，容易与 whether 混。</li><li>D ✅ whether ... or ... 是固定搭配，引导宾语从句表示「是……还是……」（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：天太黑了。我分辨不出这是男孩还是女孩。</p><p><strong>词组</strong>：<code>find out</code> 查明；弄清楚；<code>whether ... or ...</code> 是……还是……（引导名词性从句表选择）</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 1 · Fall in Love with English / 课堂练习第 1 题（单句语法题，空所在句））：It is so dark. I can’t find out ______ it’s a boy ______ a girl.</p></details><p><strong>Could you tell me if he ______ to Shanghai? （你能告诉我他是否已经去上海了吗？）</strong></p><ul><li>A. has gone</li><li>B. had gone</li><li>C. went</li><li>D. go</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（has gone）</strong> —— has gone to 表示「已经去了某地，目前尚未回来」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 已经去了上海、人还没回来，用 has gone to；宾语从句用陈述语序，主语 he 用单数（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ had gone 是过去完成时，需要「过去的过去」的参照点；主句 Could you tell me 是现在的请求，没有过去参照时间。干扰点：只看到 could 就误判为过去。</li><li>C ❌ went 只说明过去的动作，读不出「去了、现在还没回来」的结果义。</li><li>D ❌ go 是原形，主语 he 单数不能配；而且一般现在时与「已经去」的时间关系不符。</li></ul><p><strong>整句翻译</strong>：你能告诉我他是否已经去上海了吗？</p><p><strong>词组</strong>：<code>has gone to</code> 已经去了某地（人不在说话处，尚未回来）；<code>have been to</code> 去过某地（已经回来）</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 1 · Fall in Love with English / 课堂练习第 2 题（单句语法题，空所在句））：Could you tell me if he ______ to Shanghai?</p></details><p><strong>He told me ______ she would catch the early bus. （他告诉我她会赶早班车。）</strong></p><ul><li>A. which</li><li>B. whether</li><li>C. why</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（that）</strong> —— 从句成分完整且表达陈述事实，用连接词 that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 表「哪一个」，从句里没有可选择的几项，且 which 要充当主语或定语，此处不缺。</li><li>B ❌ whether 表「是否」，而句中「她会赶早班车」是确定的陈述，不是疑问。干扰点：把「他告诉我」错读成「他问我」。</li><li>C ❌ why 表原因，从句里没有交代为什么，前文也没有问原因。</li><li>D ✅ 从句 she would catch the early bus 主谓宾完整，且是陈述事实，用只起连接作用、不充当成分的 that（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：他告诉我她会赶早班车。</p><p><strong>词组</strong>：<code>catch the early bus</code> 赶早班车；<code>tell sb. (that) ...</code> 告诉某人（某事），that 引导陈述性宾语从句</p><p><strong>原文定位</strong>（Passage 1 · Fall in Love with English / 课堂练习第 3 题（单句语法题，空所在句））：He told me ______ she would catch the early bus.</p></details><p><strong>Mrs. Green asked me ______ I would go with her. （格林太太问她为什么要和她一起去。）</strong></p><ul><li>A. what</li><li>B. which</li><li>C. why</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（why）</strong> —— 选项中只有 why 能在从句中作原因状语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 要在从句中充当主语或宾语，而 I would go with her 成分完整，缺的只是原因状语。</li><li>B ❌ which 表「哪一个」，从句里没有可选项；同样也不能只作状语。</li><li>C ✅ 只有 why 能在从句中作原因状语，与中文「为什么和她一起去」对应（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ that 不能引导疑问；而且主句 asked 表提问，后面不能用陈述连接词。</li></ul><p><strong>整句翻译</strong>：格林太太问我为什么要和她一起去。</p><p><strong>词组</strong>：<code>go with sb.</code> 和某人一起去；<code>ask sb. sth.</code> 问某人某事，后接疑问性宾语从句</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 1 · Fall in Love with English / 课堂练习第 4 题（单句语法题，空所在句））：Mrs. Green asked me ______ I would go with her.</p></details><p><strong>I don’t know ______ the coat ______ cheap enough. （我不知道这件外套是否足够便宜。）</strong></p><ul><li>A. if, is</li><li>B. where, were</li><li>C. that, was</li><li>D. if, were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（if, is）</strong> —— if 表示「是否」；主语 the coat 为单数，系动词用 is。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ if 在此表「是否」；从句主语 the coat 是单数，一般现在时用 is（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ where 表地点，句中没有地点含义；were 也不配单数主语。</li><li>C ❌ that 不能表「是否」；而且 was 与「这件外套是否够便宜」的现在时描述不符。</li><li>D ❌ if 选对了，但 were 是复数或虚拟形式的过去式，主语 the coat 单数、时态也只允许 is。干扰点：只挑对了连词，漏掉主谓一致。</li></ul><p><strong>整句翻译</strong>：我不知道这件外套是否足够便宜。</p><p><strong>词组</strong>：<code>cheap enough</code> 足够便宜（enough 放在形容词之后）；<code>if 引导宾语从句</code> 表「是否」，从句用陈述语序</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 1 · Fall in Love with English / 课堂练习第 5 题（单句语法题，空所在句））：I don’t know ______ the coat ______ cheap enough.</p></details><p><strong>—Linda, could you tell me something about Mo Yan? —Sure. He is the writer ______ won the Nobel Literature Prize. （他就是获得诺贝尔文学奖的作家。）</strong></p><ul><li>A. which</li><li>B. whose</li><li>C. who</li><li>D. whom</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（who）</strong> —— 先行词 the writer 指人，关系词在从句中作主语，用 who。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 只能指物，先行词 the writer 是人。干扰点：看到「作家」后面的从句就不再核对先行词的人/物属性。</li><li>B ❌ whose 表所属，后面要接名词（whose book），而空处后是谓语 won。</li><li>C ✅ 先行词 the writer 指人，关系词在从句中作主语，用 who（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ whom 只能在从句中作宾语，而 won 后面已经有宾语 the Nobel Literature Prize。</li></ul><p><strong>整句翻译</strong>：——琳达，能给我讲讲莫言吗？——当然。他就是获得诺贝尔文学奖的那位作家。</p><p><strong>词组</strong>：<code>the Nobel Literature Prize</code> 诺贝尔文学奖；<code>the writer who won ...</code> 获奖的那位作家（who 在定语从句中作主语）</p><p><strong>原文定位</strong>（Passage 1 · Fall in Love with English / 课堂练习第 6 题（单句语法题，空所在句））：He is the writer ______ won the Nobel Literature Prize.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>Every day, they would remind him to recite words, practice grammar, and do more exercises. 译：每天，他们会提醒他背单词，练习语法，做更多的练习。</p></li><li><p>More importantly, he had truly fallen in love with English, seeing it as a key to unlocking a wealth of knowledge and fun. 译：更重要的是，他真的爱上了英语，把它视为开启丰富知识和乐趣的钥匙。</p></li></ol></div><h3 id="passage-2-·-successful-language-learners-教材-p9-12-练习册-p56-57" tabindex="-1"><a class="header-anchor" href="#passage-2-·-successful-language-learners-教材-p9-12-练习册-p56-57"><span>Passage 2 · Successful Language Learners（教材 P9-12；练习册 P56-57）</span></a></h3><p>If we take a close look at successful language learners, we may discover a few techniques which make language learning easier for them.</p><p>First of all, successful language learners are independent learners. They do not rely on books or teachers; they discover their own way to learn the language. Instead of waiting for the teacher to explain everything, they try to find the patterns and the rules for themselves. They are good guessers who look for clues and form their own conclusions.</p><p>Successful language learning is active learning. Therefore, successful learners do not wait for a chance to use the language; they look for such a chance. They find people who speak the language and ask these people to correct them when they make a mistake. They will try anything to communicate. When communication is difficult, they can accept information that is inexact or incomplete. It is more important for them to learn to think in the language than to know the meaning of every word.</p><p>Finally, successful language learners are learners with a purpose. They want to learn the language because they are interested in the language and the people who speak it. It is necessary for them to learn the language in order to communicate with these people and to learn from them.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>如果我们仔细观察成功的语言学习者，可能会发现一些能让他们的语言学习变得更轻松的方法。</p><p>首先，成功的语言学习者是自主学习者。他们不依赖书本或老师；而是探索自己的语言学习方式。他们不会等着老师解释所有内容，而是努力自己去寻找规律和规则。他们是善于猜测的人，会寻找线索并形成自己的结论。</p><p>成功的语言学习是主动学习。因此，成功的学习者不会等待使用语言的机会，而是主动寻找这样的机会。他们会找到说这种语言的人，并在自己犯错时请这些人纠正自己。为了交流，他们愿意尝试任何方法。当交流有困难时，他们能够接受不准确或不完整的信息。对他们而言，学会用这种语言思考比知道每个单词的意思更重要。</p><p>最后，成功的语言学习者是有明确目的的学习者。他们想要学习这种语言，是因为对这种语言以及说这种语言的人感兴趣。对他们来说，学习这种语言是必要的，以便与这些人交流并向他们学习。</p></details><p><strong>词汇</strong>：discover（发现；发觉）· technique（技巧；技术；手法）· successful（成功的）· explain（说明；解释）· conclusion（结论；推论）· purpose（目的；用途）· meaning（含义；意图）· communicate（传达；交流）</p><p><strong>词组</strong>：first of all（首先）· rely on（依赖；依靠）· instead of（代替；而不是）· wait for（等待）· look for（寻找）· be interested in（对……感兴趣）· in order to（为了）· communicate with（和……交流）· learn from（向……学习）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>If we take a close look at successful language learners, we may discover a few techniques <strong>which make language learning easier for them</strong>. —— 这是 if 引导的条件状语从句；which make language learning easier for them 是定语从句，修饰 techniques。</p></li><li><p>They find people <strong>who speak the language</strong> and ask these people to correct them <strong>when they make a mistake</strong>. —— who speak the language 是定语从句，修饰先行词 people，关系代词 who 作主语；when they make a mistake 是时间状语从句，修饰第二个谓语动词 ask。</p></li><li><p><strong>It</strong> is more important for them <strong>to learn to think in the language</strong> than to know the meaning of every word. —— 句型为 It is + 形容词 + for sb. + to do sth.；It 是形式主语，真正的主语是 to learn to think in the language，可避免句子头重脚轻；比较级结构比较两者的重要性。</p></li></ol></div><p><strong>These children are ______ this year than they were last year. （这些孩子今年比去年高。）</strong></p><ul><li>A. more tall</li><li>B. more taller</li><li>C. very taller</li><li>D. much taller</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（much taller）</strong> —— 比较级 taller 可由 much 修饰，不能再用 more。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ tall 是单音节形容词，比较级直接加 -er，不用 more tall。</li><li>B ❌ more 与 -er 不能同时出现，more taller 是双重比较级。干扰点：只记得 more 表比较，忘了单音节词加 -er。</li><li>C ❌ very 不能修饰比较级，只能修饰原级（very tall）。</li><li>D ✅ much 可以直接修饰比较级 taller，表示程度「高得多」（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：这些孩子今年比去年高。</p><p><strong>词组</strong>：<code>much + 比较级</code> ……得多（much 用来修饰比较级）；<code>than they were last year</code> 比他们去年（更高）</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 2 · Successful Language Learners / 课堂练习第 1 题（单句语法题，空所在句））：These children are ______ this year than they were last year.</p></details><p><strong>The experiment was ______ easier than we had expected. （这项实验比我们预想的容易得多。）</strong></p><ul><li>A. more</li><li>B. much more</li><li>C. much</li><li>D. more much</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（much）</strong> —— much 直接修饰比较级 easier。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ easier 已经是比较级，前面再加 more 就成双重比较级。</li><li>B ❌ much more + 原级才是 more 的用法，而这里已经是 easier；more 与 easier 不能叠用。干扰点：把 more 当成程度副词。</li><li>C ✅ much 直接修饰比较级 easier，表示程度（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ more much 语序颠倒，且 much 不修饰 more 这种用法。</li></ul><p><strong>整句翻译</strong>：这项实验比我们预想的容易得多。</p><p><strong>词组</strong>：<code>much easier</code> 容易得多；<code>than we had expected</code> 比我们原先预想的（用过去完成时）</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 2 · Successful Language Learners / 课堂练习第 2 题（单句语法题，空所在句））：The experiment was ______ easier than we had expected.</p></details><p><strong>If there were no examinations, we should have ______ at school. （如果没有考试，我们在学校会过得快乐得多。）</strong></p><ul><li>A. the happiest time</li><li>B. a more happier time</li><li>C. much happiest time</li><li>D. a much happier time</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（a much happier time）</strong> —— a much happier time 中，much 修饰比较级 happier。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ the happiest 是最高级，句中是 if 虚拟条件下「与现在对比」，要用比较级 + than 隐含的对比含义。</li><li>B ❌ more happier 是双重比较级；happy 变比较级是 happier（辅音字母 + y 变 i 加 -er）。</li><li>C ❌ much 不能修饰最高级 happiest；最高级前一般用 the，也不用 much。</li><li>D ✅ a much happier time 中 much 修饰比较级 happier，冠词 a 放在最前（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：如果没有考试，我们在学校会过得快乐得多。</p><p><strong>词组</strong>：<code>if there were no examinations</code> 如果没有考试（与现在事实相反的虚拟条件）；<code>a much happier time</code> 快乐得多的时光</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 2 · Successful Language Learners / 课堂练习第 3 题（单句语法题，空所在句））：If there were no examinations, we should have ______ at school.</p></details><p><strong>This book is ______ that one, but ______ than that one. （这本书和那本书一样难，但比那本书更贵。）</strong></p><ul><li>A. as difficult as; expensive</li><li>B. as more difficult as; more expensive</li><li>C. as difficult as; more expensive</li><li>D. more difficult as; as expensive</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（as difficult as; more expensive）</strong> —— 同级比较用 as difficult as；第二空根据 than 用比较级 more expensive。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空 as difficult as 对，但第二空有 than 就必须用比较级 more expensive，expensive 是原级。干扰点：只改对了一半。</li><li>B ❌ as 与 than 之间只能用原级，as more difficult as 把比较级塞进了同级结构。</li><li>C ✅ 同级比较用 as difficult as；有 than 提示不同级比较，用 more expensive（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ more difficult as 混用了两种结构；第二空 as expensive 缺了与 than 呼应的比较级。</li></ul><p><strong>整句翻译</strong>：这本书和那本书一样难，但比那本书更贵。</p><p><strong>词组</strong>：<code>as + 原级 + as</code> 和……一样（同级比较）；<code>more expensive than</code> 比……更贵（不同级比较用比较级 + than）</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 2 · Successful Language Learners / 课堂练习第 4 题（单句语法题，空所在句））：This book is ______ that one, but ______ than that one.</p></details><p><strong>When we arrived, we found the meeting room crowded with ______ students. （我们到达时，发现会议室里挤满了相当多的学生。）</strong></p><ul><li>A. quite a few</li><li>B. only a few</li><li>C. few</li><li>D. a few quite</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（quite a few）</strong> —— quite a few 表示「相当多的」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ quite a few 表示「相当多的」，与 crowded with（挤满）的程度一致；students 是可数名词复数（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ only a few 表「只有几个」，与 crowded with 的「挤满」矛盾。干扰点：只看 a few 的肯定义，忽略 only 的限制。</li><li>C ❌ few 表否定「几乎没有」，人少就不可能挤满。</li><li>D ❌ a few quite 语序错误，修饰词 quite 要放在 a few 之前构成固定说法 quite a few。</li></ul><p><strong>整句翻译</strong>：我们到达时，发现会议室里挤满了相当多的学生。</p><p><strong>词组</strong>：<code>quite a few</code> 相当多的（修饰可数名词复数）；<code>be crowded with</code> 挤满了……</p><p><strong>原文定位</strong>（Passage 2 · Successful Language Learners / 课堂练习第 5 题（单句语法题，空所在句））：When we arrived, we found the meeting room crowded with ______ students.</p></details><p><strong>______ there by bike will take us half an hour. （骑自行车到那里要花我们半个小时。）</strong></p><ul><li>A. To get</li><li>B. To be gotten</li><li>C. Getting</li><li>D. To be getting</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Getting）</strong> —— 动名词短语 Getting there by bike 作主语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ To get 作主语在语法上可以，但谈「骑自行车去要多久」这种泛指做法，动名词更自然，且本组考点就是动名词作主语。干扰点：不定式与动名词都能作主语。</li><li>B ❌ To be gotten 是被动不定式，「被到达」语义不通，get there 也没有被动用法。</li><li>C ✅ 动名词短语 Getting there by bike 作主语，泛指的出行方式用动名词（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ To be getting 是进行式不定式，结构本身少见，也不能表示「泛指的做法」。</li></ul><p><strong>整句翻译</strong>：骑自行车到那里要花我们半个小时。</p><p><strong>词组</strong>：<code>get there by bike</code> 骑自行车到那里（by + 交通工具）；<code>take sb. some time</code> 花费某人多长时间</p><p><strong>对比自测</strong>：做完后对照 quiz-p2:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 2 · Successful Language Learners / 课堂练习第 6 题（单句语法题，空所在句））：______ there by bike will take us half an hour.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>If we take a close look at successful language learners, we may discover a few techniques which make language learning easier for them. 译：如果我们仔细观察成功的语言学习者，我们可能会发现一些让他们学习语言更容易的技巧。</p></li><li><p>When communication is difficult, they can accept information that is inexact or incomplete. 译：当沟通困难时，他们可以接受不准确或不完整的信息。</p></li><li><p>They want to learn the language because they are interested in the language and the people who speak it. 译：他们想学这门语言，因为他们对这门语言和说这门语言的人感兴趣。</p></li><li><p>他们不是等着老师解释所有的事情，而是自己去发现各种模式和规则。 译：Instead of waiting for the teacher to explain everything, they discover all kinds of patterns and rules by themselves.</p></li></ol></div><h3 id="passage-3-·-artificial-satellites-教材-p13-16-练习册-p58" tabindex="-1"><a class="header-anchor" href="#passage-3-·-artificial-satellites-教材-p13-16-练习册-p58"><span>Passage 3 · Artificial Satellites（教材 P13-16；练习册 P58）</span></a></h3><p>Many people dream of exploring the vast universe, and one of the most important tools for this exploration is the artificial satellite. Over the decades, countries around the world have launched countless artificial satellites with the aim of studying the Earth, observing the universe, and facilitating communication. At least several thousand artificial satellites have been sent into space in the pursuit of these scientific and practical goals. The first artificial satellite, Sputnik 1, was the achievement of the Soviet Union. It was successfully launched in 1957, marking a new era in space exploration.</p><p>To make these satellites more efficient and versatile, scientists continuously improve their design and technology. Sputnik 1 was relatively simple in structure, mainly used to transmit radio signals, but it opened the door to a new field.</p><p>Sputnik 1 was not immediately recognized as a revolutionary invention in all aspects at that time, but it served as a significant starting point for the development of space technology. By 1960, many countries began to follow suit and develop their own satellite projects. Scientists used these early satellites to conduct a series of basic space research, such as studying the Earth&#39;s magnetic field and the radiation environment in space. Today, there are thousands of artificial satellites orbiting the Earth, and more than a hundred new satellites are launched into space every year. These satellites are used in various fields, including weather forecasting, navigation, and television broadcasting. Countless scientific papers and reports have been written based on the data collected by these satellites.</p><p>Today, although the initial excitement about the first simple satellites has subsided, the importance of artificial satellites in modern life has become increasingly prominent. Throughout the past few decades, satellite technology has evolved rapidly. It has become an indispensable part of modern society. The fact that more countries are investing in satellite research and development shows that the application of satellite technology is still expanding globally. No one would deny the great value of artificial satellites, but few people think that the original simple satellites like Sputnik 1 are likely to play the same crucial role in the future.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>许多人都梦想探索浩瀚的宇宙，而人造卫星是实现这一探索最重要的工具之一。数十年来，世界各国发射了无数人造卫星，目的是研究地球、观测宇宙并促进通信。为了实现这些科学和实用目标，至少已有数千颗人造卫星被送入太空。第一颗人造卫星“斯普特尼克 1 号”是苏联的成果，它于 1957 年成功发射，标志着太空探索迈入新纪元。</p><p>为了让这些卫星更高效、功能更全面，科学家们不断改进其设计与技术。“斯普特尼克 1 号”的结构相对简单，主要用于传输无线电信号，但它为（太空探索的）新领域打开了大门。</p><p>当时，“斯普特尼克 1 号”并未立即被视为在各方面都具有革命性的发明，但它成为了空间技术发展的重要起点。到 1960 年，许多国家开始效仿，开发本国的卫星项目。科学家们利用这些早期卫星开展了一系列基础空间研究，例如研究地球磁场和太空辐射环境。如今，有成千上万颗人造卫星环绕地球运行，每年还有超 100 颗新卫星被送入太空。这些卫星被应用于多个领域，包括天气预报、导航和电视广播。无数科学论文与报告都基于这些卫星收集的数据撰写而成。</p><p>如今，尽管人们对最初那些简单卫星的兴奋感已逐渐消退，但人造卫星在现代生活中的重要性却日益凸显。在过去几十年间，卫星技术发展迅猛，已成为现代社会不可或缺的一部分。越来越多的国家投身卫星研发的事实表明，卫星技术的应用在全球范围内仍在拓展。没有人会否认人造卫星的巨大价值，但很少有人认为像“斯普特尼克 1 号”这样最初的简单卫星在未来还能发挥同等关键的作用。</p></details><p><strong>词汇</strong>：vast（广阔的；浩瀚空间）· universe（宇宙）· artificial（人造的）· satellite（卫星；人造卫星）· decade（十年）· launch（发射；发起）· countless（无数的）· pursuit（追赶；追求）· achievement（成就）· revolutionary（革命的；大变革的）· efficient（有效率的）· versatile（多才多艺的；通用的）· transmit（传输；传播；发射）· orbit（轨道；绕轨道运行）· forecast（预测；预报）· navigation（航行；航海）· indispensable（不可缺少的）</p><p><strong>词组</strong>：dream of（梦想；梦见）· aim of（目的在于；旨在）· send into（把……送进）· in the pursuit of（追求；寻求）· open the door to（给……机会）· follow suit（跟着做；学样）· a series of（一系列的）· based on（以……为基础；基于）· invest in（投资于；投入）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>At least several thousand artificial satellites <strong>have been sent</strong> into space in the pursuit of these scientific and practical goals. —— in the pursuit of 意为“追求”；have been sent 是现在完成时的被动语态，表示“已经被……”。</p></li><li><p>Many people dream of <strong>exploring</strong> the vast universe, and one of the most important tools for this exploration is the artificial satellite. —— 并列连词 and 连接两个独立分句；介词 of 后接动名词短语作宾语；后半句使用 one of + 复数名词 结构。</p></li><li><p><strong>The fact that</strong> more countries are investing in satellite research and development shows <strong>that</strong> the application of satellite technology is still expanding globally. —— that more countries are investing… 是同位语从句，解释 The fact，其中 that 不充当成分、不可省略；谓语 shows 后接 that 引导的宾语从句，其中 that 可省略。</p></li></ol></div><p><strong>—Where is your father? I haven’t seen him for a long time. —He ______ Shanghai on business. He will be back in a week.</strong></p><ul><li>A. has been to</li><li>B. has gone to</li><li>C. went to</li><li>D. goes to</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（has gone to）</strong> —— 人去了上海且尚未回来，用 has gone to。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ has been to 表示「去过并已回来」，与后句 He will be back in a week（一周后才回来）矛盾。干扰点：中文都说「去上海」，分不清去与回。</li><li>B ✅ 人去了上海、现在不在这里、还没回来 → has gone to；后句 He will be back 正是「未归」的旁证（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ went to 只交代过去动作，不能说明「现在不在本地」这一结果。</li><li>D ❌ goes to 是一般现在时表习惯，与「出差去了、一周后回」的一次性事件不符。</li></ul><p><strong>整句翻译</strong>：——你父亲在哪儿？我很久没见到他了。——他出差去上海了。一周后回来。</p><p><strong>词组</strong>：<code>on business</code> 出差（公干）；<code>be back</code> 回来</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 3 · Artificial Satellites / 课堂练习第 1 题（单句语法题，空所在句））：—He ______ Shanghai on business. He will be back in a week.</p></details><p><strong>My sister ______ the piano since she was five years old. Now she’s very good at it.</strong></p><ul><li>A. played</li><li>B. will play</li><li>C. has played</li><li>D. is playing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（has played）</strong> —— since 引出的时间状语要求主句用现在完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ played 只说明过去，读不出「从五岁一直弹到现在」的延续义。</li><li>B ❌ will play 表将来，与 since 引出的「从过去到现在」冲突。</li><li>C ✅ since 引出的时间状语要求主句用现在完成时：has played since she was five（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ is playing 表此刻正在进行，不能表示延续多年的经历。干扰点：被 Now she&#39;s very good at it 误导成「现在」，但那是旁证不是主句时态依据。</li></ul><p><strong>整句翻译</strong>：我妹妹从五岁起就弹钢琴。现在她弹得很好。</p><p><strong>词组</strong>：<code>since she was five years old</code> 从她五岁起（since 从句用一般过去时）；<code>be good at</code> 擅长</p><p><strong>原文定位</strong>（Passage 3 · Artificial Satellites / 课堂练习第 2 题（单句语法题，空所在句））：My sister ______ the piano since she was five years old.</p></details><p><strong>—______ you ever ______ to the Great Wall? —Yes, I have. I went there last year.</strong></p><ul><li>A. Have; gone</li><li>B. Have; been</li><li>C. Did; go</li><li>D. Will; go</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（Have; been）</strong> —— have been to 表示「去过并已回来」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Have; gone 是「去了（还没回来）」，而答句 I went there last year 说明人已经去过并回来了。</li><li>B ✅ ever 提问经历，用 have been to；答句 I went there last year 是过去具体时间，用一般过去时，二者正好呼应（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ Did; go 是过去时提问，但 ever 问的是「到现在为止的经历」，一般与现在完成时连用。</li><li>D ❌ Will; go 表将来，答句却是 last year 的过去事实。</li></ul><p><strong>整句翻译</strong>：——你去过长城吗？——去过。我去年去了那儿。</p><p><strong>词组</strong>：<code>have been to</code> 去过某地（已回来）；<code>go there last year</code> 去年去那儿（与现在完成时对照的一般过去时）</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 3 · Artificial Satellites / 课堂练习第 3 题（单句语法题，空所在句））：—______ you ever ______ to the Great Wall? —Yes, I have. I went there last year.</p></details><p><strong>I ______ my homework. I’m ready to go out and play football.</strong></p><ul><li>A. finish</li><li>B. finished</li><li>C. will finish</li><li>D. have finished</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（have finished）</strong> —— 作业已经完成且结果影响现在，用现在完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ finish 只是一般现在时，读不出「已经做完」的结果义。</li><li>B ❌ finished 只说明过去做过，与「现在可以出去踢球」的结果关联弱。干扰点：事情确实发生在过去，但句子强调的是对现在的影响。</li><li>C ❌ will finish 表将来，与后半句「已经准备好出去」矛盾。</li><li>D ✅ 作业已完成、结果影响现在（所以能出去玩），用现在完成时 have finished（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：我已经做完作业了。我准备出去踢足球。</p><p><strong>词组</strong>：<code>be ready to do</code> 准备好做某事；<code>finish one&#39;s homework</code> 完成作业</p><p><strong>原文定位</strong>（Passage 3 · Artificial Satellites / 课堂练习第 4 题（单句语法题，空所在句））：I ______ my homework. I’m ready to go out and play football.</p></details><p><strong>The famous writer ______ one new book in the past two years.</strong></p><ul><li>A. is writing</li><li>B. was writing</li><li>C. wrote</li><li>D. has written</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（has written）</strong> —— in the past two years 常与现在完成时连用。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is writing 表此刻正在写，与「两年里写成了一本」不符。</li><li>B ❌ was writing 表过去某段时间正在写，同样没有「已经完成」的结果义。</li><li>C ❌ wrote 只说明过去做过，与 in the past two years 这一「延续到现在」的标志不搭。</li><li>D ✅ in the past two years 是现在完成时的典型标志，表从过去延续到现在期间完成的事（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：这位著名作家在过去两年里写了一本新书。</p><p><strong>词组</strong>：<code>in the past two years</code> 在过去的两年里（现在完成时标志）；<code>one new book</code> 一本新书（数量 + 可数名词单数）</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 3 · Artificial Satellites / 课堂练习第 5 题（单句语法题，空所在句））：The famous writer ______ one new book in the past two years.</p></details><p><strong>—How long ______ you ______ this dictionary? —For two years.</strong></p><ul><li>A. have; bought</li><li>B. have; had</li><li>C. did; buy</li><li>D. do; have</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（have; had）</strong> —— for two years 要与延续性动词搭配，have had 表示「拥有了两年」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ bought 是瞬间动词，不能与 for two years 这样的时间段连用——不能说「买了两年」。干扰点：中文「买两年」说得通，英语不行。</li><li>B ✅ have had 是 have 的完成式，have 表「拥有」是延续性状态，可以持续两年（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ did; buy 是过去时疑问，答句 For two years 是持续时间，两者不对应。</li><li>D ❌ do; have 是一般现在时，不能表示从过去延续到现在的时长。</li></ul><p><strong>整句翻译</strong>：——这本词典你用了多久？——两年了。</p><p><strong>词组</strong>：<code>How long ... ?</code> 多久（问持续时间）；<code>for two years</code> 两年（for + 时间段，要求延续性动词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p3:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 3 · Artificial Satellites / 课堂练习第 6 题（单句语法题，空所在句））：—How long ______ you ______ this dictionary? —For two years.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>Over the decades, countries around the world have launched countless artificial satellites with the aim of studying the Earth, observing the universe, and facilitating communication. 译：几十年来，世界各国以研究地球、观测宇宙、促进通信为目的，发射了无数颗人造卫星。</p></li><li><p>To make these satellites more efficient and versatile, scientists continuously improve their design and technology. 译：为了使这些卫星更加高效和多用途，科学家们不断改进它们的设计和技术。</p></li><li><p>These satellites are used in various fields, including weather forecasting, navigation, and television broadcasting. 译：这些卫星用于各种领域，包括天气预报、导航和电视广播。</p></li></ol></div><h3 id="passage-4-·-emily-and-innovative-prosthetic-technology-教材-p18-21-练习册-p59" tabindex="-1"><a class="header-anchor" href="#passage-4-·-emily-and-innovative-prosthetic-technology-教材-p18-21-练习册-p59"><span>Passage 4 · Emily and Innovative Prosthetic Technology（教材 P18-21；练习册 P59）</span></a></h3><p>Emily is among the &quot;tomorrow&#39;s people&quot; who embrace innovative prosthetic（假肢的）technology to overcome physical limitations. She wears a state-of-the-art prosthetic leg that has changed her life significantly.</p><p>Now, Emily is an active member of her community. She often participates in outdoor activities, like hiking with friends. When she walks on uneven paths, she adjusts her posture with ease. For most people, walking and enjoying nature is a normal part of life. However, three years ago, after a tragic car accident, Emily lost her left leg below the knee, and such activities seemed like distant dreams.</p><p>After the accident, Emily fell into a deep depression. &quot;I felt as if my whole world had collapsed. I couldn&#39;t accept that I would have to live with a disability,&quot; she said. But her strong-willed nature led her to seek solutions. That&#39;s when she learned about advanced prosthetic technology that could provide a more natural walking experience.</p><p>In a challenging surgical procedure, doctors prepared Emily&#39;s residual limb for the prosthetic attachment. Then, a team of engineers and prosthetists customized a prosthetic leg for her. The leg was equipped with sensors that could detect the movements of her muscles and adjust the leg&#39;s movement accordingly. At first, wearing the prosthetic leg was uncomfortable, and she had to relearn basic walking skills. &quot;One month after starting the training, I took my first independent step with the prosthetic leg. It was a moment of great joy,&quot; she remembered. As she continued to practice, the prosthetic leg became more and more integrated with her body.</p><p>Today, Emily&#39;s prosthetic leg has enabled her to lead an almost normal life, but it still has its limitations. For instance, when she tries to run on soft sand, the prosthetic leg doesn&#39;t provide as much stability as a natural leg. Also, during long-term use, she sometimes experiences fatigue in the residual limb. But Emily remains positive. &quot;I&#39;m sure that in the future, prosthetic technology will become even more advanced, and I&#39;ll be able to do everything I want, like dancing and mountain climbing,&quot; she says with determination.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>艾米丽属于那群“走在时代前沿的人”，他们借助创新的假肢技术突破身体的局限。她佩戴着一条最先进的假肢腿，这条腿极大地改变了她的生活。</p><p>如今，艾米丽是社区里的活跃分子。她经常参与户外活动，比如和朋友一起徒步旅行。走在崎岖的小路上时，她能轻松调整姿势。对大多数人而言，走路和享受自然是生活中再平常不过的部分。然而，三年前的一场惨烈车祸让艾米丽失去了左膝以下的小腿，此类活动对她而言曾是遥不可及的梦想。</p><p>车祸后，艾米丽陷入了严重的抑郁。“我感觉整个世界都崩塌了。我无法接受自己要带着残疾生活。”她说道。但她意志坚强的本性驱使她寻找解决方案。就在那时，她了解到先进的假肢技术，这种技术能带来更自然的行走体验。</p><p>在一场颇具挑战性的手术中，医生为艾米丽的残肢做好了安装假肢的准备。随后，一支由工程师和假肢矫形师组成的团队为她定制了一条假肢腿。这条腿配备了传感器，能检测肌肉活动并相应地调整腿部动作。起初，佩戴假肢并不舒适，她不得不重新学习基本的行走技能。“开始训练一个月后，我用假肢迈出了独立的第一步。那是无比喜悦的时刻。”她回忆道。随着不断练习，假肢与她的身体越来越融合。</p><p>如今，假肢让艾米丽过上了近乎正常的生活，但它仍有局限。例如，在松软的沙地上奔跑时，假肢的稳定性远不及天然腿。此外，长期使用后，她的残肢有时会感到疲劳。但艾米丽始终保持乐观：“我坚信未来假肢技术会更先进，我能做任何想做的事，比如跳舞、登山。”她坚定地说道。</p></details><p><strong>词汇</strong>：embrace（拥抱；欣然采纳）· innovative（革新的；创新的）· prosthetic（假体的；替代的）· limitation（限制；局限）· state-of-the-art（最先进的）· significantly（显著地）· uneven（不平坦的；不平衡的）· posture（姿势）· tragic（悲剧的；不幸的）· collapse（倒塌；崩溃）· disability（残疾）· challenging（有挑战性的）· surgical（外科的；手术的）· procedure（程序；步骤）· residual（剩余的；残留的）· attachment（附件；连接物）· engineer（工程师）· prosthetist（修复学家；假肢矫形师）· customize（定做）· sensor（传感器）· detect（察觉；探测）· accordingly（因此；相应地）· fatigue（疲劳）· long-term（长期的）</p><p><strong>词组</strong>：with ease（轻松地）· fall into a deep depression（陷入严重抑郁）· as if（仿佛；好像）· be equipped with（配备有……）· at first（起初）· enable sb. to do sth.（使某人能够做某事）· for instance（例如）· with determination（坚定地）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>For instance, when she tries to run on soft sand, the prosthetic leg <strong>doesn&#39;t provide as much stability as</strong> a natural leg. —— for instance 意为“例如”；not as…as… 意为“不如……”，用于比较。</p></li><li><p>&quot;I&#39;m sure <strong>that</strong> in the future, prosthetic technology will become even more advanced, and I&#39;ll be able to do <strong>everything I want</strong>, like dancing and mountain climbing,&quot; she says with determination. —— 核心结构为 she says…，引号内是直接引语（宾语从句）；I&#39;m sure 后接 that 引导的宾语从句，形成嵌套；everything I want 中 I want 是省略关系代词的定语从句，修饰 everything。</p></li></ol></div><p><strong>Do you know the man ______ is standing over there?</strong></p><ul><li>A. whom</li><li>B. which</li><li>C. who</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（who）</strong> —— 先行词 the man 指人，关系词在从句中作主语，用 who。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ whom 只能作宾语，而从句 is standing over there 缺的是主语。</li><li>B ❌ which 只能指物，先行词 the man 是人。</li><li>C ✅ 先行词 the man 指人、关系词在从句中作主语，用 who（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ what 不能引导定语从句，它本身就等于「the thing that」，前面不能再有先行词。</li></ul><p><strong>整句翻译</strong>：你认识站在那边的那个人吗？</p><p><strong>词组</strong>：<code>standing over there</code> 站在那边（分词短语作后置定语）；<code>the man who ...</code> ……的那个人（who 在从句中作主语）</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 4 · Emily and Innovative Prosthetic Technology / 课堂练习第 1 题（单句语法题，空所在句））：Do you know the man ______ is standing over there?</p></details><p><strong>I will go to bed ______ I finish my homework. （我一做完作业就去睡觉。）</strong></p><ul><li>A. until</li><li>B. as soon as</li><li>C. while</li><li>D. though</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（as soon as）</strong> —— as soon as 表示「一……就……」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ until 表「直到……为止」，与「一做完就睡」的即时感不符。</li><li>B ✅ as soon as 表示「一……就……」，正好对应中文提示（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ while 引导的从句谓语要用延续性动词或进行时，finish homework 是瞬间动作。</li><li>D ❌ though 表让步，与句意没有转折关系。</li></ul><p><strong>整句翻译</strong>：我一做完作业就去睡觉。</p><p><strong>词组</strong>：<code>as soon as</code> 一……就……（引导时间状语从句）；<code>go to bed</code> 上床睡觉（不加 the）</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 4 · Emily and Innovative Prosthetic Technology / 课堂练习第 2 题（单句语法题，空所在句））：I will go to bed ______ I finish my homework.</p></details><p><strong>Could you tell me ______ the nearest bank is? （你能告诉我最近的银行在哪里吗？）</strong></p><ul><li>A. where</li><li>B. what</li><li>C. when</li><li>D. who</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（where）</strong> —— 宾语从句表示地点，用 where。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 从句缺地点状语，用连接副词 where；语序为 where the nearest bank is，用陈述语序（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ what 要在从句中充当主语或宾语，而 the nearest bank is 已经成分完整。</li><li>C ❌ when 表时间，句中没有时间含义。</li><li>D ❌ who 表人，这里问的是地点。干扰点：被中文「在哪里」的疑问语气带偏，以为要倒装。</li></ul><p><strong>整句翻译</strong>：你能告诉我最近的银行在哪里吗？</p><p><strong>词组</strong>：<code>the nearest bank</code> 最近的银行（near 的最高级 nearest）；<code>宾语从句用陈述语序</code> where the nearest bank is，不倒装成 where is the bank</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 4 · Emily and Innovative Prosthetic Technology / 课堂练习第 3 题（单句语法题，空所在句））：Could you tell me ______ the nearest bank is?</p></details><p><strong>The house ______ we bought last year is very big.</strong></p><ul><li>A. who</li><li>B. where</li><li>C. which</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（which）</strong> —— 先行词 the house 指物，关系词在从句中作宾语，用 which。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ who 只能指人，先行词 the house 是物。</li><li>B ❌ where 是关系副词，要求从句不缺主语或宾语；we bought 缺宾语。干扰点：一见 house 就想到「地点 → where」。</li><li>C ✅ 先行词 the house 指物，关系词在从句中作 bought 的宾语，用 which（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ when 表时间，且它要求从句成分完整；这里缺宾语。</li></ul><p><strong>整句翻译</strong>：我们去年买的那栋房子很大。</p><p><strong>词组</strong>：<code>bought last year</code> 去年买的（从句谓语）；<code>the house which we bought</code> 我们买的那栋房子（which 作从句宾语，可省略）</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 4 · Emily and Innovative Prosthetic Technology / 课堂练习第 4 题（单句语法题，空所在句））：The house ______ we bought last year is very big.</p></details><p><strong>She didn’t realize her mistake ______ I told her. （直到我告诉她，她才意识到自己的错误。）</strong></p><ul><li>A. after</li><li>B. until</li><li>C. since</li><li>D. while</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（until）</strong> —— not…until… 表示「直到……才……」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ after 表「在……之后」，读不出「在此之前一直没意识到」的含义。</li><li>B ✅ not ... until ... 是「直到……才……」的固定结构，主句用否定、从句由 until 引导（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ since 表「自从」，要求主句用现在完成时，而主句 didn&#39;t realize 是过去时。</li><li>D ❌ while 表「在……期间」，动作要持续；told her 是瞬间动作。</li></ul><p><strong>整句翻译</strong>：直到我告诉她，她才意识到自己的错误。</p><p><strong>词组</strong>：<code>not ... until ...</code> 直到……才……；<code>realize one&#39;s mistake</code> 意识到自己的错误</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 4 · Emily and Innovative Prosthetic Technology / 课堂练习第 5 题（单句语法题，空所在句））：She didn’t realize her mistake ______ I told her.</p></details><p><strong>I wonder ______ he will come to the party or not.</strong></p><ul><li>A. if</li><li>B. that</li><li>C. whether</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（whether）</strong> —— 与 or not 连用时，用 whether 更规范。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ if 也能表「是否」，但与 or not 直接连用时习惯上用 whether 更规范。干扰点：if 与 whether 的差别只在搭配条件上。</li><li>B ❌ that 不表「是否」，且句中「会来还是不会来」本身是不确定的。</li><li>C ✅ 与 or not 连用表「是否」，用 whether 引导宾语从句（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ what 要在从句中充当主语或宾语，而 he will come to the party 已经完整。</li></ul><p><strong>整句翻译</strong>：我想知道他是否会来参加聚会。</p><p><strong>词组</strong>：<code>whether ... or not</code> 是否……（与 or not 连用时用 whether）；<code>come to the party</code> 来参加聚会</p><p><strong>对比自测</strong>：做完后对照 quiz-p1:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 4 · Emily and Innovative Prosthetic Technology / 课堂练习第 6 题（单句语法题，空所在句））：I wonder ______ he will come to the party or not.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>For most people, walking and enjoying nature is a normal part of life. 译：对大多数人来说，散步和享受大自然是生活的正常组成部分。</p></li><li><p>As she continued to practice, the prosthetic leg became more and more integrated with her body. 译：随着不断地练习，义肢与身体的融合越来越紧密。</p></li></ol></div><h3 id="passage-5-·-how-junk-food-companies-make-their-products-addictive-教材-p23-25-练习册-p60-61" tabindex="-1"><a class="header-anchor" href="#passage-5-·-how-junk-food-companies-make-their-products-addictive-教材-p23-25-练习册-p60-61"><span>Passage 5 · How Junk Food Companies Make Their Products Addictive（教材 P23-25；练习册 P60-61）</span></a></h3><p>Have you ever wondered why it&#39;s so hard to resist that bag of chips or a sugary soda? Many people don&#39;t realize that junk food companies use clever tricks to make their products addictive. When you walk into a supermarket, colorful packaging and catchy slogans draw you in. But what&#39;s really inside these products?</p><p>How do they make junk food addictive? Food companies add high amounts of sugar, salt, and fat to their products. These ingredients activate the reward centers in our brains, making us feel good and crave more. For example, a single can of soda may contain up to 10 teaspoons of sugar, which is much more than our daily recommended limit. Scientists have found that these substances can change the way our brains work, similar to how drugs affect addiction.</p><p>Why do companies do this? The goal of junk food companies is to make you buy more products. By making their food addictive, they ensure customers keep coming back. They also spend billions of dollars on advertising, targeting children and teenagers through cartoons, social media, and sports events. For instance, fast-food chains often offer toys with kids&#39; meals, making unhealthy food more appealing.</p><p>What are the consequences? Consuming too much junk food can lead to serious health problems. Obesity, diabetes, and heart disease are all linked to a diet high in sugar, salt, and fat. Even if you exercise regularly, eating junk food can still harm your body. Many young people don&#39;t think about these risks and continue eating unhealthy snacks, not knowing the long-term damage they&#39;re causing.</p><p>Conclusion: Junk food companies use science and marketing to make their products hard to resist. Your health is valuable, and understanding these tricks can help you make better choices. While junk food may taste good, the danger is that it could harm your body in the long run. It&#39;s important to read labels, limit your intake, and choose healthier alternatives.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>你有没有想过，为什么很难抗拒一包薯片或一瓶含糖汽水？很多人没意识到，垃圾食品公司会用巧妙的手段让产品变得令人上瘾。当你走进超市，色彩缤纷的包装和吸睛的标语会把你“勾”进去。但这些产品里到底藏着什么秘密？</p><p>他们是如何让垃圾食品令人上瘾的？食品公司会在产品中添加大量糖、盐和脂肪。这些成分会激活大脑的“奖励中枢”，让我们产生愉悦感并渴望更多。比如，一罐汽水可能含有多达 10 茶匙的糖，远超每日推荐摄入量。科学家发现，这些物质会改变大脑的运作方式，效果类似于药物成瘾。</p><p>企业为何要这么做？垃圾食品公司的目标很明确：让你买得更多。通过让食品“成瘾”，他们能确保顾客不断回购。此外，他们还在广告上砸下数十亿美元，通过卡通片、社交媒体和体育赛事瞄准儿童和青少年。比如，快餐连锁店常随儿童餐附赠玩具，让不健康的食品对孩子更具吸引力。</p><p>后果是什么？摄入过多垃圾食品会导致严重的健康问题。肥胖、糖尿病和心脏病都与高糖、高盐、高脂肪的饮食密切相关。即使你经常锻炼，吃垃圾食品仍会损害身体。很多年轻人没考虑这些风险，继续吃着不健康的零食，却不知自己正在造成长期伤害。</p><p>结论：垃圾食品公司利用科学和营销手段让产品难以抗拒。你的健康无比宝贵，了解这些“套路”能帮你做出更明智的选择。虽然垃圾食品可能很美味，但长期来看，它会对身体造成伤害。阅读食品标签、控制摄入量、选择更健康的替代品，这些都至关重要。</p></details><p><strong>词汇</strong>：resist（抵制；忍住）· addictive（使人上瘾的）· catchy（易记的；吸引人的）· slogan（标语；口号）· ingredient（成分；原料）· activate（激活）· reward（奖励；回报）· crave（渴望；渴求）· recommended（推荐的）· substance（物质）· obesity（肥胖）· diabetes（糖尿病）· appealing（有吸引力的）· intake（摄入）</p><p><strong>词组</strong>：draw in（吸引；引诱）· up to（多达；达到）· be linked to（与……有关联）· in the long run（从长远来看）· make better choices（做出更好的选择）· limit intake（限制摄入）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>These ingredients activate the reward centers in our brains, <strong>making us feel good and crave more</strong>. —— making us feel good and crave more 是现在分词短语作结果状语，说明“激活大脑奖励中心”产生的结果。</p></li><li><p><strong>Even if</strong> you exercise regularly, <strong>eating junk food</strong> can still harm your body. —— Even if 引导让步状语从句；主句主语为动名词短语 eating junk food，动名词短语可充当主语。</p></li><li><p>Junk food companies use science and marketing <strong>to make their products hard to resist</strong>. —— use sth. to do sth. 表示“利用某物做某事”；make + 宾语 + 宾语补足语 中，their products 是宾语，形容词短语 hard to resist 是宾补。</p></li></ol></div><p><strong>—______ has the 2018 World Cup been on? —For about two weeks. （2018 年世界杯已经举行多久了？——大约两周。）</strong></p><ul><li>A. How soon</li><li>B. How far</li><li>C. How long</li><li>D. How often</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（How long）</strong> —— for about two weeks 表示持续时长，用 How long 提问。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ How soon 问「还要多久才……」，答语应是 in + 一段时间，而不是 For about two weeks。</li><li>B ❌ How far 问距离，答语应是具体的距离。</li><li>C ✅ 答语 For about two weeks 是持续时长，与 How long 对应；问句用现在完成时也印证「持续到现在」（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ How often 问频率，答语应是 twice a week 这类频度表达。</li></ul><p><strong>整句翻译</strong>：——2018 年世界杯已经举行多久了？——大约两周。</p><p><strong>词组</strong>：<code>be on</code> 上映；举行（be on 表活动正在进行）；<code>How long</code> 多久（问持续时间）</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 5 · How Junk Food Companies Make Their Products Addictive / 课堂练习第 1 题（单句语法题，空所在句））：—______ has the 2018 World Cup been on? —For about two weeks.</p></details><p><strong>—______ do you usually go to school, Mary? —By bike. （玛丽，你通常怎样去上学？——骑自行车。）</strong></p><ul><li>A. When</li><li>B. How</li><li>C. Where</li><li>D. Why</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（How）</strong> —— By bike 回答方式，用 How 提问。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ When 问时间，答语应是 at seven 这类时间表达。</li><li>B ✅ 答语 By bike 说明方式，问方式用 How（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ Where 问地点，答语应是 to school 或具体地点。</li><li>D ❌ Why 问原因，答语应是 because 从句。干扰点：How 既能问方式也能问程度，要按答语落在哪一类来定。</li></ul><p><strong>整句翻译</strong>：——玛丽，你通常怎样去上学？——骑自行车。</p><p><strong>词组</strong>：<code>by bike</code> 骑自行车（by + 交通工具，表方式）；<code>go to school</code> 去上学（school 前不加冠词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 5 · How Junk Food Companies Make Their Products Addictive / 课堂练习第 2 题（单句语法题，空所在句））：—______ do you usually go to school, Mary? —By bike.</p></details><p><strong>—______ do you like the Double Eleven Shopping Festival? —I don’t like it because my mother often buys a lot of things we don’t need. （你觉得「双十一」购物节怎么样？）</strong></p><ul><li>A. How</li><li>B. Why</li><li>C. When</li><li>D. Where</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（How）</strong> —— How do you like ...? 意为「你觉得……怎么样？」，与答句的评价相呼应。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ How do you like ... 是「你觉得……怎么样」的固定句型，答句给出评价（我不喜欢），一问一答正好对应（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ Why do you like ... 是「你为什么喜欢」，与答语「我不喜欢」的矛盾答句不搭。</li><li>C ❌ When 问时间，答语应是时间表达，而答句给的是评价与原因。</li><li>D ❌ Where 问地点，答语应是地点，同样对不上。</li></ul><p><strong>整句翻译</strong>：——你觉得「双十一」购物节怎么样？——我不喜欢它，因为我妈妈经常买很多我们不需要的东西。</p><p><strong>词组</strong>：<code>How do you like ... ?</code> 你觉得……怎么样？（问评价）；<code>a lot of things we don&#39;t need</code> 很多我们不需要的东西（定语从句省略 that）</p><p><strong>对比自测</strong>：做完后对照 quiz-p5:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 5 · How Junk Food Companies Make Their Products Addictive / 课堂练习第 3 题（单句语法题，空所在句））：—______ do you like the Double Eleven Shopping Festival? —I don’t like it because my mother often buys a lot of things we don’t need.</p></details><p><strong>Before you start reading, ask yourself ______ you are reading this book. Most people read for two main reasons, pleasure or knowledge. （大多数人阅读有两个主要目的：获得乐趣或知识。）</strong></p><ul><li>A. why</li><li>B. what</li><li>C. where</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（why）</strong> —— 后句给出阅读的两个原因，宾语从句用 why。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 后一句给出阅读的两个原因（pleasure or knowledge），从句缺的正是原因状语，用 why（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ what 要在从句中作主语或宾语，而 you are reading this book 成分完整。</li><li>C ❌ where 表地点，句中没有地点信息。</li><li>D ❌ when 表时间，句中没有时间信息。干扰点：只读前半句，没看后句给出的原因线索。</li></ul><p><strong>整句翻译</strong>：在你开始阅读之前，问问自己为什么要读这本书。大多数人阅读有两个主要目的：乐趣或知识。</p><p><strong>词组</strong>：<code>ask yourself</code> 问问自己；<code>two main reasons, pleasure or knowledge</code> 两个主要原因：乐趣或知识</p><p><strong>原文定位</strong>（Passage 5 · How Junk Food Companies Make Their Products Addictive / 课堂练习第 4 题（单句语法题，空所在句））：Before you start reading, ask yourself ______ you are reading this book. Most people read for two main reasons, pleasure or knowledge.</p></details><p><strong>______ a clock on the desk. It wakes me up every day. （桌上有一个钟，它每天把我叫醒。）</strong></p><ul><li>A. There are</li><li>B. There be</li><li>C. There is</li><li>D. There being</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（There is）</strong> —— 单数主语 a clock 与 There is 搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ There are 接复数名词，而 a clock 是单数。干扰点：只记住 There be 是「有」，没核对后面的名词。</li><li>B ❌ There be 是句型的骨架，be 必须按主语变位，原形不能直接入句。</li><li>C ✅ There be 句型遵循就近原则，后面第一个名词 a clock 是单数，用 There is（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ There being 是非谓语形式，不能作句子谓语；本句需要一个谓语。</li></ul><p><strong>整句翻译</strong>：桌上有一个钟。它每天把我叫醒。</p><p><strong>词组</strong>：<code>There be 句型</code> 某处有某物；be 的单复数与后面第一个名词一致；<code>wake sb. up</code> 把某人叫醒</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 5 · How Junk Food Companies Make Their Products Addictive / 课堂练习第 5 题（单句语法题，空所在句））：______ a clock on the desk. It wakes me up every day.</p></details><p><strong>—Jack is telling everyone he has bought a new car. —Pay no attention to him. He is just ______. （别理他，他只是在炫耀。）</strong></p><ul><li>A. taking off</li><li>B. showing off</li><li>C. driving off</li><li>D. setting off</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（showing off）</strong> —— show off 意为「炫耀」；take off 脱下／起飞，drive off 驾车离开，set off 出发／引爆。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ take off 是「脱下（衣服）」或「（飞机）起飞」，与「逢人就说买了新车」的行为不符。</li><li>B ✅ show off 意为「炫耀」，正对应 He is telling everyone he has bought a new car 与 Pay no attention to him 的语气（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ drive off 是「驾车离开」，句中没有离开的语境。</li><li>D ❌ set off 是「出发」或「引爆」，与炫耀无关。干扰点：四个选项都含 off，只按中文「出发」的模糊印象选错。</li></ul><p><strong>整句翻译</strong>：——杰克逢人就说他买了辆新车。——别理他。他只是在炫耀。</p><p><strong>词组</strong>：<code>show off</code> 炫耀；卖弄；<code>pay no attention to</code> 别理会；不放在心上</p><p><strong>原文定位</strong>（Passage 5 · How Junk Food Companies Make Their Products Addictive / 课堂练习第 6 题（单句语法题，空所在句））：—Pay no attention to him. He is just ______.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>When you walk into a supermarket, colorful packaging and catchy slogans draw you in. 译：当你走进一家超市，五颜六色的包装和朗朗上口的标语吸引着你。</p></li><li><p>For example, a single can of soda may contain up to 10 teaspoons of sugar, which is much more than our daily recommended limit. 译：例如，一罐苏打水可能含有多达 10 茶匙的糖，这远远超过了我们每天的推荐限量。</p></li><li><p>Many young people don&#39;t think about these risks and continue eating unhealthy snacks, not knowing the long-term damage they&#39;re causing. 译：许多年轻人没有考虑到这些风险，继续吃不健康的零食，不知道它们会造成长期损害。</p></li></ol></div><h3 id="passage-6-·-the-founding-of-subway-sandwich-教材-p26-28-练习册-p60、p62" tabindex="-1"><a class="header-anchor" href="#passage-6-·-the-founding-of-subway-sandwich-教材-p26-28-练习册-p60、p62"><span>Passage 6 · The Founding of Subway Sandwich（教材 P26-28；练习册 P60、P62）</span></a></h3><p>It was the summer of 1965. De Luca, then 17, visited Peter Buck, a family friend. Buck asked De Luca about his plans. “I&#39;m going to college, but I need a way to pay for it,” De Luca recalls saying. Buck said, “You should open a sandwich shop.”</p><p>That afternoon, they agreed to be partners. And they set a goal to open 32 stores in ten years. After doing some research, Buck wrote a check for $1,000. De Luca rented a storefront（店面）in Connecticut, and when they couldn&#39;t cover their start-up costs, Buck gave another $1,000.</p><p>But business didn&#39;t go smoothly as they expected. De Luca says, “After six months, we were doing poorly, but we didn&#39;t know how badly because we didn&#39;t have any financial controls.” All he and Buck knew was that their sales were lower than their costs.</p><p>De Luca was managing the store and going to the University of Bridgeport at the same time. Buck was working at his day job as a nuclear physicist in New York. They&#39;d meet on Monday evenings and brainstorm ideas for keeping the business running. “We convinced ourselves to open a second store. We figured we could tell the public, ‘We are so successful: we are opening a second store.’” And they did in the spring of 1966. Still, it was a lot of learning by trial and error. But the partners&#39; learn-as-you-go approach turned out to be their greatest strength. “Every Friday, De Luca would drive around and hand-deliver the checks to pay their suppliers. I drove probably two and a half hours and it wasn&#39;t necessary, but as a result, the suppliers got to know me very well, and the personal relationships established really helped out,” De Luca says.</p><p>And having a goal was also important. “There are so many problems that can get you down. You just have to keep working toward your goal,” Deluca adds. Deluca ended up founding Subway Sandwich, the multimillion-dollar chain restaurant.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>那是 1965 年的夏天。当时 17 岁的德卢卡去拜访家人的朋友彼得·巴克。巴克询问德卢卡他的计划。德卢卡回忆道，自己当时说：“我要去上大学，但我需要一种支付学费的方式。”巴克说：“你应该开一家三明治店。”</p><p>那天下午，他们达成一致，成为合伙人。并且他们设定了一个目标：在十年内开设 32 家门店。在做了一些调研后，巴克开出了一张 1000 美元的支票。德卢卡在康涅狄格州租了一个店面，当他们无法承担创业成本时，巴克又给了 1000 美元。</p><p>但生意并没有像他们预期的那样顺利。德卢卡说：“六个月后，我们的经营状况很糟糕，但我们不知道有多糟，因为我们没有任何财务管控措施。”他和巴克只知道他们的销售额低于成本。</p><p>德卢卡当时一边管理店铺，一边在布里奇波特大学上学。巴克则在纽约从事核物理学家的日常工作。他们会在周一晚上碰面，集思广益，想办法让生意继续运转下去。“我们说服自己开了第二家店。我们想，我们可以告诉公众，‘我们非常成功：我们要开第二家店了。’”他们在 1966 年春天确实这么做了。尽管如此，这仍然是一个不断尝试和犯错的学习过程。但事实证明，这对合伙人边做边学的方法是他们最大的优势。“每个周五，德卢卡都会开车四处奔波，亲手把支票交给供应商，支付货款。我大概开了两个半小时的车，其实没必要这么做，但结果是，供应商们对我非常熟悉，建立起来的私人关系真的帮了大忙。”德卢卡说。</p><p>而且设定目标也很重要。德卢卡补充道：“会有很多问题让你沮丧。你只需要继续朝着目标努力就行。”德卢卡最终创立了赛百味三明治店，这是一家价值数百万美元的连锁餐厅。</p></details><p><strong>词汇</strong>：pay（支付；付）· partner（同伴；合伙人）· recall（记起；回想起）· goal（目标；进球得分）· agree（同意；赞成）· expected（预期要发生的）· financial（财政的；财务的）· smoothly（平稳地；顺利地）· control（控制；管理）· badly（严重地）· manage（管理；处理）· physicist（物理学家）· nuclear（核子的）· convince（坚信；确信；正文 convince oneself 使自己相信）· figure（理解；弄懂）· necessary（必要的）· established（已建立的；确定的）· personal（个人的；私人的）· supplier（供应商）· found（创办；成立）</p><p><strong>词组</strong>：pay for（赔偿；为……付钱）· agree to（同意）· turn out（结果是……；证明是……）· get you down（令人沮丧；让你失望）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>Buck was working at <strong>his day job as a nuclear physicist</strong> in New York. —— work at one&#39;s day job as ... 表示“以……身份从事日常工作”；as a nuclear physicist 说明职业身份。</p></li><li><p><strong>Having a goal</strong> was also important. “There are so many problems <strong>that can get you down</strong>. You just have to keep working toward your goal,” Deluca adds. —— 动名词短语 having a goal 作主语时，谓语动词通常用单数；There be 句型遵循就近原则；that can get you down 是定语从句，修饰 problems；keep doing sth. 表示“持续做某事”。</p></li></ol></div><p><strong>The headmaster wanted the new classroom building ______ as soon as possible. （校长希望尽快把新教学楼建起来。）</strong></p><ul><li>A. to put up</li><li>B. to be put up</li><li>C. to have been put up</li><li>D. being put up</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（to be put up）</strong> —— want + 宾语 + to do；building 与 put up 是被动关系，所以用 to be put up。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ to put up 是主动式，而 building 是被建造的对象。干扰点：只想到 want sb. to do 的主动句式。</li><li>B ✅ want + 宾语 + to do；building 与 put up 是被动关系，用 to be put up（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ to have been put up 是完成被动式，表「已经被建好」，与 as soon as possible（尽快、尚未完成）矛盾。</li><li>D ❌ being put up 是分词的被动进行式，不能作 want 的宾语补足语。</li></ul><p><strong>整句翻译</strong>：校长希望尽快把新教学楼建起来。</p><p><strong>词组</strong>：<code>want sth. to be done</code> 希望某事被做（want + 宾语 + 不定式）；<code>put up</code> 建造；搭起</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 6 · The Founding of Subway Sandwich / 课堂练习第 1 题（单句语法题，空所在句））：The headmaster wanted the new classroom building ______ as soon as possible.</p></details><p><strong>At the shopping-center, he didn’t know what ______ and ______ with an empty bag. （他不知道该买什么，最后空着袋子离开了。）</strong></p><ul><li>A. to buy; leave</li><li>B. to be bought; left</li><li>C. to buy; left</li><li>D. was to buy; leave</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（to buy; left）</strong> —— what to buy 是「疑问词 + 不定式」；第二空与主句谓语 didn’t know 并列叙述过去动作，用 left。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 第一空 what to buy 对，但第二空 leave 是原形；句子叙述过去的动作，要与 didn&#39;t know 一致用 left。干扰点：漏看第一空的转折关系。</li><li>B ❌ to be bought 是被动式，「不知道该被买什么」主被动颠倒。</li><li>C ✅ what to buy 是「疑问词 + 不定式」结构作宾语；第二空与主句谓语 didn&#39;t know 并列叙述过去动作，用 left（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ was to buy 是谓语形式，「不知道什么是要去买」结构崩坏；第二空 leave 又是原形。</li></ul><p><strong>整句翻译</strong>：在购物中心，他不知道该买什么，最后空着袋子离开了。</p><p><strong>词组</strong>：<code>疑问词 + to do</code> what to buy 作 know 的宾语，等于 what he should buy；<code>with an empty bag</code> 带着空袋子（with 复合结构作状语）</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 6 · The Founding of Subway Sandwich / 课堂练习第 2 题（单句语法题，空所在句））：At the shopping-center, he didn’t know what ______ and ______ with an empty bag.</p></details><p><strong>The policeman put down the phone, ______ with a smile on his face. （警察放下电话，脸上带着满意的微笑。）</strong></p><ul><li>A. satisfied</li><li>B. satisfying</li><li>C. to be satisfied</li><li>D. having satisfied</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（satisfied）</strong> —— satisfied 表示人的感受／状态，作伴随状语；此处意为「感到满意地」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ satisfied 表人的感受，作伴随状语说明警察放下电话时的状态（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ satisfying 意为「令人满意的」，用来形容事物；这里说的是警察自己的感受。干扰点：物 -ing / 人 -ed 的分线没落到主语身上。</li><li>C ❌ to be satisfied 是不定式，作状语多表目的或结果，读不出「同时带着微笑」的伴随义。</li><li>D ❌ having satisfied 是完成式，表「已经使别人满意」且先发生，主被动与时间都不对。</li></ul><p><strong>整句翻译</strong>：警察放下电话，脸上带着满意的微笑。</p><p><strong>词组</strong>：<code>put down the phone</code> 放下电话；<code>satisfied</code> 感到满意的（-ed 说明人的感受）</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 6 · The Founding of Subway Sandwich / 课堂练习第 3 题（单句语法题，空所在句））：The policeman put down the phone, ______ with a smile on his face.</p></details><p><strong>______, your composition is full of mistakes. （你的作文写得很粗心，因此满是错误。）</strong></p><ul><li>A. Writing carelessly</li><li>B. Written carelessly</li><li>C. Having written carelessly</li><li>D. Being written carelessly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（Written carelessly）</strong> —— composition 与 write 是被动关系，用过去分词 Written carelessly 作条件／方式状语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Writing carelessly 是主动式，逻辑主语会是 your composition，而作文不会自己「写」。</li><li>B ✅ composition 与 write 是被动关系，用过去分词 Written carelessly 作原因／方式状语（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ Having written carelessly 是主动完成式，同样把主被动弄反。</li><li>D ❌ Being written carelessly 是被动进行式，表「正在被写」，与「满是错误」这一已完成的结果不符。</li></ul><p><strong>整句翻译</strong>：你的作文写得很粗心，因此满是错误。</p><p><strong>词组</strong>：<code>be full of</code> 充满；<code>written carelessly</code> （被）写得很粗心（过去分词作原因状语）</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 6 · The Founding of Subway Sandwich / 课堂练习第 4 题（单句语法题，空所在句））：______, your composition is full of mistakes.</p></details><p><strong>She made a candle ______ us light. （她做了一支蜡烛给我们照明。）</strong></p><ul><li>A. give</li><li>B. gave</li><li>C. to give</li><li>D. given</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（give）</strong> —— make + 宾语 + 动词原形，用 give 作宾补。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ make + 宾语 + 宾语补足语，三使之一 make 后接省 to 的不定式，用 give（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ gave 是过去式谓语，句中已有谓语 made，一句不能有两个谓语。干扰点：看到「做了蜡烛」就顺着过去时接 gave。</li><li>C ❌ to give 多了 to：make、let、have、感官动词后的宾补一律省 to。</li><li>D ❌ given 是过去分词，表被动；蜡烛是主动提供光，不是被提供。</li></ul><p><strong>整句翻译</strong>：她做了一支蜡烛给我们照明。</p><p><strong>词组</strong>：<code>make sb./sth. do sth.</code> 使某人／某物做某事（使役动词后省 to）；<code>give us light</code> 给我们光明／照明</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 6 · The Founding of Subway Sandwich / 课堂练习第 5 题（单句语法题，空所在句））：She made a candle ______ us light.</p></details><p><strong>The stranger you saw ______ with a big travelling-bag stayed in Room 104 yesterday. （你看见的那个提着大旅行包进来的陌生人，昨天住在 104 房间。）</strong></p><ul><li>A. to come in</li><li>B. come in</li><li>C. has come in</li><li>D. who came in</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（who came in）</strong> —— 主干是 The stranger ... stayed ...；you saw 和 who came in with ... 都修饰 stranger，后者需用关系代词 who 引导。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ to come in 是不定式，不能跟在 you saw 后面构成完整修饰，且与 stayed 的时间关系不明。</li><li>B ❌ come in 少了关系词；you saw 后直接接 come in 会被读成省 to 的宾补，无法表达「进来的那个」。</li><li>C ❌ has come in 是谓语形式，句中已有 stayed，且与 yesterday 的时态不搭。</li><li>D ✅ 主干是 The stranger ... stayed in Room 104；you saw 与 who came in with a big travelling-bag 都修饰 stranger，后者需要关系代词 who 引导（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：你看见的那个提着大旅行包进来的陌生人，昨天住在 104 房间。</p><p><strong>词组</strong>：<code>travel with a big travelling-bag</code> 带着大旅行包旅行；<code>stay in Room 104</code> 住在 104 房间</p><p><strong>原文定位</strong>（Passage 6 · The Founding of Subway Sandwich / 课堂练习第 6 题（单句语法题，空所在句））：The stranger you saw ______ with a big travelling-bag stayed in Room 104 yesterday.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>After doing some research, Buck wrote a check for $1,000. De Luca rented a storefront（店面）in Connecticut, and when they couldn&#39;t cover their start-up costs, Buck gave another $1,000. 译：在做了一些研究之后，巴克开出了一张 1000 美元的支票。德卢卡在康涅狄格州租了一家店面；当他们无法支付创业成本时，巴克又给了 1000 美元。（注：源页 p87 曾把第二个 $1,000 误排为“1000 英镑”并重复翻译“店面”，此处按笔记校正币种与表达。）</p></li><li><p>They&#39;d meet Monday evenings and brainstorm ideas for keeping the business running. 译：他们会在周一晚上碰面，集思广益，想办法让生意继续运转下去。</p></li><li><p>巴克在纽约从事核物理学家的日常工作。 译：Buck was working at his day job as a nuclear physicist in New York.</p></li><li><p>有一个目标也很重要。“有那么多问题会让你失望。你只需要继续朝着你的目标努力，”德卢卡补充道。 译：And having a goal was also important. “There are so many problems that can get you down. You just have to keep working toward your goal,” Deluca adds.</p></li></ol></div><h3 id="passage-7-·-vincent-van-gogh-教材-p30-32-练习册-p62-63" tabindex="-1"><a class="header-anchor" href="#passage-7-·-vincent-van-gogh-教材-p30-32-练习册-p62-63"><span>Passage 7 · Vincent van Gogh（教材 P30-32；练习册 P62-63）</span></a></h3><p>Vincent van Gogh was a 19th-century Dutch painter who lived a life filled with struggles and loneliness. During his lifetime, he sold only one painting, and most people considered his art too strange and intense. In spite of this, he is now regarded as one of the most influential painters in history, with his works selling for millions of dollars at auctions. Along with Leonardo da Vinci, he may be one of the two most famous painters who ever lived.</p><p>Van Gogh was born on March 30, 1853, in a small village in the Netherlands. His family was religious, and his father was a minister. As a young man, he worked in art dealerships but later decided to become a painter. He had a close relationship with his younger brother, Theo, who supported him financially throughout his life. However, Van Gogh often struggled with mental health issues including depression and anxiety.</p><p>He didn&#39;t seem to fit into the traditional art world of his time. People described him as odd and unpredictable. Although he briefly studied art in Brussels, he was mostly self-taught. His paintings, characterized by bold colors and swirling brushstrokes, were very different from the realistic styles popular at the time. In his personal life, he faced many failures in love and friendship. He never married and spent a great deal of time alone, focusing on his art.</p><p>The time and place in which he lived were not favorable for an artist with such a unique style. Most art critics preferred safe, classical works, and they rejected Van Gogh&#39;s innovative approach. Rather than compromise his vision, he continued to paint passionately, often working long hours in isolation. From 1888 to 1889, he created some of his most famous works in Arles, France. However, his mental health worsened, and he famously cut off part of his own ear during a breakdown. He spent his final years in an asylum, where he continued to paint until his tragic death by suicide at age 37. Despite his short and difficult life, his art has left a lasting impact on the world of painting.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>文森特·梵高是 19 世纪的荷兰画家，一生充满挣扎与孤独。在他有生之年，仅卖出一幅画作，而且大多数人认为他的艺术风格过于怪异、情绪过于强烈。尽管如此，如今他被公认为历史上最具影响力的画家之一，其作品在拍卖会上能拍出数百万美元的高价。与列奥纳多·达·芬奇一道，他或许是有史以来最负盛名的两位画家之一。</p><p>梵高于 1853 年 3 月 30 日出生在荷兰的一个小村庄。他的家庭信仰宗教，父亲是一名牧师。年轻时，他在艺术品经销商处工作，后来却决定成为一名画家。他与弟弟提奥关系亲密，提奥一生都在经济上资助他。然而，梵高常年受心理健康问题困扰，包括抑郁症和焦虑症。</p><p>他似乎与当时的传统艺术界格格不入。人们形容他古怪又难以捉摸。尽管他曾在布鲁塞尔短暂学习艺术，但他的绘画技巧主要靠自学。他的画作以大胆的色彩和漩涡状的笔触为特色，与当时流行的写实风格大相径庭。在个人生活中，他在爱情和友谊上屡遭挫折。他终身未娶，常常独处，将精力倾注于艺术创作。</p><p>他所处的时代和环境，对一位风格如此独特的艺术家并不友好。大多数艺术评论家更青睐保守、经典的作品，对梵高的创新手法嗤之以鼻。他不愿妥协自己的艺术理念，而是继续饱含激情地作画，常常独自长时间工作。1888 年至 1889 年，他在法国阿尔勒创作了部分最负盛名的作品。然而，他的心理健康状况不断恶化，在一次精神崩溃中，他竟割下了自己的一部分耳朵——这一事件广为人知。他生命的最后几年是在精神病院里度过的，在那里他仍坚持作画，直至 37 岁时悲剧性地自杀身亡。尽管生命短暂且坎坷，他的艺术却对绘画界产生了深远而持久的影响。</p></details><p><strong>词汇</strong>：struggle（斗争；奋斗；挣扎）· loneliness（孤独；寂寞）· intense（强烈的；紧张的）· influential（有影响力的）· auction（拍卖）· religious（宗教的；虔诚的）· minister（牧师；部长）· dealership（代理权；经销商）· unpredictable（不可预测的）· characterize（具有……的特征）· swirling（旋转的；打旋的）· realistic（现实的；现实主义的）· innovative（革新的；创新的）· compromise（妥协；和解）· isolation（隔离；孤立）· asylum（庇护；收容所；此处指精神病院）</p><p><strong>词组</strong>：be filled with（充满；装满）· in spite of（尽管；不管）· be regarded as（被认为是；被当作）· decide to do（决定做……）· financially support（在经济上支持）· fit into（适合；适应；融入）· focus on（集中于；专注于）· in isolation（孤立地；单独地）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>Vincent van Gogh was a 19th-century Dutch painter <strong>who lived a life filled with struggles and loneliness</strong>. —— 主句为主系表结构；who lived a life… 是定语从句，修饰先行词 painter。</p></li><li><p>His paintings, <strong>characterized by bold colors and swirling brushstrokes</strong>, were very different from the realistic styles popular at the time. —— characterized by… 是过去分词短语，修饰主语 His paintings，作非限制性定语；过去分词与逻辑主语构成被动关系。</p></li><li><p><strong>Rather than compromise</strong> his vision, he continued to paint passionately, <strong>often working long hours in isolation</strong>. —— rather than 后接动词原形；often working long hours in isolation 是现在分词短语，逻辑主语为 he，作伴随状语。</p></li></ol></div><p><strong>The girl ______ long hair and wearing a red dress is my sister. She is very kind-hearted. （那个留着长发、穿红裙子的女孩是我妹妹。她非常善良。）</strong></p><ul><li>A. with</li><li>B. has</li><li>C. having</li><li>D. whose</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（with）</strong> —— with long hair 是介词短语作后置定语；句中已有谓语 is，不能再用 has。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ with long hair 是介词短语作后置定语，与后面的 wearing a red dress 并列修饰 The girl（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ has 是谓语，句中已有谓语 is，一句不能有两个谓语。干扰点：中文「那个女孩有长发」直接译成 has。</li><li>C ❌ having 是分词，与后面的 wearing 并列时结构重复且不自然，标准说法用 with + 名词表特征。</li><li>D ❌ whose 引导定语从句要跟完整主谓（whose hair is long），而空后只有名词短语 long hair。</li></ul><p><strong>整句翻译</strong>：那个留着长发、穿红裙子的女孩是我妹妹。她非常善良。</p><p><strong>词组</strong>：<code>with long hair</code> 留着长发（with + 特征，作后置定语）；<code>kind-hearted</code> 善良的；心肠好的</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 7 · Vincent van Gogh / 课堂练习第 1 题（单句语法题，空所在句））：The girl ______ long hair and wearing a red dress is my sister. She is very kind-hearted.</p></details><p><strong>The novel ______ by the famous writer was published last year and soon became a best-seller. （那位著名作家写的小说去年出版，很快成为畅销书。）</strong></p><ul><li>A. writing</li><li>B. written</li><li>C. was written</li><li>D. which written</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（written）</strong> —— novel 与 write 为被动关系，用过去分词 written 作后置定语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ writing 是主动进行，小说不会自己写自己。干扰点：只看到 write 就选 -ing。</li><li>B ✅ novel 与 write 是被动关系，用过去分词 written 作后置定语（= which was written by the famous writer）（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ was written 是谓语形式，句中已有谓语 was published。</li><li>D ❌ which written 结构残缺：关系代词后必须接完整的从句谓语。</li></ul><p><strong>整句翻译</strong>：那位著名作家写的小说去年出版，很快成为畅销书。</p><p><strong>词组</strong>：<code>be published</code> 被出版（被动语态）；<code>best-seller</code> 畅销书</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 7 · Vincent van Gogh / 课堂练习第 2 题（单句语法题，空所在句））：The novel ______ by the famous writer was published last year and soon became a best-seller.</p></details><p><strong>I’d prefer to spend my holiday in the countryside ______ in a big city. （我宁愿在乡村度假，而不愿在大城市。）</strong></p><ul><li>A. rather than</li><li>B. more than</li><li>C. other than</li><li>D. less than</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（rather than）</strong> —— prefer to do A rather than do B 表示「宁愿做 A 而不做 B」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ prefer to do A rather than do B 是固定结构，rather than 连接两个平行的不定式短语（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ more than 表「多于」，与「宁愿……」的选择义无关。</li><li>C ❌ other than 表「除了」，句意是两者择一，不是排除。干扰点：rather than / other than 都有 than，中文也都能译成「而不」。</li><li>D ❌ less than 表「少于」，与选择关系无关。</li></ul><p><strong>整句翻译</strong>：我宁愿在乡村度假，而不愿在大城市。</p><p><strong>词组</strong>：<code>prefer to do A rather than do B</code> 宁愿做 A 而不做 B；<code>spend one&#39;s holiday</code> 度假</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 7 · Vincent van Gogh / 课堂练习第 3 题（单句语法题，空所在句））：I’d prefer to spend my holiday in the countryside ______ in a big city.</p></details><p><strong>The house ______ we visited last week is very old but has a special charm. （我们上周参观的房子很古老，却别具魅力。）</strong></p><ul><li>A. where</li><li>B. when</li><li>C. which</li><li>D. whose</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（which）</strong> —— 定语从句缺宾语，先行词 house 指物，用 which。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ where 是关系副词，要求从句不缺主语宾语；而 we visited 缺宾语。干扰点：house 是地点名词，一见地点就选 where。</li><li>B ❌ when 表时间，从句里没有时间关系。</li><li>C ✅ 定语从句缺宾语，先行词 house 指物，用关系代词 which（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ whose 表所属，后面要跟名词，而空后是主语 we。</li></ul><p><strong>整句翻译</strong>：我们上周参观的房子很古老，却别具魅力。</p><p><strong>词组</strong>：<code>visit the house</code> 参观房子（visit 是及物动词，从句缺宾语）；<code>a special charm</code> 一种特别的魅力</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 7 · Vincent van Gogh / 课堂练习第 4 题（单句语法题，空所在句））：The house ______ we visited last week is very old but has a special charm.</p></details><p><strong>Most of the goods ______ at the market are from local factories and are of high quality. （市场上出售的大多数商品来自当地工厂，而且质量很高。）</strong></p><ul><li>A. selling</li><li>B. to sell</li><li>C. sold</li><li>D. are sold</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（sold）</strong> —— goods 与 sell 为被动关系，用过去分词 sold 作后置定语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ selling 是主动进行，商品不会自己卖自己。</li><li>B ❌ to sell 表将来，「将要被卖的商品」与「来自当地工厂、质量很高」的现状不符。</li><li>C ✅ goods 与 sell 是被动关系，用过去分词 sold 作后置定语（= which are sold at the market）（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ are sold 是谓语形式，句中已有谓语 are。干扰点：把后置定语当成谓语来填。</li></ul><p><strong>整句翻译</strong>：市场上出售的大多数商品来自当地工厂，而且质量很高。</p><p><strong>词组</strong>：<code>be of high quality</code> 质量高（of + 抽象名词 = 形容词）；<code>goods</code> 商品（恒用复数）</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 7 · Vincent van Gogh / 课堂练习第 5 题（单句语法题，空所在句））：Most of the goods ______ at the market are from local factories and are of high quality.</p></details><p><strong>He decided to work hard on his project ______ waste time on meaningless things. （他决定努力做项目，而不是把时间浪费在无意义的事情上。）</strong></p><ul><li>A. rather than</li><li>B. instead</li><li>C. instead of</li><li>D. more than</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（rather than）</strong> —— 前后连接两个动词原形 work 与 waste，用 rather than。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ rather than 连接 work hard 与 waste time 两个动词原形，保持结构平行（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ instead 是副词，不能连接两个动词；要用它得另起一句。</li><li>C ❌ instead of 是介词短语，后面要接动名词 wasting，而空后是原形 waste。干扰点：instead of 与 instead 的中文都是「而不是」，词性不同。</li><li>D ❌ more than 表「多于」，与「而不是」的选择义无关。</li></ul><p><strong>整句翻译</strong>：他决定努力做项目，而不是把时间浪费在无意义的事情上。</p><p><strong>词组</strong>：<code>rather than do sth.</code> 而不是做某事（连接两个对等成分）；<code>waste time on sth.</code> 把时间浪费在某事上</p><p><strong>对比自测</strong>：做完后对照 quiz-p7:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 7 · Vincent van Gogh / 课堂练习第 6 题（单句语法题，空所在句））：He decided to work hard on his project ______ waste time on meaningless things.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>In spite of this, he is now regarded as one of the most influential painters in history, with his works selling for millions of dollars at auctions. 译：尽管如此，他现在被认为是历史上最有影响力的画家之一，他的作品在拍卖会上卖到数百万美元。</p></li><li><p>He never married and spent a great deal of time alone, focusing on his art. 译：他从未结婚，大部分时间都是独自一人，专注于他的艺术。</p></li><li><p>Despite his short and difficult life, his art has left a lasting impact on the world of painting. 译：尽管他的一生短暂而艰难，但他的艺术对画坛产生了持久的影响。</p></li></ol></div><h3 id="passage-8-·-technology-and-parental-involvement-教材-p34-38-练习册-p64-65" tabindex="-1"><a class="header-anchor" href="#passage-8-·-technology-and-parental-involvement-教材-p34-38-练习册-p64-65"><span>Passage 8 · Technology and Parental Involvement（教材 P34-38；练习册 P64-65）</span></a></h3><p>Technological change is everywhere and affects every aspect of life, mostly for the better. However, social changes that are brought about by new technology are often mistaken for a change in attitudes.</p><p>An example at hand is the involvement of parents in the lives of their children who are attending college. Surveys on this topic suggest that parents today continue to be “very” or “somewhat” overly-protective even after their children move into college dormitories. The same surveys also indicate that the rate of parental involvement is greater today than it was a generation ago. This is usually interpreted as a sign that today&#39;s parents are trying to manage their children&#39;s lives past the point where this behavior is appropriate.</p><p>However, greater parental involvement does not necessarily indicate that parents are failing to let go of their “adult” children.</p><p>In the context of this discussion, it seems valuable to first find out the cause of change in the case of parents&#39; involvement with their grown children. If parents of earlier generations had wanted to be in touch with their college-age children frequently, would this have been possible? Probably not. On the other hand, does the possibility of frequent communication today mean that the urge to do so wasn&#39;t present a generation ago? Many studies show that older parents—today&#39;s grandparents—would have called their children more often if the means and cost of doing so had not been a barrier.</p><p>Furthermore, studies show that finances are the most frequent subject of communication between parents and their college children. The fact that college students are financially dependent on their parents is nothing new; nor are requests for more money to be sent from home. This phenomenon is neither good nor bad; it is a fact of college life, today and in the past.</p><p>Thanks to the advanced technology, we live in an age of bettered communication. This has many implications well beyond the role that parents seem to play in the lives of their children who have left for college. But it is useful to bear in mind that all such changes come from the technology and not some imagined desire by parents to keep their children under their wings.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>技术变革无处不在，影响着生活的方方面面，且大多朝着更美好的方向发展。然而，新技术引发的社会变化，却常常被误认为是人们态度的转变。</p><p>一个现成的例子，是父母对在读大学的子女生活的参与度。关于这一话题的调查显示：如今，即使孩子搬入大学宿舍，父母仍会“非常”或“某种程度上”过度保护。同样的调查还表明，如今父母的参与度比上一代人更高。这种现象通常被解读为一种信号——如今的父母试图干预孩子的生活，甚至越过了“恰当”的界限。</p><p>然而，父母参与度的提高，并不一定意味着他们无法放手让成年子女独立。</p><p>在这一讨论背景下，先探究“父母对成年子女参与度变化”的原因，似乎很有价值。如果早几代的父母想频繁联系上大学的孩子，这有可能吗？大概率不行。另一方面，如今“频繁沟通的可能性”，是否意味着几十年前父母就没有这样的渴望？许多研究表明：老一辈父母（如今的祖父母），如果当时通讯方式和成本不是障碍，他们也会更频繁地给孩子打电话。</p><p>此外，研究显示，财务问题是父母与大学生子女间最常讨论的话题。大学生在经济上依赖父母，并非新鲜事；向家里索要更多生活费的请求，也屡见不鲜。这种现象既非好事也非坏事，它是大学校园生活的现实——过去如此，现在亦然。</p><p>得益于先进技术，我们生活在一个沟通更便捷的时代。这带来的影响，远不止父母在“离家上大学的子女生活中”所扮演的角色这一方面。但值得铭记的是：所有这些变化，都源于技术，而非父母“臆想中想要将孩子护在羽翼下”的欲望。</p></details><p><strong>词汇</strong>：technological（技术的）· affect（影响）· overly-protective（过分保护的）· dormitory（宿舍）· indicate（表明）· appropriate（适当的）· necessarily（必要地；必然地）· discussion（讨论）· frequently（频繁地）· furthermore（此外）· financially（财政上；经济上）· phenomenon（现象）· advanced（先进的）</p><p><strong>词组</strong>：bring about（引起；使发生）· at hand（在手边；现成的）· let go of（释放；放开）· in the context of（在……情况下）· an age of（一个……的时期）· in the case of（至于；在……的情况下）· bear in mind（记住）· on the other hand（另一方面）· thanks to（幸亏；由于）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p><strong>Thanks to</strong> the advanced technology, we live in an age of <strong>bettered</strong> communication. —— Thanks to 是介词短语，意为“由于、多亏”，作原因状语；bettered 由动词 better（改善）转化而来，是过去分词作定语。</p></li><li><p>But <strong>it</strong> is useful to bear in mind <strong>that</strong> all such changes come from the technology and not some imagined desire by parents to keep their children under their wings. —— it 是形式主语，真正主语是后置不定式 to bear in mind that...；bear in mind 意为“牢记”；过去分词 imagined 修饰 desire，表示“被想象出来的欲望”。</p></li></ol></div><p><strong>By the end of last week, they ______ the new project. （到上周末，他们已经完成了新项目。）</strong></p><ul><li>A. has finished</li><li>B. finishes</li><li>C. finished</li><li>D. had finished</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（had finished）</strong> —— by the end of last week 表示过去某时点之前已完成，用过去完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ has finished 是现在完成时，与 last week 这一过去时间点冲突，主谓也不一致。</li><li>B ❌ finishes 是一般现在时，与 last week 完全不符。</li><li>C ❌ finished 只说明过去做过，读不出「到上周末为止已经完成」的截止义。干扰点：看到过去时间就用一般过去时。</li><li>D ✅ by the end of last week 表示「到过去某时点为止已完成」，用过去完成时 had finished（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：到上周末，他们已经完成了新项目。</p><p><strong>词组</strong>：<code>by the end of last week</code> 到上周末为止（过去的时间点）；<code>finish the project</code> 完成项目</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 1 题（单句语法题，空所在句））：By the end of last week, they ______ the new project.</p></details><p><strong>I ______ in the army for more than 5 years. （我已经在军队里服役五年多了。）</strong></p><ul><li>A. am</li><li>B. was</li><li>C. have been</li><li>D. had been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（have been）</strong> —— for more than 5 years 且状态延续至今，用现在完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ am 是一般现在时，不能与 for more than 5 years 表示的时间跨度配合。</li><li>B ❌ was 只说过去的状态，读不出「到现在已经五年多」。干扰点：把服役当成过去的事。</li><li>C ✅ for + 时间段且状态延续至今，用现在完成时 have been（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ had been 是过去完成时，需要一个过去参照点，句中只有「到现在」。</li></ul><p><strong>整句翻译</strong>：我已经在军队里服役五年多了。</p><p><strong>词组</strong>：<code>in the army</code> 在部队服役；<code>for more than 5 years</code> 五年多（for + 时间段）</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 2 题（单句语法题，空所在句））：I ______ in the army for more than 5 years.</p></details><p><strong>Our roof leaked yesterday, but my father managed ______. （昨天屋顶漏水了，但父亲设法让人把它修好了。）</strong></p><ul><li>A. to get fixed it</li><li>B. get it fixed</li><li>C. to get it fixed</li><li>D. getting it fixed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（to get it fixed）</strong> —— manage to do 与 get sth. done 结合为 manage to get it fixed。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ get fixed it 语序错乱：get 的宾语 it 应在 get 之后、过去分词之前。</li><li>B ❌ manage 后要接不定式，get 不能直接跟在 manage 后面作宾语。</li><li>C ✅ manage to do + get sth. done 叠合为 manage to get it fixed（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ getting 是动名词，manage 只接不定式，不接动名词。</li></ul><p><strong>整句翻译</strong>：昨天屋顶漏水了，但父亲设法让人把它修好了。</p><p><strong>词组</strong>：<code>manage to do sth.</code> 设法做成某事；<code>get sth. done</code> 让某事被做成（get + 宾语 + 过去分词）</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 3 题（单句语法题，空所在句））：Our roof leaked yesterday, but my father managed ______.</p></details><p><strong>The poor children in the remote village are looking forward to ______ a big meal over the New Year. （偏远村庄的贫困儿童期待着新年能得到一顿丰盛的饭。）</strong></p><ul><li>A. give</li><li>B. be given</li><li>C. giving</li><li>D. being given</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（being given）</strong> —— look forward to 中 to 是介词，后接动名词；孩子「被给予」饭食，用 being given。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ give 是原形，不能作介词 to 的宾语。</li><li>B ❌ be given 是不定式形式，同样不能作介词宾语。</li><li>C ❌ giving 是主动式，孩子们是被给予的一方。干扰点：只看 look forward to 后面要 doing，忘了判主被动。</li><li>D ✅ look forward to 中 to 是介词，后接动名词；孩子「被给予」饭食，用被动式 being given（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：偏远村庄的贫困儿童期待着新年能得到一顿丰盛的饭。</p><p><strong>词组</strong>：<code>look forward to doing sth.</code> 期待做某事（to 是介词）；<code>be given a big meal</code> 被给予一顿丰盛的饭</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 4 题（单句语法题，空所在句））：The poor children in the remote village are looking forward to ______ a big meal over the New Year.</p></details><p><strong>If you ______ the doctor’s orders last week, you ______ well now. （如果你上周遵从了医嘱，现在身体就会好了。）</strong></p><ul><li>A. followed; would have been</li><li>B. followed; would be</li><li>C. had followed; would have been</li><li>D. had followed; would be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（had followed; would be）</strong> —— 上周未遵医嘱是对过去的虚拟，用 had followed；结果影响现在，用 would be。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ followed 是一般过去时，但 last week 要求与过去事实相反的 had done；主句 would have been 也与 now 不符。</li><li>B ❌ 从句用一般过去时对应「与现在相反」，而 last week 明确指的是过去。</li><li>C ❌ 从句 had followed 对，但主句 would have been 对应过去，而 now 提示结果影响现在。干扰点：看到虚拟就统一用 would have done。</li><li>D ✅ 从句与过去事实相反用 had followed；主句结果影响现在（now）用 would be，构成错综时间虚拟（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：如果你上周遵从了医嘱，现在身体就会好了。</p><p><strong>词组</strong>：<code>follow the doctor&#39;s orders</code> 遵从医嘱；<code>错综时间虚拟</code> 从句与主句分别对应不同时间，各按自己的时间选形式</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 5 题（单句语法题，空所在句））：If you ______ the doctor’s orders last week, you ______ well now.</p></details><p><strong>If only you ______ him what I said! Everything would have been all right. （要是你没有把我的话告诉他就好了！那样一切都会没事。）</strong></p><ul><li>A. do not tell</li><li>B. would not tell</li><li>C. have not told</li><li>D. had not told</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（had not told）</strong> —— 对过去的愿望用 if only + had done。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ do not tell 是一般现在时，与后句 would have been 的过去虚拟不配套。</li><li>B ❌ would not tell 是过去将来，不能用在 if only 从句里表示对过去的愿望。</li><li>C ❌ have not told 是现在完成时，不表示「与过去事实相反」。</li><li>D ✅ if only 表「要是……就好了」，对过去事实的愿望用 had done；后句 would have been 也印证这是对过去的虚拟（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：要是你没有把我的话告诉他就好了！那样一切都会没事。</p><p><strong>词组</strong>：<code>if only</code> 要是……就好了（表强烈愿望）；<code>would have been all right</code> 本会一切正常（对过去的虚拟结果）</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 6 题（单句语法题，空所在句））：If only you ______ him what I said! Everything would have been all right.</p></details><p><strong>I lost my key in the cinema ______ I watched this film. （我在观看这部电影的那家电影院里丢了钥匙。）</strong></p><ul><li>A. in which</li><li>B. that</li><li>C. which</li><li>D. in where</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（in which）</strong> —— 先行词 cinema 在从句中作地点状语，可用 in which。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 先行词 cinema 在从句中作地点状语，但从句谓语 watched 后已有宾语 this film，不能用关系代词，用 in which（= where）（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ that 作关系代词要在从句中充当主语或宾语；从句已有主语 I 和宾语 this film。</li><li>C ❌ which 单独使用缺少介词，watched this film 不需要 cinema 作宾语。干扰点：只判断先行词是物就选 which。</li><li>D ❌ in where 不成立：where 本身就是关系副词，不能再加介词。</li></ul><p><strong>整句翻译</strong>：我在观看这部电影的那家电影院里丢了钥匙。</p><p><strong>词组</strong>：<code>in the cinema</code> 在电影院（原句搭配里的介词，随关系词一起提前）；<code>the cinema in which I watched this film</code> 我看这部电影的那家影院</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 7 题（单句语法题，空所在句））：I lost my key in the cinema ______ I watched this film.</p></details><p><strong>I saw a man shouting at a driver ______ car was blocking the street. （我看见一个男人正冲一名司机叫喊，那名司机的车堵住了街道。）</strong></p><ul><li>A. whose</li><li>B. why</li><li>C. where</li><li>D. which</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（whose）</strong> —— whose car 表所属关系，whose 修饰 car。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ whose car 表所属关系，whose 在从句中作定语修饰 car（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ why 是关系副词，只能修饰 the reason 这类先行词，且从句成分要完整。</li><li>C ❌ where 是关系副词，从句里 car was blocking 已成分完整，不需要地点状语。</li><li>D ❌ which 不能修饰后面的名词 car；表所属要用 whose。干扰点：先行词 driver 是人，但空处修饰的是 car。</li></ul><p><strong>整句翻译</strong>：我看见一个男人正冲一名司机叫喊，那名司机的车堵住了街道。</p><p><strong>词组</strong>：<code>shout at sb.</code> 冲某人大喊；<code>block the street</code> 堵住街道</p><p><strong>原文定位</strong>（Passage 8 · Technology and Parental Involvement / 课堂练习第 8 题（单句语法题，空所在句））：I saw a man shouting at a driver ______ car was blocking the street.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>This is usually interpreted as a sign that today&#39;s parents are trying to manage their children&#39;s lives past the point where this behavior is appropriate. 译：这通常被理解为一个迹象，即当今父母试图管理孩子的生活，超出了这种行为恰当的程度。</p></li><li><p>Thanks to the advanced technology, we live in an age of bettered communication. 译：由于先进技术，我们生活在一个通讯更完善的时代。</p></li><li><p>这不仅意味着父母在孩子上大学后所扮演的角色。 译：This means more than just the role parents play when their children go off to college.</p></li><li><p>此外，研究表明，财务是父母和他们的大学生之间最常见的交流主题。 译：In addition, research shows that finance is the most common topic of communication between parents and their college students.</p></li></ol></div><h3 id="passage-9-·-student-cheating-教材-p38、p40、p42-43-练习册-p66" tabindex="-1"><a class="header-anchor" href="#passage-9-·-student-cheating-教材-p38、p40、p42-43-练习册-p66"><span>Passage 9 · Student Cheating（教材 P38、P40、P42-43；练习册 P66）</span></a></h3><p>Charlene, a 16-year-old student at a high school, found herself faced with a math test to which she knew none of the answers. Rather than fail, she took the test out with her and filled in the answers with the help of her friends. During a break, she got back into the classroom without being seen, crumpled the test with her shoe and left it lying on the floor. The teacher thought it had been dropped when the tests were collected; she corrected it, and Charlene received a B.</p><p>Cheating is, of course, nothing new. But today, educators are finding that cheating on the part of students has become more frequent than in the past. Whether it is copying a friend&#39;s homework, using a prepared sheet on an exam, stealing advance copies of a final, writing down rules in one&#39;s hand, or paying someone else to write a term paper, cheating appears to have gained acceptance among a growing number of students between 13 and 19.</p><p>In a 1978 study of cheating at twenty-two high schools in Georgia, it was found that cheating was common among good and poor students alike—although both boys and girls said they thought boys cheated more.</p><p>Why is student cheating on the rise? No one really knows. Some blame cheating on a general loss of good values among today&#39;s youth. They point to facts showing increased damage of public things and school stealing and think that reports, such as Watergate, have disappointed youth about the honesty of people in higher positions.</p><p>Others think that today&#39;s youth are far more practical than their forefathers. In the late sixties and early seventies, students were filled with imaginations about changing the world, but today&#39;s students feel great stress to succeed.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>16 岁的高中生夏琳（Charlene）发现自己要面对一场数学考试，可她一道题的答案都不会。为了及格，她把试卷带了出去，在朋友们的帮助下填好了答案。休息时，她没被人发现就回到教室，用鞋子把试卷揉皱，然后把它扔在地板上。老师以为试卷是收的时候掉了的，于是批改了这份试卷，夏琳得了个 B。</p><p>当然，作弊并不是什么新鲜事。但如今，教育工作者发现学生作弊的情况比过去更频繁了。无论是抄袭朋友的作业、考试时使用预先准备好的纸条、偷取期末考试的提前版试卷、在手上写下公式，还是花钱请别人写学期论文，作弊似乎在越来越多 13 至 19 岁的学生中被接受了。</p><p>1978 年，针对佐治亚州 22 所高中的作弊情况开展了一项研究，结果发现，作弊在优等生和差等生中都很普遍——尽管男孩和女孩都表示，他们认为男孩作弊更多。</p><p>为什么学生作弊的现象呈上升趋势？没人真正知道原因。一些人将作弊归咎于当今年轻人普遍良好价值观的丧失。他们指出，公共财物受损情况增多、校园偷窃行为增加等事实，还认为像“水门事件”这样的报道，让年轻人对身居高位者的诚实度感到失望。</p><p>另一些人则认为，如今的年轻人比他们的先辈实际得多。在 20 世纪 60 年代末和 70 年代初，学生们满怀着改变世界的憧憬，但如今的学生感受到了取得成功的巨大压力。</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>In a 1978 study of cheating at twenty-two high schools in Georgia, <strong>it was found that</strong> cheating was common among good and poor students alike—<strong>although</strong> both boys and girls said they thought boys cheated more. —— it was found that... 中 it 为形式主语，that 从句为真正主语；句首介词短语交代研究背景，although 从句作让步状语。</p></li><li><p>The teacher thought <strong>it had been dropped</strong> when the tests were collected; she corrected it, and Charlene received a B. —— 分号前是含宾语从句和时间状语从句的复合句，后半是 and 连接的并列句；drop 发生在过去的 thought 之前，又与试卷构成被动关系，故用过去完成时被动语态 had been dropped。</p></li><li><p>They <strong>point to</strong> facts <strong>showing</strong> increased damage of public things and school stealing and <strong>think</strong> that reports, such as Watergate, have disappointed youth about the honesty of people in higher positions. —— and 连接两个并列谓语 point to 与 think；showing... 是现在分词短语作 facts 的后置定语，相当于 facts which show...；disappoint sb. about sth. 表示“使某人对某事失望”。</p></li></ol></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>语法归纳（教材 P38；课件原例） <strong>时间状语从句</strong>：连接词包括 when, before, after, while, as soon as, until, since（普通从属连词还有 till, whenever 等）。主句是一般将来时，从句要用一般现在时表示将来；时间从句中也不用过去将来时或将来完成时，以相应的一般过去时或现在完成时代替。</p><p><strong>When you think you know nothing, then you begin to know something.</strong> 当你以为自己一无所知的时候，你就开始知道一些事物了。</p><p><strong>While my wife was reading the newspaper, I was watching TV.</strong> 当我妻子在看报纸时，我在看电视。</p><p><strong>现在完成时</strong>：构成 have/has + 过去分词。常见时间状语：for + 一段时间（I have taught English for four years.）；since + 过去时间点（He has been at this school since 1986.）；since + 一般过去时从句（I have lived here since I was born.）；since + 一段时间 + ago（I have known him since 20 years ago.）。用法：表示开始于过去的动作刚刚结束（常与 already, just, now, yet 连用，如 I&#39;ve already read that book.）；或表示过去动作的结果现在仍然存在（通常不带具体过去时间状语，如 I have lost my watch. 现在仍未找到）。</p></div><p><strong>—I’m sure Andrew will win the first prize in the final. —I think so. He ______ for it for months. （我确信安德鲁会在决赛中获得一等奖。——我也这样认为，他已经为此准备好几个月了。）</strong></p><ul><li>A. is preparing</li><li>B. was preparing</li><li>C. had been preparing</li><li>D. has been preparing</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（has been preparing）</strong> —— for months 表示从过去持续到现在且仍在准备，用现在完成进行时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ is preparing 表此刻正在准备，读不出「已经持续好几个月」。</li><li>B ❌ was preparing 是过去进行时，与「到现在还在准备」不符。</li><li>C ❌ had been preparing 是过去完成进行时，需要过去参照点，而说话时间就是现在。</li><li>D ✅ for months 表示从过去持续到现在且仍在进行，用现在完成进行时 has been preparing（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：——我确信安德鲁会在决赛中获得一等奖。——我也这样认为，他已经为此准备好几个月了。</p><p><strong>词组</strong>：<code>win the first prize</code> 获得一等奖；<code>prepare for sth.</code> 为某事做准备</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 9 · Student Cheating / 课堂练习第 1 题（单句语法题，空所在句））：—I think so. He ______ for it for months.</p></details><p><strong>By the time he realizes he ______ into a trap, it’ll be too late for him to do anything about it. （等他意识到自己已经走入陷阱时，再采取任何行动都太晚了。）</strong></p><ul><li>A. walks</li><li>B. walked</li><li>C. has walked</li><li>D. had walked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（has walked）</strong> —— By the time 从句用一般现在时表将来；「意识到」时已经走入陷阱，用现在完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ walks 是一般现在时，读不出「在他意识到之前已经走进去」。</li><li>B ❌ walked 只说明过去，与主句 it&#39;ll be too late 的将来指向不搭。</li><li>C ✅ By the time 从句用一般现在时表将来；等他意识到时，陷阱已经走进去 → 用现在完成时 has walked（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ had walked 需要过去参照点，而主句是 it&#39;ll be（将来）。</li></ul><p><strong>整句翻译</strong>：等他意识到自己已经走入陷阱时，再采取任何行动都太晚了。</p><p><strong>词组</strong>：<code>walk into a trap</code> 走进陷阱；上当；<code>too late to do anything about it</code> 再做什么都太晚</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 9 · Student Cheating / 课堂练习第 2 题（单句语法题，空所在句））：By the time he realizes he ______ into a trap, it’ll be too late for him to do anything about it.</p></details><p><strong>So far this year we ______ a fall in house prices by between 5 and 10 percent. （今年到目前为止，我们已经看到房价下降了 5% 至 10%。）</strong></p><ul><li>A. saw</li><li>B. see</li><li>C. had seen</li><li>D. have seen</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（have seen）</strong> —— so far this year 是现在完成时标志。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ saw 是一般过去时，与 so far this year（延续到现在）冲突。</li><li>B ❌ see 是一般现在时，不能表示「到目前为止已经看到」。</li><li>C ❌ had seen 是过去完成时，缺少过去参照点。干扰点：看到 so far 与过去时间混在一起就乱用时态。</li><li>D ✅ so far this year 是现在完成时的标志，表示从年初延续到现在（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：今年到目前为止，我们已经看到房价下降了 5% 至 10%。</p><p><strong>词组</strong>：<code>so far</code> 到目前为止（现在完成时标志）；<code>a fall in house prices</code> 房价的下跌</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 9 · Student Cheating / 课堂练习第 3 题（单句语法题，空所在句））：So far this year we ______ a fall in house prices by between 5 and 10 percent.</p></details><p><strong>Cathy is taking notes of the grammatical rules in class at Sunshine School, where she ______ English for a year. （凯茜正在阳光学校的课堂上记语法规则；她已在那里学英语一年。）</strong></p><ul><li>A. studies</li><li>B. studied</li><li>C. is studying</li><li>D. has been studying</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（has been studying）</strong> —— for a year 表示学习延续至今，用现在完成进行时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ studies 是一般现在时，只表习惯，不能表示已持续一年。</li><li>B ❌ studied 只说明过去，无法表达延续到现在。</li><li>C ❌ is studying 表此刻正在进行，与 for a year 的时长不相配。</li><li>D ✅ for a year 表示学习从过去延续至今，用现在完成进行时 has been studying（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：凯茜正在阳光学校的课堂上记语法规则；她已在那里学英语一年。</p><p><strong>词组</strong>：<code>take notes of</code> 记笔记；<code>for a year</code> 一年（for + 时间段）</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 9 · Student Cheating / 课堂练习第 4 题（单句语法题，空所在句））：Cathy is taking notes of the grammatical rules in class at Sunshine School, where she ______ English for a year.</p></details><p><strong>Danny ______ hard for long to realize his dream and now he is popular. （丹尼长期努力工作以实现梦想，如今他很受欢迎。）</strong></p><ul><li>A. works</li><li>B. is working</li><li>C. has worked</li><li>D. had worked</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（has worked）</strong> —— 长期努力产生「如今很受欢迎」的结果，用现在完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ works 是一般现在时，不表示长期的积累。</li><li>B ❌ is working 强调此刻正在做，读不出「长期以来一直努力」。</li><li>C ✅ 长期努力产生「如今很受欢迎」的结果，用现在完成时 has worked（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ had worked 是过去完成时，需要过去参照点；and now he is popular 指向现在。</li></ul><p><strong>整句翻译</strong>：丹尼长期努力工作以实现梦想，如今他很受欢迎。</p><p><strong>词组</strong>：<code>realize one&#39;s dream</code> 实现梦想；<code>for long</code> 长久以来</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 9 · Student Cheating / 课堂练习第 5 题（单句语法题，空所在句））：Danny ______ hard for long to realize his dream and now he is popular.</p></details><p><strong>The unemployment rate in this district ______ from 30% to 20% in the past two years. （过去两年，这一地区的失业率从 30% 降至 20%。）（整理时已修正原题百分比的增减方向。）</strong></p><ul><li>A. has fallen</li><li>B. had fallen</li><li>C. is falling</li><li>D. was falling</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（has fallen）</strong> —— in the past two years 与现在完成时搭配；失业率从 30% 降至 20%，所以选 has fallen。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ in the past two years 与现在完成时搭配；失业率从 30% 降到 20%，所以选 has fallen（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ had fallen 是过去完成时，需要「过去的过去」参照点，句中只有 in the past two years。</li><li>C ❌ is falling 表此刻正在下降，与「过去两年里从 30% 降到 20%」这一已完成的变化不符。</li><li>D ❌ was falling 表过去某时正在下降，不表示已经完成的结果。</li></ul><p><strong>整句翻译</strong>：过去两年，这一地区的失业率从 30% 降至 20%。（整理时已修正原题百分比的增减方向。）</p><p><strong>词组</strong>：<code>the unemployment rate</code> 失业率；<code>fall from ... to ...</code> 从……下降到……</p><p><strong>对比自测</strong>：做完后对照 quiz-p9:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 9 · Student Cheating / 课堂练习第 6 题（单句语法题，空所在句；原题百分比方向已在整理时最小修订））：The unemployment rate in this district ______ from 30% to 20% in the past two years.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>Rather than fail, she took the test out with her and filled in the answers with the help of her friends. 译：她没有选择不及格，而是把试卷带出去，在朋友的帮助下填写了答案。</p></li><li><p>No one really knows. Some blame cheating on a general loss of good values among today&#39;s youth. 译：没有人真正知道。一些人将作弊归咎于当今年轻人普遍丧失良好价值观。</p></li><li><p>收试卷时，老师以为它被丢掉了；她批改了夏琳的试卷，夏琳得到了 B。 译：The teacher thought it had been dropped when the tests were collected; she corrected it, and Charlene received a B.</p></li><li><p>在六十年代末七十年代初，学生们对改变世界充满了想象力，但今天的学生感到成功的压力很大。 译：In the late 1960s and early 1970s, students were full of imagination to change the world, but today&#39;s students feel great pressure to succeed.</p></li></ol></div><h3 id="passage-10-·-passenger-pigeons-教材-p40、p49-练习册-p68-69" tabindex="-1"><a class="header-anchor" href="#passage-10-·-passenger-pigeons-教材-p40、p49-练习册-p68-69"><span>Passage 10 · Passenger Pigeons（教材 P40、P49；练习册 P68-69）</span></a></h3><p>Passenger pigeons once flew over much of the United States in unbelievable numbers. Written accounts from the 18th and 19th centuries described flocks so large that they darkened the sky for hours.</p><p>It was calculated that when its population reached its highest point, there were more than 3 billion passenger pigeons—a number equal to 24 to 40 percent of the total bird population in the United States, making it perhaps the most abundant bird in the world. Even as late as 1870, when their numbers had already become smaller, a flock believed to be 1 mile wide and 320 miles (about 515 kilometers) long was seen near Cincinnati.</p><p>Sadly, the abundance of passenger pigeons may have been their undoing. Where the birds were most abundant, people believed there was an everlasting supply and killed them by the thousands. Commercial hunters attracted them to small clearings with grain, waited until pigeons had settled to feed, then threw large nets over them, taking hundreds at a time. The birds were shipped to large cities and sold in restaurants.</p><p>By the closing decades of the 19th century, the hardwood forests where passenger pigeons nested had been damaged by Americans&#39; need for wood, which scattered the flocks and forced the birds to go farther north, where cold temperatures and spring storms contributed to their decline. Soon the great flocks were gone, never to be seen again.</p><p>In 1897, the state of Michigan passed a law prohibiting the killing of passenger pigeons, but by then, no sizable flocks had been seen in the state for 10 years. The last confirmed wild pigeon in the United States was shot by a boy in Pike County, Ohio, in 1900. For a time, a few birds survived under human care. The last of them, known affectionately as Martha, died at the Cincinnati Zoological Garden on September 1, 1914.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>旅鸽曾经以令人难以置信的数量飞过美国大部分地区。18、19 世纪的文字记载描述，旅鸽群规模大到能让天空昏暗数小时。</p><p>据估算，当旅鸽的数量达到峰值时，总数超过 30 亿只——这一数量相当于美国鸟类总数量的 24% 至 40%，或许使旅鸽成为了当时世界上数量最繁多的鸟类。甚至晚至 1870 年，即便它们的数量已经减少，人们在辛辛那提附近仍看到过一个被认为宽 1 英里、长 320 英里（约 515 公里）的鸟群。</p><p>可悲的是，旅鸽的大量存在或许正是它们走向灭亡的诱因。在旅鸽数量最集中的区域，人们认为它们的供给无穷无尽，于是成百上千地捕杀它们。商业猎人用谷物把旅鸽引诱到小块空地上，等旅鸽停下来进食时，就撒下大网，一次能捕获数百只。这些鸟被运往大城市，在餐馆里售卖。</p><p>到 19 世纪的最后几十年，旅鸽筑巢依赖的硬木森林因美国人对木材的需求而遭到破坏，这驱散了鸟群，迫使旅鸽向更北的区域迁徙；而那里的寒冷气温与春季暴风雨进一步加速了它们的衰退。很快，大规模的旅鸽群消失了，再也不复存在。</p><p>1897 年，密歇根州通过了一项禁止捕杀旅鸽的法律，但那时，该州已经有 10 年没出现过有规模的旅鸽群了。美国最后一只经确认的野生旅鸽于 1900 年被俄亥俄州派克县的一个男孩射杀。有一段时间，几只旅鸽在人类照料下存活了下来。它们中最后一只（被亲切地称为“玛莎”）于 1914 年 9 月 1 日在辛辛那提动物园离世。</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p><strong>It was calculated that</strong> when its population reached its highest point, there were more than 3 billion passenger pigeons—<strong>a number equal to</strong> 24 to 40 percent of the total bird population in the United States, <strong>making</strong> it perhaps the most abundant bird in the world. —— It 是形式主语，that 从句是真正主语；其中 when... 为时间状语从句；破折号后的 a number 是同位语，equal to... 作后置定语；making... 是现在分词短语，补充说明前面整件事的结果。</p></li><li><p>Sadly, <strong>the abundance of</strong> passenger pigeons <strong>may have been</strong> their undoing. —— 主语为“抽象名词 + of + 具体名词”结构，中心词 abundance 不可数，谓语用单数；may have been 是“情态动词 + 完成式”，对过去作较委婉的推测；undoing 指“毁灭、垮台的原因”。</p></li><li><p>By the closing decades of the 19th century, the hardwood forests <strong>where passenger pigeons nested</strong> <strong>had been damaged</strong> by Americans&#39; need for wood, which scattered the flocks and forced the birds to go farther north, where cold temperatures and spring storms contributed to their decline. —— had been damaged 表示森林被破坏发生在“19 世纪末”这一过去时点之前，且是被动关系。课件还连带指出下一句 never to be seen again 是不定式结果状语，说明大群旅鸽消失后再也无法被看到。</p></li></ol></div><p><strong>According to the schedule, the manager ______ the meeting at 8:00 next morning. （按照日程，经理将在次日早上八点主持会议。）</strong></p><ul><li>A. holds</li><li>B. is going hold</li><li>C. is holding</li><li>D. is about to hold</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（is holding）</strong> —— 现在进行时可表示按计划安排的近期将来；according to the schedule 提示已安排。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ holds 是一般现在时，虽可表按时刻表安排，但本句用 at 8:00 next morning 的具体安排，习惯用现在进行时表近期将来。干扰点：一般现在时也可表时刻表。</li><li>B ❌ is going hold 结构残缺，缺了 to：应为 is going to hold。</li><li>C ✅ 现在进行时可表示按计划安排的近期将来，according to the schedule 正是「已安排好」的提示（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ is about to hold 表「马上就要」，不能带 at 8:00 next morning 这样具体的时间状语。</li></ul><p><strong>整句翻译</strong>：按照日程，经理将在次日早上八点主持会议。</p><p><strong>词组</strong>：<code>according to the schedule</code> 按照日程安排；<code>hold the meeting</code> 主持会议</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 10 · Passenger Pigeons / 课堂练习第 1 题（单句语法题，空所在句））：According to the schedule, the manager ______ the meeting at 8:00 next morning.</p></details><p><strong>With so many beautiful dresses ______, the little girl didn’t know which one to buy. （有这么多漂亮裙子可选，小女孩不知道该买哪一条。）</strong></p><ul><li>A. choosing from</li><li>B. chosen from</li><li>C. to choose from</li><li>D. to be chosen from</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（to choose from）</strong> —— with + 名词 + to do 表示有待完成；裙子是供小女孩主动选择，保留介词 from。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ choosing from 表主动进行，但裙子不会自己挑自己。</li><li>B ❌ chosen from 表被动完成，「已经被挑选过」与「还不知道买哪一条」矛盾。</li><li>C ✅ with + 名词 + to do 表有待完成；裙子是供小女孩主动挑选的对象，介词 from 不能漏（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ to be chosen from 是被动，「裙子被挑选」会把主语变成裙子自己不能选。干扰点：一看到 with 就机械套被动。</li></ul><p><strong>整句翻译</strong>：有这么多漂亮裙子可选，小女孩不知道该买哪一条。</p><p><strong>词组</strong>：<code>with + 宾语 + 宾补</code> with 复合结构，宾补可用 doing / done / to do；<code>choose from</code> 从……中挑选（from 不能漏）</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 10 · Passenger Pigeons / 课堂练习第 2 题（单句语法题，空所在句））：With so many beautiful dresses ______, the little girl didn’t know which one to buy.</p></details><p><strong>If you are walking away from a clock tower, you will hear the ticking of the clock fade to the point ______ it cannot be heard. （如果你正远离钟楼，就会听见钟表滴答声逐渐减弱，直到无法听见的程度。）</strong></p><ul><li>A. which</li><li>B. what</li><li>C. where</li><li>D. how</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（where）</strong> —— 先行词 point 在定语从句中作抽象地点状语，用 where。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 要在从句中作主语或宾语，而 it cannot be heard 主谓完整。干扰点：先行词 point 是抽象名词，容易误判成关系代词。</li><li>B ❌ what 不能引导定语从句，它本身已含先行词。</li><li>C ✅ 先行词 point 是抽象地点，从句不缺主要成分，用关系副词 where（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ how 是连接副词，不能引导定语从句。</li></ul><p><strong>整句翻译</strong>：如果你正远离钟楼，就会听见钟表滴答声逐渐减弱，直到无法听见的程度。</p><p><strong>词组</strong>：<code>fade to the point ...</code> 减弱到……的程度；<code>the point where ...</code> 抽象地点先行词 point 用 where 引导定语从句</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:6，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 10 · Passenger Pigeons / 课堂练习第 3 题（单句语法题，空所在句））：If you are walking away from a clock tower, you will hear the ticking of the clock fade to the point ______ it cannot be heard.</p></details><p><strong>He won’t go to sleep ______ you tell him a story. （除非你给他讲故事，否则他不会睡觉。）</strong></p><ul><li>A. however</li><li>B. whoever</li><li>C. as if</li><li>D. unless</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（unless）</strong> —— unless 表示「除非」，等于 if...not。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ however 表「无论如何」，只引导让步状语从句，与「除非」的条件关系不符。</li><li>B ❌ whoever 表「无论谁」，是连接代词，句子缺的是条件连词。</li><li>C ❌ as if 表「好像」，只引导方式状语从句，且从句需用虚拟或陈述语气。</li><li>D ✅ unless 表示「除非」，等于 if he does not tell him a story，与中文提示完全对应（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：除非你给他讲故事，否则他不会睡觉。</p><p><strong>词组</strong>：<code>unless</code> 除非（= if ... not）；<code>go to sleep</code> 入睡</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 10 · Passenger Pigeons / 课堂练习第 4 题（单句语法题，空所在句））：He won’t go to sleep ______ you tell him a story.</p></details><p><strong>It is reported ______ three people were badly injured in the traffic accident. （据报道，三人在交通事故中受了重伤。）</strong></p><ul><li>A. which</li><li>B. that</li><li>C. while</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— It is reported that... 是固定主语从句句型。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 要在从句中充当主语或宾语，而从句 three people were badly injured 成分完整。</li><li>B ✅ It is reported that ... 是固定主语从句句型，It 是形式主语，真正的主语是 that 从句（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ while 表「在……期间」或对比，与 It is reported 的句型不搭。</li><li>D ❌ what 本身含先行词，不能用在 It is reported 的固定句型里。</li></ul><p><strong>整句翻译</strong>：据报道，三人在交通事故中受了重伤。</p><p><strong>词组</strong>：<code>It is reported that ...</code> 据报道……（It 是形式主语）；<code>be badly injured</code> 受重伤</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 10 · Passenger Pigeons / 课堂练习第 5 题（单句语法题，空所在句））：It is reported ______ three people were badly injured in the traffic accident.</p></details><p><strong>______ weight, those girls worked out every morning. （为了减重，那些女孩每天早晨锻炼。）</strong></p><ul><li>A. Having lost</li><li>B. Losing</li><li>C. Lose</li><li>D. To lose</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（To lose）</strong> —— 不定式置于句首作目的状语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Having lost 是完成式分词，「已经减过肥」与每天锻炼的目的不符。</li><li>B ❌ Losing 读作伴随或进行，读不出「为了」的目的义。干扰点：分词也能作状语，但每类状语对应不同含义。</li><li>C ❌ Lose 是原形，不能作状语，且句中已有谓语 worked out。</li><li>D ✅ 句首表目的用不定式 To lose weight（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：为了减重，那些女孩每天早晨锻炼。</p><p><strong>词组</strong>：<code>lose weight</code> 减重；减肥；<code>work out</code> 锻炼；健身</p><p><strong>对比自测</strong>：做完后对照 quiz-p6:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 10 · Passenger Pigeons / 课堂练习第 6 题（单句语法题，空所在句））：______ weight, those girls worked out every morning.</p></details><p><strong>Many a student ______ a walk on campus after dinner. But many students ______ computer games in the dormitory too. （许多学生晚饭后会在校园散步，但也有许多学生在宿舍玩电脑游戏。）</strong></p><ul><li>A. takes; play</li><li>B. take; play</li><li>C. took; play</li><li>D. have taken; have played</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（takes; play）</strong> —— many a + 单数名词 接单数谓语 takes；many + 复数名词 接复数谓语 play。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ many a + 单数名词作主语形式上单数，谓语用 takes；many + 复数名词作主语谓语用 play（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ take 与 many a student 的单数形式冲突。干扰点：只按「许多」的意义判断复数。</li><li>C ❌ took 是过去时，与前后的习惯性描述（every dinner / too）不符。</li><li>D ❌ have taken 与 have played 是现在完成时，句子讲的是常态习惯，不用完成时。</li></ul><p><strong>整句翻译</strong>：许多学生晚饭后会在校园散步，但也有许多学生在宿舍玩电脑游戏。</p><p><strong>词组</strong>：<code>many a + 单数名词</code> 许多……（形式单数，谓语用单数）；<code>many + 复数名词</code> 许多……（谓语用复数）</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 10 · Passenger Pigeons / 课堂练习第 7 题（单句语法题，空所在句））：Many a student ______ a walk on campus after dinner. But many students ______ computer games in the dormitory too.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>Where the birds were most abundant, people believed there was an everlasting supply and killed them by the thousands. 译：在旅鸽数量最多的地方，人们认为它们取之不尽，于是成千上万地捕杀。</p></li><li><p>Written accounts from the 18th and 19th centuries described flocks so large that they darkened the sky for hours. 译：18 世纪和 19 世纪的文字记载描述了如此庞大的鸟群，以至于它们将天空遮暗数小时。</p></li><li><p>By the closing decades of the 19th century, the hardwood forests where passenger pigeons nested had been damaged by Americans&#39; need for wood, which scattered the flocks and forced the birds to go farther north, where cold temperatures and spring storms contributed to their decline. 译：到 19 世纪最后几十年，旅鸽筑巢的硬木森林因美国人对木材的需求而遭到破坏，这驱散鸟群，迫使旅鸽向更北方迁徙，而那里的低温和春季风暴导致它们减少。</p></li><li><p>据计算，当旅鸽数量达到最高点时，有超过 30 亿只旅鸽——这个数字相当于美国鸟类总数的 24% 到 40%，这可能使旅鸽成为世界上数量最多的鸟类。 译：It was calculated that when its population reached its highest point, there were more than 3 billion passenger pigeons—a number equal to 24 to 40 percent of the total bird population in the United States, making it perhaps the most abundant bird in the world.</p></li></ol></div><h3 id="passage-11-·-guide-dogs-for-the-mind-教材-p40、p53-练习册-p70-71" tabindex="-1"><a class="header-anchor" href="#passage-11-·-guide-dogs-for-the-mind-教材-p40、p53-练习册-p70-71"><span>Passage 11 · Guide Dogs for the Mind（教材 P40、P53；练习册 P70-71）</span></a></h3><p>They already guide blind and disabled people; now dogs are trained to help people with dementia. The duties of these “guide dogs for the mind” will include reminding their owners to take medicine, as well as encouraging them to eat, drink and sleep at regular intervals.</p><p>The dementia dogs will be trained to respond to sound triggers in the home that prompt them to perform tasks. These could include delivering a bite-proof bag of medicine with a note inside reminding the patient to take it, or waking them up in the morning.</p><p>The idea was developed by design students at the Glasgow School of Art and will now be put into practice by Alzheimer&#39;s Scotland and Dogs for the Disabled.</p><p>Joyce Gray of Alzheimer&#39;s Scotland said, “People in the early stages of dementia are still able to live a relatively normal life, and dogs help to maintain routine.”</p><p>The other advantage of using pets as companions is that conversation can be increasingly confusing for people with Alzheimer&#39;s, but dogs can give them a sense of silent support and companionship. People light up when they see animals. They don&#39;t need to communicate verbally but they can still interact. You can have a speechless bond.</p><p>The dog would also encourage the owner to take them out for walks, ensuring they keep exercising and interacting with other people.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>它们已能引导盲人和残障人士；如今，狗狗们正被训练来帮助痴呆症患者。这些“心灵导盲犬”的职责包括提醒主人服药，并鼓励他们定时进食、饮水和睡眠。</p><p>痴呆症辅助犬会接受训练，对家中的声音提示作出反应，从而执行任务。例如：叼来防咬的药袋（内附提醒服药的便签），或在清晨唤醒主人。</p><p>这一创意由格拉斯哥艺术学院的设计专业学生提出，现正由苏格兰阿尔茨海默协会和“残疾辅助犬”组织共同落地实践。</p><p>苏格兰阿尔茨海默协会的乔伊斯·格雷表示：“早期痴呆症患者仍能维持相对正常的生活，而狗狗有助于保持生活规律。”</p><p>以宠物为伴的另一优势在于：阿尔茨海默患者易因语言交流陷入困惑，而狗狗能提供无声的支持与陪伴。人们见到动物时会焕发神采——无需言语交流也能建立互动，形成一种无言的纽带。</p><p>这些狗狗还会鼓励主人带它们外出散步，确保主人坚持锻炼并与他人保持社交。</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>The dementia dogs will <strong>be trained to</strong> respond to sound triggers in the home <strong>that prompt them to perform tasks</strong>. —— trigger 可作名词“触发器”、动词“触发”；be trained to do sth. 表示“被训练做某事”；respond to 表示“回应”；that prompt them to perform tasks 是定语从句，修饰 sound triggers。</p></li><li><p>The other advantage of using pets as companions <strong>is that</strong> conversation can be increasingly confusing for people with Alzheimer&#39;s, <strong>but</strong> dogs can give them a sense of silent support and companionship. —— 本句为主系表结构，that conversation... 是表语从句，but 连接转折（源课件 p148 在此误重复了上一句的解析，此处按笔记整理核查口径呈现）。</p></li></ol></div><p><strong>The reason why he failed is ______ he was too careless. （他失败的原因是他太粗心。）</strong></p><ul><li>A. because</li><li>B. that</li><li>C. for</li><li>D. because of</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（that）</strong> —— The reason why... is that... 是固定结构，表语从句用 that。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ because 引导原因状语从句，不能作 is 的表语从句连接词；The reason ... is because ... 是口语冗余，规范考试口径用 that。干扰点：中文「原因是他粗心」让人直接对应 because。</li><li>B ✅ The reason why ... is that ... 是固定结构，从句 he was too careless 成分完整、只起连接作用，用 that（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ for 是并列连词（表「因为」），连接两个独立分句，不能引导名词性从句放在 is 之后。</li><li>D ❌ because of 是介词短语，后面只能接名词、代词或动名词，不能接完整的从句 he was too careless。</li></ul><p><strong>整句翻译</strong>：他失败的原因是他太粗心。</p><p><strong>词组</strong>：<code>the reason why ... is that ...</code> ……的原因是……（固定结构，表语从句用 that）；<code>too careless</code> 太粗心</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 11 · Guide Dogs for the Mind / 课堂练习第 1 题（单句语法题，空所在句））：The reason why he failed is ______ he was too careless.</p></details><p><strong>What I want to know is ______ he likes the gift given by us. （我想知道的是，他是否喜欢我们送的礼物。）</strong></p><ul><li>A. that</li><li>B. if</li><li>C. whether</li><li>D. /</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（whether）</strong> —— 表语从句表示「是否」时用 whether，通常不用 if。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ that 引导表语从句时表确定的陈述，而句中「是否喜欢」是不确定的选择，语义冲突。</li><li>B ❌ if 表「是否」通常只引导宾语从句；表语从句表「是否」习惯用 whether，不用 if。干扰点：记住了 if=是否，没看从句位置。</li><li>C ✅ 表语从句表示「是否」时用 whether 引导，通常不用 if（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ 不填连接词则 is 后直接跟一个完整句子，两个分句无连接手段；且「是否」的疑问意义必须由一个连接词承担，不能省略。</li></ul><p><strong>整句翻译</strong>：我想知道的是，他是否喜欢我们送的礼物。</p><p><strong>词组</strong>：<code>What I want to know is ...</code> 我想知道的是……（what 引导主语从句）；<code>the gift given by us</code> 我们送的礼物（过去分词短语作后置定语）</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 11 · Guide Dogs for the Mind / 课堂练习第 2 题（单句语法题，空所在句））：What I want to know is ______ he likes the gift given by us.</p></details><p><strong>The reason is ______ I missed the bus. （原因是我错过了公共汽车。）</strong></p><ul><li>A. that</li><li>B. when</li><li>C. why</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（that）</strong> —— The reason is that... 用 that 引导表语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ The reason is that ... 用 that 引导表语从句陈述原因内容，从句 I missed the bus 成分完整（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ when 在从句中作时间状语，而 I missed the bus 不缺时间状语，语义与成分都对不上。</li><li>C ❌ why 会写成「原因是我为什么错过车」，主语 reason 与 why 语义重复，逻辑混乱。</li><li>D ❌ what 要在从句中充当主语或宾语，而从句成分完整。干扰点：把「原因是什么」的疑问语气错套到表语从句上。</li></ul><p><strong>整句翻译</strong>：原因是我错过了公共汽车。</p><p><strong>词组</strong>：<code>The reason is that ...</code> 原因是……（表语从句陈述事实用 that）；<code>miss the bus</code> 错过公共汽车</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 11 · Guide Dogs for the Mind / 课堂练习第 3 题（单句语法题，空所在句））：The reason is ______ I missed the bus.</p></details><p><strong>That is ______ we were late last time. （那就是我们上次迟到的原因。）</strong></p><ul><li>A. that</li><li>B. when</li><li>C. why</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（why）</strong> —— That is why... 表示「那就是……的原因」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ that 引导表语从句只起连接作用，表「那就是我们迟到」语义不完整——句子要表达的是「那是原因」，不是「那是事实」。</li><li>B ❌ when 表时间，从句 we were late last time 不缺时间状语。干扰点：被 last time 误导成时间从句。</li><li>C ✅ That is why ... 表示「那就是……的原因」，why 在表语从句中作原因状语，与中文提示对应（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ what 要在从句中充当主语或宾语，从句成分完整，不缺。</li></ul><p><strong>整句翻译</strong>：那就是我们上次迟到的原因。</p><p><strong>词组</strong>：<code>That is why ...</code> 那就是……的原因（why 引导表语从句）；<code>be late</code> 迟到</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 11 · Guide Dogs for the Mind / 课堂练习第 4 题（单句语法题，空所在句））：That is ______ we were late last time.</p></details><p><strong>She looked ______ she were ten years younger. （她看起来仿佛年轻了十岁。）</strong></p><ul><li>A. that</li><li>B. like</li><li>C. as</li><li>D. as though</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（as though）</strong> —— as though + 虚拟语气 表示「看起来仿佛……」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ look that 从句不成立；that 从句不能作 look 的状语表达「仿佛」。</li><li>B ❌ like 是介词，后接名词或代词（look like a student），不能接从句 she were ten years younger。干扰点：把「看起来像」的 like 直接接从句。</li><li>C ❌ as 单独使用表「像」时是连词，但现代英语表「仿佛」必须用 as if / as though；as she were 结构不成立。</li><li>D ✅ as though + 虚拟语气表示「看起来仿佛……」，she were 是与现在事实相反的虚拟形式，正合「仿佛年轻了十岁」（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：她看起来仿佛年轻了十岁。</p><p><strong>词组</strong>：<code>as though / as if</code> 仿佛；好像（引导方式状语从句，可接虚拟语气）；<code>ten years younger</code> 年轻十岁（比较级）</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 11 · Guide Dogs for the Mind / 课堂练习第 5 题（单句语法题，空所在句））：She looked ______ she were ten years younger.</p></details><p><strong>—I drove to Zhuhai for the air show last week. —Is that ______ you had a few days off? （——我上周开车去珠海看航展了。——那就是你请了几天假的原因吗？）</strong></p><ul><li>A. why</li><li>B. what</li><li>C. when</li><li>D. where</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（why）</strong> —— 根据问句语义，询问「那是否是你请假的原因」，用 why。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 根据问句语义，询问「那是否是你请假的原因」，用 why 引导表语从句（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ what 要在从句中充当主语或宾语，而 you had a few days off 成分完整。</li><li>C ❌ when 问时间，答句应是时间表达，而这里问的是「请假的原因」。</li><li>D ❌ where 问地点，与「请了几天假」语义无关。干扰点：四个选项都是疑问词，只看句式像特殊疑问句，没读语义。</li></ul><p><strong>整句翻译</strong>：——我上周开车去珠海看航展了。——那就是你请了几天假的原因吗？</p><p><strong>词组</strong>：<code>have a few days off</code> 请几天假；<code>Is that why ...?</code> 那就是……的原因吗？（why 引导表语从句）</p><p><strong>对比自测</strong>：做完后对照 quiz-p11:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 11 · Guide Dogs for the Mind / 课堂练习第 6 题（单句语法题，空所在句））：—I drove to Zhuhai for the air show last week. —Is that ______ you had a few days off?</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>People light up when they see animals. 译：人们见到动物时会焕发神采。</p></li><li><p>The dog would also encourage the owner to take them out for walks, ensuring they keep exercising and interacting with other people. 译：这些狗狗还会鼓励主人带它们外出散步，确保主人坚持锻炼并与他人保持社交。</p></li><li><p>The other advantage of using pets as companions is that conversation can be increasingly confusing for people with Alzheimer&#39;s, but dogs can give them a sense of silent support and companionship. 译：以宠物为伴的另一优势在于：阿尔茨海默患者易因语言交流陷入困惑，而狗狗能提供无声的支持与陪伴。</p></li></ol></div><h3 id="passage-12-·-two-kinds-of-popularity-教材-p40、p59-练习册-p72" tabindex="-1"><a class="header-anchor" href="#passage-12-·-two-kinds-of-popularity-教材-p40、p59-练习册-p72"><span>Passage 12 · Two Kinds of Popularity（教材 P40、P59；练习册 P72）</span></a></h3><p>During the rosy years of elementary school, I enjoyed sharing my dolls and jokes, which allowed me to keep my high social status. I was the queen of the playground. Then came my tweens and teens, and mean girls and cool kids. They rose in the ranks not by being friendly but by smoking cigarettes, breaking rules and playing jokes on others, among whom I soon found myself.</p><p>Popularity is a well-explored subject in social psychology. Mitch Prinstein, a professor of clinical psychology, sorts the popular into two categories: the likable and the status seekers. The likables&#39; play-well-with-others qualities strengthen schoolyard friendships, jump-start interpersonal skills and, when tapped early, are employed ever after in life and work. Then there is the kind of popularity that appears in adolescence: status born of power and even dishonorable behavior.</p><p>Enviable as the cool kids may have seemed, Dr. Prinstein&#39;s studies show unpleasant consequences. Those who were highest in status in high school, as well as those least liked in elementary school, were most likely to engage in dangerous and risky behavior.</p><p>In one study, Dr. Prinstein examined the two types of popularity in 235 adolescents, scoring the least liked, the most liked and the highest in status based on student surveys.</p><p>&quot;We found that the least well-liked teens had become more aggressive over time toward their classmates. But so had those who were high in status. It clearly showed that while likability can lead to healthy adjustment, high status has just the opposite effect on us.&quot;</p><p>Dr. Prinstein has also found that the qualities that made the neighbors want you on a play date, including sharing, kindness and openness, carry over to later years and make you better able to relate and connect with others.</p><p>In analyzing his and other research, Dr. Prinstein came to another conclusion: not only is likability related to positive life outcomes, but it is also responsible for those outcomes.</p><p>&quot;Being liked creates opportunities for learning and for new kinds of life experiences that help somebody gain an advantage,&quot; he said.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>在小学的美好岁月里，我喜欢分享我的玩偶和笑话，这让我得以维持较高的社交地位。我曾是操场上的“女王”。后来进入十一二岁到十几岁的年纪，出现了“坏女孩”和“酷孩子”。他们提升地位不是靠友善待人，而是靠抽烟、违反规定以及捉弄他人，而我很快发现自己也成了他们捉弄的对象之一。</p><p>“受欢迎”是社会心理学中一个被深入研究的课题。临床心理学教授米奇·普林斯坦将受欢迎的人分为两类：受人喜爱型和追求地位型。受人喜爱者“与他人和睦相处”的品质能巩固校园友谊，推动人际交往技能的发展，而且如果早年就被发掘，这些品质在日后的生活和工作中也会一直发挥作用。还有一种受欢迎程度出现在青少年时期：由权力甚至不光彩行为催生的地位。</p><p>尽管“酷孩子”可能看起来令人羡慕，但普林斯坦博士的研究揭示了令人不快的后果。那些在高中时地位最高的人，以及在小学时最不受喜欢的人，“最有可能从事危险且冒险的行为”。</p><p>在一项研究中，普林斯坦博士调查了 235 名青少年身上的这两种受欢迎类型，依据学生调查对“最不受喜欢”“最受喜欢”和“地位最高”的人进行评分。“我们发现，随着时间的推移，最不受喜欢的青少年对同学变得更具攻击性。但那些地位高的人也是如此。这清楚地表明，虽然受人喜爱能带来健康的适应能力，但高地位对我们产生的影响恰恰相反。”</p><p>普林斯坦博士还发现，那些能让邻居愿意邀请你一起玩耍的品质——分享、善良、坦率——会延续到日后的岁月，让你更能与他人建立联系和产生共鸣。</p><p>在分析他自己和其他研究时，普林斯坦博士得出了另一个结论：受人喜爱不仅与积极的人生结果相关，而且也是这些结果的促成因素。“被人喜欢能创造学习和新的生活体验的机会，这些机会有助于人获得优势，”他说。</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>During the rosy years of elementary school, I enjoyed sharing my dolls and jokes, <strong>which allowed me to</strong> keep my high social status. —— which 引导非限制性定语从句，指代前面“分享娃娃和笑话”整件事；During the rosy years of elementary school 是时间状语。</p></li><li><p>They rose in the ranks <strong>not by</strong> being friendly <strong>but by</strong> smoking cigarettes, breaking rules and playing jokes on others, <strong>among whom</strong> I soon found myself. —— not by... but by... 连接两个方式状语；among whom I soon found myself 是“介词 + whom”引导的非限制性定语从句，先行词为指人的 others；find oneself among... 表示“发现自己处于……之中”。</p></li><li><p><strong>It</strong> clearly showed <strong>that while</strong> likability can lead to healthy adjustment, high status has just the opposite effect on us. —— 课件把 It 说成形式主语、that 从句说成主语从句，并指出 while 表让步对比。整理核查：此处 It 实际指上文研究结果，that 从句是 showed 的宾语从句；while 的确表示“虽然/而”，构成对比。</p></li></ol></div><p><strong>Not until I began to work ______ how much time I had wasted. （直到开始工作，我才意识到自己浪费了多少时间。）</strong></p><ul><li>A. didn’t I realize</li><li>B. did I realize</li><li>C. I didn’t realize</li><li>D. I realized</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（did I realize）</strong> —— Not until 置于句首时，主句部分倒装；过去时用 did I realize。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ didn&#39;t I realize 把否定副词前置后的倒装又加了 not，构成双重否定，语义变成「直到工作我才没意识到」，逻辑不通。</li><li>B ✅ Not until 置于句首时主句部分倒装；began 提示过去时，用 did I realize（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ I didn&#39;t realize 未倒装：否定性短语 not until 置句首时主句必须部分倒装，这是硬语法关。</li><li>D ❌ I realized 既未倒装也丢了否定，变成「直到工作我才意识到」的原序肯定句，与 not until 结构不兼容。</li></ul><p><strong>整句翻译</strong>：直到开始工作，我才意识到自己浪费了多少时间。</p><p><strong>词组</strong>：<code>not until ...</code> 直到……才……；<code>how much time I had wasted</code> 我浪费了多少时间（感叹宾语从句，陈述语序）</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 12 · Two Kinds of Popularity / 课堂练习第 1 题（单句语法题，空所在句））：Not until I began to work ______ how much time I had wasted.</p></details><p><strong>______ can you expect to get a pay rise. （只有努力工作，你才有望加薪。）</strong></p><ul><li>A. With hard work</li><li>B. Although work hard</li><li>C. Only with hard work</li><li>D. Now that he works hard</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Only with hard work）</strong> —— Only + 状语 置于句首，主句部分倒装，故 Only with hard work can you...。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ With hard work 置句首时主句不用倒装，后面应是 you can expect ...；可原句已是 can you expect 的倒装语序，前后不接。</li><li>B ❌ Although work hard 结构残缺：work hard 是谓语形式，although 后应接完整从句（although you work hard），且它与倒装语序也不搭。</li><li>C ✅ Only + 状语（with hard work）置于句首，主句部分倒装：Only with hard work can you expect ...（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ Now that he works hard 语义是「既然他努力工作」，人称跳到 he 与主句 you 不一致，且 now that 引导原因从句不要求倒装，接不上 can you expect。</li></ul><p><strong>整句翻译</strong>：只有努力工作，你才有望加薪。</p><p><strong>词组</strong>：<code>expect to do sth.</code> 有望做某事；期待做某事；<code>a pay rise</code> 加薪</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 12 · Two Kinds of Popularity / 课堂练习第 2 题（单句语法题，空所在句））：______ can you expect to get a pay rise.</p></details><p><strong>So carelessly ______ that he almost killed himself. （他开车如此粗心，差点害死自己。）</strong></p><ul><li>A. he drives</li><li>B. does he drive</li><li>C. did he drive</li><li>D. he drove</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（did he drive）</strong> —— So + 副词 置于句首，主句部分倒装；killed 提示过去时，用 did he drive。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ he drives 未倒装：So + 副词 carelessly 置句首时主句必须部分倒装。</li><li>B ❌ does he drive 倒装对但时态错：almost killed 提示说的是过去的事，应用过去时 did。干扰点：只检查倒装，漏看时态呼应。</li><li>C ✅ So carelessly 置句首主句部分倒装；killed 提示过去时，用 did he drive（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ he drove 未倒装，同样过不了倒装这一硬关。</li></ul><p><strong>整句翻译</strong>：他开车如此粗心，差点害死自己。</p><p><strong>词组</strong>：<code>so + 副词 置于句首</code> 如此……（引起主句部分倒装）；<code>almost kill oneself</code> 差点丧命</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 12 · Two Kinds of Popularity / 课堂练习第 3 题（单句语法题，空所在句））：So carelessly ______ that he almost killed himself.</p></details><p><strong>The number of people invited ______ fifty, but a number of them ______ absent for different reasons. （受邀人数是五十人，但其中许多人因不同原因缺席。）</strong></p><ul><li>A. were; was</li><li>B. was; was</li><li>C. was; were</li><li>D. were; were</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（was; were）</strong> —— the number of + 复数名词 作主语时谓语单数；a number of + 复数名词 作主语时谓语复数。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ were; was 两个空都用反了：the number of 表单数应用 was，a number of 表复数应用 were。</li><li>B ❌ was; was 第二空错：a number of them 意为「他们中的许多人」，谓语应用复数 were。干扰点：只记住 number 单数，没分辨 the/a。</li><li>C ✅ the number of people invited 的中心词是 number（单数）→ was；a number of them 相当于 many → were（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ were; were 第一空错：the number of ... 表单数概念，谓语不能用复数。</li></ul><p><strong>整句翻译</strong>：受邀人数是五十人，但其中许多人因不同原因缺席。</p><p><strong>词组</strong>：<code>the number of + 复数名词</code> ……的数目（作主语谓语用单数）；<code>a number of + 复数名词</code> 许多……（作主语谓语用复数）</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:6，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 12 · Two Kinds of Popularity / 课堂练习第 4 题（单句语法题，空所在句））：The number of people invited ______ fifty, but a number of them ______ absent for different reasons.</p></details><p><strong>Each of the students, working hard at his or her lessons, ______ to go to university. （每个努力学习的学生都希望上大学。）</strong></p><ul><li>A. hope</li><li>B. hopes</li><li>C. hoping</li><li>D. hoped</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（hopes）</strong> —— 中心主语 Each 为单数，谓语用 hopes。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ hope 与主语 Each 的单数形式冲突。干扰点：被 students 的复数带偏，没找真正的主语中心词。</li><li>B ✅ 主语中心词是 Each（单数），中间的 working hard at his or her lessons 是分词插入语，谓语用 hopes（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ hoping 是非谓语，句中将没有谓语动词，结构不完整。</li><li>D ❌ hoped 是过去时，句子说的是普遍情况（学生都想上大学），无过去时间状语，应用一般现在时。</li></ul><p><strong>整句翻译</strong>：每个努力学习的学生都希望上大学。</p><p><strong>词组</strong>：<code>each of + 复数名词</code> ……中的每一个（主语中心词 each 为单数）；<code>work hard at one&#39;s lessons</code> 努力学习功课</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:6，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 12 · Two Kinds of Popularity / 课堂练习第 5 题（单句语法题，空所在句））：Each of the students, working hard at his or her lessons, ______ to go to university.</p></details><p><strong>A library with five thousand books ______ to the nation as a gift. （一座藏有五千本书的图书馆被作为礼物赠予国家。）</strong></p><ul><li>A. is offered</li><li>B. has offered</li><li>C. are offered</li><li>D. have offered</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（is offered）</strong> —— 中心主语 A library 为单数，且与 offer 为被动关系，用 is offered。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 主语中心词 A library 为单数，with 短语只是修饰；图书馆是「被赠予」的对象，用被动 is offered（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ has offered 是主动形式，图书馆不能自己赠予自己；且现在完成时与「作为礼物赠予国家」的叙述口径也不搭。</li><li>C ❌ are offered 用了复数，与单数主语 A library 冲突。干扰点：被 five thousand books 的复数带偏。</li><li>D ❌ have offered 主动加复数，语态与一致双错。</li></ul><p><strong>整句翻译</strong>：一座藏有五千本书的图书馆被作为礼物赠予国家。</p><p><strong>词组</strong>：<code>with five thousand books</code> 藏有五千本书（with 短语作后置修饰，不影响主语单复数）；<code>offer sth. to sb.</code> 把某物赠予某人（被动：be offered to）</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 12 · Two Kinds of Popularity / 课堂练习第 6 题（单句语法题，空所在句））：A library with five thousand books ______ to the nation as a gift.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>During the rosy years of elementary school, I enjoyed sharing my dolls and jokes, which allowed me to keep my high social status. 译：在小学的美好岁月里，我喜欢分享我的玩偶和笑话，这让我得以维持较高的社交地位。</p></li><li><p>They rose in the ranks not by being friendly but by smoking cigarettes, breaking rules and playing jokes on others, among whom I soon found myself. 译：他们提升地位不是靠友善待人，而是靠抽烟、违反规定以及捉弄他人，而我很快发现自己也成了他们捉弄的对象之一。</p></li><li><p>It clearly showed that while likability can lead to healthy adjustment, high status has just the opposite effect on us. 译：这清楚地表明，虽然受人喜爱能带来健康的适应能力，但高地位对我们产生的影响恰恰相反。</p></li></ol></div><h3 id="passage-13-·-a-report-warns-of-a-global-food-crisis-教材-p61、p64-练习册-p73-74" tabindex="-1"><a class="header-anchor" href="#passage-13-·-a-report-warns-of-a-global-food-crisis-教材-p61、p64-练习册-p73-74"><span>Passage 13 · A Report Warns of a Global Food Crisis（教材 P61、P64；练习册 P73-74）</span></a></h3><p>A recent research report indicates that food is increasingly in short supply globally as climate change intensifies and populations continue to expand. The report was presented at the International Food Security Summit held in Rome last week, an event regarded as one of the most significant gatherings focused on global food issues.</p><p>Mayor of Rome, Roberto Gualtieri, addressed the summit during a key session. He emphasized that food insecurity is not confined to specific regions but has become a widespread concern. “Even in a city like Rome, with its long-standing agricultural heritage, we are not immune,” he stated.</p><p>In Rome, the local food supply has been severely affected. Unusual weather patterns, including extended droughts and sudden heavy floods, have damaged crops. Moreover, the rapid urbanization process has led to the loss of large areas of agricultural land, disrupting traditional food production systems. To cope with the situation, local authorities have started promoting urban gardening projects. They have converted underutilized public spaces into community gardens, aiming to increase local food production and improve food access for city residents.</p><p>Globally, the situation is even more alarming. By 2050, the world population is projected to reach a new high, and the demand for food is expected to surge by over 50%. The report warns that without effective measures, over 3 billion people could face food shortages, struggling to obtain enough nutritious food.</p><p>To prevent such a dire crisis, experts at the summit called for a series of “sustainable agriculture-based solutions”. These solutions involve adopting innovative farming techniques, such as precision agriculture, which uses advanced technology to optimize water and fertilizer use, thereby increasing crop yields while reducing environmental impact. Additionally, promoting organic farming practices can improve soil quality and biodiversity, making agricultural systems more resilient to climate change. Experts also proposed strengthening international cooperation in food trade and distribution to ensure a more balanced supply of food across different regions. Protecting natural habitats, such as forests and grasslands, is also crucial, as they play a vital role in maintaining a stable climate and supporting agricultural ecosystems. As the global population continues to grow and the climate situation becomes more complex, these proposals will be essential for safeguarding global food security.</p><details class="hint-container details"><summary>展开课件中文译文 · 一份报告警示：气候变化与人口增长引发全球粮食危机</summary><p>近期一份研究报告指出，随着气候变化加剧以及人口持续增长，全球粮食供应日益短缺。该报告在上周于罗马举行的国际粮食安全峰会上发布，这场峰会被视为聚焦全球粮食问题的最重要会议之一。</p><p>罗马市长罗伯托·瓜尔蒂耶里在峰会的一个关键环节发表了讲话。他强调，粮食不安全问题并非局限于特定地区，而是已成为广泛关注的焦点。“即便是像罗马这样有着悠久农业传统的城市，我们也未能幸免，”他表示。</p><p>在罗马，当地的粮食供应受到了严重影响。异常的天气模式，包括持续的干旱和突如其来的大洪水，对农作物造成了损害。此外，快速的城市化进程导致大量农业用地流失，扰乱了传统的粮食生产系统。为应对这一状况，当地政府已开始推广城市园艺项目。他们将一些未充分利用的公共空间改造成社区花园，旨在提高当地粮食产量，并改善城市居民的粮食获取渠道。</p><p>从全球范围来看，形势更为严峻。到 2050 年，世界人口预计将达到新高，对粮食的需求预计将激增 50% 以上。报告警示称，如果不采取有效措施，超过 30 亿人可能会面临粮食短缺问题，难以获得足够的营养食品。</p><p>为防止如此可怕的危机发生，峰会上的专家们呼吁采取一系列“基于可持续农业的解决方案”。这些解决方案包括采用创新的农业技术，例如精准农业，它利用先进技术优化水和肥料的使用，从而在提高农作物产量的同时减少对环境的影响。此外，推广有机农业实践有助于改善土壤质量和生物多样性，使农业系统更能抵御气候变化的影响。专家们还提议加强粮食贸易和分配方面的国际合作，以确保不同地区之间的粮食供应更加均衡。保护森林和草原等自然栖息地也至关重要，因为它们在维持稳定气候和支持农业生态系统方面发挥着至关重要的作用。随着全球人口持续增长，气候状况变得更加复杂，这些提议对于保障全球粮食安全将至关重要。</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>A recent research report indicates <strong>that</strong> food is increasingly in short supply globally <strong>as</strong> climate change intensifies and populations continue to expand. —— 主句为 A recent research report indicates that...；that 引导宾语从句；从句内的 as climate change intensifies and populations continue to expand 是 as 引导的时间状语从句，表示伴随变化。</p></li><li><p>Moreover, the rapid urbanization process has led to the loss of large areas of agricultural land, <strong>disrupting traditional food production systems</strong>. —— disrupting traditional food production systems 是现在分词短语作结果状语，说明农业用地流失带来的结果。</p></li><li><p>These solutions involve adopting innovative farming techniques, such as precision agriculture, <strong>which</strong> uses advanced technology to optimize water and fertilizer use, <strong>thereby increasing</strong> crop yields <strong>while reducing</strong> environmental impact. —— such as precision agriculture 举例；which... 是定语从句，修饰 precision agriculture；thereby increasing... 是现在分词短语作结果状语，while reducing... 表同时发生。</p></li></ol></div><p><strong>The conference ______ a full week by the time it ends. （到会议结束时，它将已经持续整整一周。）</strong></p><ul><li>A. must have lasted</li><li>B. will have lasted</li><li>C. would last</li><li>D. has lasted</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（will have lasted）</strong> —— by the time + 一般现在时 表示将来截止点，主句用将来完成时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ must have lasted 是「肯定已经持续了」的推测语气，与「到结束时将持续满一周」的陈述口径不符。干扰点：have lasted 的完成形式接近完成时，但情态动词 must 改变了句意。</li><li>B ✅ by the time + 一般现在时（it ends 表将来）表示将来截止点，主句用将来完成时 will have lasted（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ would last 是过去将来时，需要一个过去参照点；句中只有将来参照（it ends）。</li><li>D ❌ has lasted 是现在完成时，截止点应对应「现在」；而 by the time it ends 的截止点在将来。</li></ul><p><strong>整句翻译</strong>：到会议结束时，它将已经持续整整一周。</p><p><strong>词组</strong>：<code>by the time ...</code> 到……的时候（引导时间状语从句，表截止点）；<code>last a full week</code> 持续整整一周</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 13 · A Report Warns of a Global Food Crisis / 课堂练习第 1 题（单句语法题，空所在句））：The conference ______ a full week by the time it ends.</p></details><p><strong>British people often avoid ______ to strangers until they have been introduced. （英国人通常在经人介绍前避免与陌生人交谈。）</strong></p><ul><li>A. talking</li><li>B. to talk</li><li>C. talk</li><li>D. talks</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（talking）</strong> —— avoid doing sth. 表示「避免做某事」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ avoid doing sth. 表示「避免做某事」，用动名词 talking（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ avoid 后不接不定式：avoid to talk 不符合该动词的固定搭配。</li><li>C ❌ talk 是动词原形，不能直接作 avoid 的宾语。</li><li>D ❌ talks 是谓语第三人称单数形式，同样不能作宾语；且句中已有谓语 avoid。</li></ul><p><strong>整句翻译</strong>：英国人通常在经人介绍之前避免与陌生人交谈。</p><p><strong>词组</strong>：<code>avoid doing sth.</code> 避免做某事（avoid 后接动名词）；<code>be introduced</code> 被介绍</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 13 · A Report Warns of a Global Food Crisis / 课堂练习第 2 题（单句语法题，空所在句））：British people often avoid ______ to strangers until they have been introduced.</p></details><p><strong>At the time of economic crisis, he could only earn a ______ of $2,000 per month. （经济危机时期，他每月只能挣 2,000 美元薪水。）</strong></p><ul><li>A. wage</li><li>B. pay</li><li>C. salary</li><li>D. fee</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（salary）</strong> —— 按月支付的固定薪酬用 salary；fee 指服务费，wage 多指按时/日/周计酬。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wage 多指按小时、天或周计酬的工钱，不与 per month 的固定月薪搭配。干扰点：中文「工资」泛化，四个词都可译成工资。</li><li>B ❌ pay 泛指报酬，是集合概念，不与 a ... of $2,000 的具体计量结构搭配（a pay of 不自然）。</li><li>C ✅ 按月支付的固定薪酬用 salary；a salary of $2,000 per month 结构自然（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ fee 指服务费、学费、手续费等专业费用，不是雇员按月领取的薪酬。</li></ul><p><strong>整句翻译</strong>：经济危机时期，他每月只能挣 2,000 美元薪水。</p><p><strong>词组</strong>：<code>at the time of economic crisis</code> 在经济危机时期；<code>per month</code> 每月</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:0，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 13 · A Report Warns of a Global Food Crisis / 课堂练习第 3 题（单句语法题，空所在句））：At the time of economic crisis, he could only earn a ______ of $2,000 per month.</p></details><p><strong>Oil is an important ______ material which can be processed into many different products. （石油是一种重要原材料，可加工成许多不同产品。）</strong></p><ul><li>A. raw</li><li>B. rough</li><li>C. flexible</li><li>D. tough</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（raw）</strong> —— raw material 是固定搭配，意为「原材料」。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ raw material 是固定搭配，意为「原材料」，与「可加工成多种产品」的语境吻合（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ rough 意为「粗糙的」，rough material 不是固定说法，与石油的工业用途不搭。</li><li>C ❌ flexible 意为「柔韧的；灵活的」，多修饰材料的可塑性或人的处事方式，不能修饰 material 表达「原料」义。</li><li>D ❌ tough 意为「坚韧的」，tough material 指耐用的材料，语义与「加工成多种产品」不贴。干扰点：四个都是形容词，只靠中文「原始的/粗糙的」模糊印象选择。</li></ul><p><strong>整句翻译</strong>：石油是一种重要的原材料，可以加工成许多不同的产品。</p><p><strong>词组</strong>：<code>raw material</code> 原材料（固定搭配）；<code>be processed into</code> 被加工成</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 13 · A Report Warns of a Global Food Crisis / 课堂练习第 4 题（单句语法题，空所在句））：Oil is an important ______ material which can be processed into many different products.</p></details><p><strong>Europe’s earlier industrial growth was ______ by the availability of key resources, abundant and cheap labor, coal, iron, ore, etc. （欧洲早期工业增长得益于关键资源的可获得性，以及充足廉价的劳动力、煤、铁矿石等。）</strong></p><ul><li>A. constrained</li><li>B. detained</li><li>C. remained</li><li>D. sustained</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（sustained）</strong> —— sustain 表示「维持、支撑」，与工业增长及资源条件搭配。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ constrained 意为「受限制」，与后面罗列的有利资源条件方向相反。干扰点：-strained 与 sustained 形近。</li><li>B ❌ detained 意为「拘留；扣留」，对象只能是人，不能与 industrial growth 搭配。</li><li>C ❌ remained 是不及物动词「保持」，没有被动语态，was remained 结构错误。干扰点：把 remain 当及物动词。</li><li>D ✅ sustain 表示「维持、支撑」，工业增长「由资源条件支撑」，与 growth 及资源罗列搭配（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：欧洲早期工业增长得益于关键资源的可获得性，以及充足廉价的劳动力、煤、铁矿石等。</p><p><strong>词组</strong>：<code>the availability of key resources</code> 关键资源的可获得性；<code>abundant and cheap labor</code> 充足而廉价的劳动力</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 13 · A Report Warns of a Global Food Crisis / 课堂练习第 5 题（单句语法题，空所在句））：Europe’s earlier industrial growth was ______ by the availability of key resources, abundant and cheap labor, coal, iron, ore, etc.</p></details><p><strong>The book tells us about the author’s life ______ about his writings. （这本书既讲述作者的生平，也讲述他的作品。）</strong></p><ul><li>A. also</li><li>B. as much as</li><li>C. as well as</li><li>D. as well</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（as well as）</strong> —— as well as 连接 about his life 与 about his writings，表示「以及」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ also 是副词，不能连接两个 about 介词短语；要放在句中作状语（The book also tells us ...）。干扰点：中文「也」直接对应 also。</li><li>B ❌ as much as 表「和……一样多」，把句子变成数量比较，改变了原句「既……又……」的并列语义。</li><li>C ✅ as well as 连接 about his life 与 about his writings 两个对等介词短语，表示「以及」（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ as well 常置于句末（= too），不能放在句中连接两个短语。</li></ul><p><strong>整句翻译</strong>：这本书既讲述作者的生平，也讲述他的作品。</p><p><strong>词组</strong>：<code>as well as</code> 以及；既……又……（连接两个对等成分）；<code>the author’s life / his writings</code> 作者的生平 / 他的作品</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:1，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 13 · A Report Warns of a Global Food Crisis / 课堂练习第 6 题（单句语法题，空所在句））：The book tells us about the author’s life ______ about his writings.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>A recent research report indicates that food is increasingly in short supply globally as climate change intensifies and populations continue to expand. 译：最近的一份研究报告表明，随着气候变化加剧和人口持续增长，全球粮食供应日益短缺。</p></li><li><p>To cope with the situation, local authorities have started promoting urban gardening projects. 译：为了应对这种情况，当地政府已经开始推动城市园艺项目。</p></li><li><p>As the global population continues to grow and the climate situation becomes more complex, these proposals will be essential for safeguarding global food security. 译：随着全球人口持续增长和气候形势变得更加复杂，这些建议对于保障全球粮食安全至关重要。</p></li></ol></div><h3 id="passage-14-·-smart-buildings-against-earthquakes-教材-p66、p69-练习册-p75" tabindex="-1"><a class="header-anchor" href="#passage-14-·-smart-buildings-against-earthquakes-教材-p66、p69-练习册-p75"><span>Passage 14 · Smart Buildings Against Earthquakes（教材 P66、P69；练习册 P75）</span></a></h3><p>After the violent earthquake that shook Los Angeles in 1994, earthquake scientists had good news to report: the damage and death toll could have been much worse.</p><p>More than 60 people died in this earthquake. By comparison, an earthquake of similar intensity that shook America in 1988 claimed 25,000 victims.</p><p>Injuries and deaths were relatively less in Los Angeles because the quake occurred at 4:31 a.m. on a holiday, when traffic was light on the city&#39;s highways.</p><p>In addition, changes made to the construction codes in Los Angeles during the last 20 years have strengthened the city&#39;s buildings and highways, making them more resistant to quakes.</p><p>Despite the good news, civil engineers aren&#39;t resting on their successes. Pinned to their drawing boards are blueprints for improved quake-resistant buildings. The new designs should offer even greater security to cities where earthquakes often take place.</p><p>In the past, making structures quake-resistant meant firm yet flexible materials, such as steel and wood, that bend without breaking. Later, people tried to lift a building off its foundation and insert rubber and steel between the building and its foundation to reduce the impact of ground vibrations. The most recent designs give buildings brains as well as concrete and steel supports. Called smart buildings, the structures respond like living organisms to an earthquake&#39;s vibrations. When the ground shakes and the building tips forward, the computer would force the building to shift in the opposite direction.</p><p>The new smart structures could be very expensive to build. However, they would save many lives and would be less likely to be damaged during earthquakes.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>1994 年洛杉矶发生强烈地震后，地震科学家有消息要报告：损失和死亡人数本可能会严重得多。</p><p>这次地震中有 60 多人丧生。相比之下，1988 年美国发生的一次强度类似的地震造成了 25,000 人遇难。</p><p>洛杉矶的伤亡相对较少，是因为地震发生在凌晨 4 点 31 分，当时正值节假日，城市高速公路上的交通流量很小。</p><p>此外，过去 20 年里洛杉矶对建筑规范所做的修改，加固了城市的建筑物和高速公路，使它们更能抵御地震。</p><p>尽管有这些好消息，土木工程师们并没有满足于已有的成功。他们的绘图板上钉着改进抗震建筑的蓝图。这些新设计应该能为经常发生地震的城市提供更大的安全保障。</p><p>过去，使建筑物具有抗震能力意味着使用坚固且有弹性的材料，比如钢和木材，这些材料弯曲时不会断裂。后来，人们试图将建筑物从地基上抬升起来，并在建筑物和地基之间插入橡胶和钢材，以减轻地面震动的影响。最新的设计不仅为建筑物提供混凝土和钢材支撑，还赋予它们“大脑”。这些被称为智能建筑的结构，能像生物一样对地震的震动作出反应。当地面摇晃、建筑物向前倾斜时，计算机就会迫使建筑物向相反方向移动。</p><p>建造这种新的智能结构可能会非常昂贵。然而，它们能够挽救许多生命，并且在地震中更不容易受到损坏。</p><p>（笔记按课件保留“1988 年美国发生相似强度地震造成 25,000 人遇难”的表述，不在整理中擅自替换。）</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p>Injuries and deaths were relatively less in Los Angeles <strong>because</strong> the quake occurred at 4:31 a.m. on a holiday. —— occur 是不及物动词，意为“发生、出现”；because 引导原因状语从句。</p></li><li><p>The damage and death toll <strong>could have been</strong> much worse. —— “情态动词 + 完成式”用于对过去情况作假设或推测；could have been 强调过去存在可能性但实际未发生；death toll 指灾害或事故的死亡人数；much 修饰比较级 worse。</p></li></ol></div><p><strong>—Why, she is absent again! —She was ______ badly in an accident. （——咦，她又缺席了！——她在事故中受了重伤。）</strong></p><ul><li>A. injured</li><li>B. harmed</li><li>C. shocked</li><li>D. beaten</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（injured）</strong> —— 人在事故中「受伤」用 be injured。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 人在事故中「受伤」用 be injured，be injured badly in an accident 是固定表达（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ harm 多指对抽象事物（健康、名誉、关系）的损害，「人在事故中受伤」不用 be harmed。</li><li>C ❌ shocked 意为「震惊的」，be shocked badly 搭配不当，且与「缺席」的因果（受伤）不符。</li><li>D ❌ beaten 意为「被殴打；被打败」，语境中没有打斗或比赛的提示。干扰点：四个词都能与「坏结果」沾边，只靠中文「受害」的模糊印象选。</li></ul><p><strong>整句翻译</strong>：——咦，她又缺席了！——她在事故中受了重伤。</p><p><strong>词组</strong>：<code>be injured badly</code> 受重伤；<code>in an accident</code> 在事故中</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 14 · Smart Buildings Against Earthquakes / 课堂练习第 1 题（单句语法题，空所在句））：—Why, she is absent again! —She was ______ badly in an accident.</p></details><p><strong>The book tells us about the author’s life ______ about his writings. （这本书既讲作者生平，也讲他的作品。）</strong></p><ul><li>A. also</li><li>B. as much as</li><li>C. as well as</li><li>D. as well</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（as well as）</strong> —— as well as 连接两个 about 短语。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ also 是副词，只能作状语，不能连接两个 about 短语；放在此处语法不成立。</li><li>B ❌ as much as 表「和……一样多」，把并列语义变成数量比较，句意跑偏。</li><li>C ✅ as well as 连接两个 about 介词短语，表示「以及」（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ as well 是副词性短语，常放句末，不能放在句中起连接作用。干扰点：as well 与 as well as 只差一个 as，词性却不同。</li></ul><p><strong>整句翻译</strong>：这本书既讲作者生平，也讲他的作品。</p><p><strong>词组</strong>：<code>as well as</code> 以及；既……又……（连接两个对等成分）；<code>tell sb. about sth.</code> 向某人讲述某事</p><p><strong>对比自测</strong>：做完后对照 quiz-p13:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 14 · Smart Buildings Against Earthquakes / 课堂练习第 2 题（单句语法题，空所在句））：The book tells us about the author’s life ______ about his writings.</p></details><p><strong>The old man ______ since he came into the hospital. （这位老人入院以来一直受到悉心照顾。）</strong></p><ul><li>A. has taken good care of</li><li>B. has been taken good care of</li><li>C. has taken good care</li><li>D. has been taken good care</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（has been taken good care of）</strong> —— take good care of 变被动时介词 of 不能丢，用现在完成时被动语态。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ has taken good care of 是主动式，变成「老人照顾别人」，主被动颠倒。干扰点：中文「老人受到照顾」无主被动标记。</li><li>B ✅ since he came into the hospital 要求现在完成时；老人是「被照顾」的一方，take good care of 变被动时介词 of 必须保留：has been taken good care of（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ has taken good care 缺介词 of，主动且短语残缺。</li><li>D ❌ has been taken good care 虽然被动对，但丢了 of——take care of 的 of 在被动式中不能省略。干扰点：以为被动式可以随手砍掉介词。</li></ul><p><strong>整句翻译</strong>：这位老人入院以来一直受到悉心照顾。</p><p><strong>词组</strong>：<code>take good care of sb.</code> 悉心照顾某人（被动时 of 不可丢）；<code>since + 一般过去时从句</code> 自从……（主句用现在完成时）</p><p><strong>对比自测</strong>：做完后对照 quiz-p12:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 14 · Smart Buildings Against Earthquakes / 课堂练习第 3 题（单句语法题，空所在句））：The old man ______ since he came into the hospital.</p></details><p><strong>If the little boy had been given the best medical care, he ______. （如果那个小男孩得到最好的医疗救治，他就不会死。）</strong></p><ul><li>A. could not die</li><li>B. have not died</li><li>C. would not die</li><li>D. would not have died</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（would not have died）</strong> —— 从句 had been given 是对过去的虚拟，主句用 would have done。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ could not die 是对现在的能力否定，与从句 had been given（对过去的虚拟）时间错位。</li><li>B ❌ have not died 只是现在完成时，缺少情态动词，构不成虚拟主句，结构不完整。</li><li>C ❌ would not die 是对现在的虚拟，而从句 had been given 明确指向过去，主从时间不匹配。干扰点：看到 would 就以为虚拟对了，没核对时间层。</li><li>D ✅ 从句 had been given 是对过去的虚拟，主句用 would have done：would not have died（来源：课件未附答案，本条为笔记补充解析）。</li></ul><p><strong>整句翻译</strong>：如果那个小男孩得到最好的医疗救治，他就不会死了。</p><p><strong>词组</strong>：<code>the best medical care</code> 最好的医疗救治；<code>would not have died</code> 本不会死（对过去的虚拟结果）</p><p><strong>对比自测</strong>：做完后对照 quiz-p8:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 14 · Smart Buildings Against Earthquakes / 课堂练习第 4 题（单句语法题，空所在句））：If the little boy had been given the best medical care, he ______.</p></details><p><strong>If he ______ me tomorrow, I would let him know. （如果他明天真给我打电话，我会告诉他。）</strong></p><ul><li>A. should call</li><li>B. should not have been called</li><li>C. were not called</li><li>D. are not called</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（should call）</strong> —— 对将来可能性较小的虚拟条件可用 if + 主语 + should do。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 对将来可能性较小的虚拟条件可用 if + 主语 + should do；主句 would let 也印证是虚拟句（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ should not have been called 是被动完成式，「如果没被打电话」与 tomorrow 的将来时间矛盾，且语义不通。</li><li>C ❌ were not called 是被动虚拟（如果没被叫/没被打电话），把 call 的宾语关系弄反：句意是「他给我打电话」。</li><li>D ❌ are not called 是一般现在时被动，时态与虚拟语气都不符。干扰点：只记得条件句用现在时，忘了这里主句是 would（虚拟）。</li></ul><p><strong>整句翻译</strong>：如果他明天真给我打电话，我会告诉他。</p><p><strong>词组</strong>：<code>if ... should do</code> 万一/如果……（对将来可能性较小的虚拟）；<code>let sb. know</code> 让某人知道；告知某人</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 14 · Smart Buildings Against Earthquakes / 课堂练习第 5 题（单句语法题，空所在句））：If he ______ me tomorrow, I would let him know.</p></details><p><strong>If you asked your father, you ______ permission. （如果你问父亲，也许会得到允许。）</strong></p><ul><li>A. may get</li><li>B. might get</li><li>C. should get</li><li>D. maybe get</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（might get）</strong> —— asked 表示与现在事实相反，主句用 might get。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ may get 是一般现在时，与 asked 的虚拟形式不配套；主从语气要一致。</li><li>B ✅ asked 表示与现在事实相反的虚拟条件，主句用过去形式的情态动词：might get（也许会得到）（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ should get 表「应当得到」，把「也许、可能」的推测语气换成了义务语气，与中文提示不符。</li><li>D ❌ maybe get 中 maybe 是副词，不能作谓语的一部分，语法结构不成立。干扰点：把 maybe 当成情态动词用。</li></ul><p><strong>整句翻译</strong>：如果你问父亲，也许会得到允许。</p><p><strong>词组</strong>：<code>ask sb.</code> 询问某人（此处 asked 为虚拟形式）；<code>get permission</code> 得到允许</p><p><strong>对比自测</strong>：做完后对照 quiz-p14:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 14 · Smart Buildings Against Earthquakes / 课堂练习第 6 题（单句语法题，空所在句））：If you asked your father, you ______ permission.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>Despite the good news, civil engineers aren&#39;t resting on their successes. 译：尽管有这些好消息，土木工程师并没有满足于已有的成功。</p></li><li><p>洛杉矶的伤亡相对较少，因为地震发生在假日凌晨 4 点 31 分。 译：Injuries and deaths were relatively less in Los Angeles because the quake occurred at 4:31 a.m. on a holiday.</p></li><li><p>最近的设计给了建筑物“大脑”，以及混凝土和钢材支撑。 译：The most recent designs give buildings brains as well as concrete and steel supports.</p></li></ol></div><h3 id="passage-15-·-attitudes-toward-ai-in-the-workplace-教材-p71、p74-练习册-p75-76" tabindex="-1"><a class="header-anchor" href="#passage-15-·-attitudes-toward-ai-in-the-workplace-教材-p71、p74-练习册-p75-76"><span>Passage 15 · Attitudes toward AI in the Workplace（教材 P71、P74；练习册 P75-76）</span></a></h3><p>Attitudes toward artificial intelligence (AI) in the workplace often vary based on different professional backgrounds. Generally, tech-savvy employees are more likely to embrace AI technologies compared to those from traditional industries. However, this is not an absolute rule.</p><p>When it comes to the use of AI-powered tools for tasks like data analysis and customer service automation, there doesn&#39;t seem to be a clear divide solely determined by professional background. The overall response from employees is mixed. In a recent survey conducted across various industries, 45 percent of employees said they were willing to work with AI-based systems, while 47 percent expressed concerns or reservations.</p><p>The fact that attitudes toward AI in the workplace are so diverse regardless of professional background indicates how impactful the integration of AI could be. Not every employee is ready to accept AI now—and in some cases, the technology is still in the experimental stage—but among those who are open-minded, employees from different professional fields show similar levels of interest.</p><p>Actually, this isn&#39;t entirely unexpected. While some employees from traditional industries may be hesitant to adopt new AI-related technologies, AI offers real advantages to all types of workers. For example, employees with repetitive and time-consuming tasks can benefit greatly from AI-driven automation, which can free up their time for more creative and strategic work.</p><p>This is particularly interesting considering that tech-industry employees, who are usually more exposed to new technologies, don&#39;t necessarily have a more positive attitude towards AI in the workplace.</p><p>When it comes to AI in the workplace, differences in attitudes are more significant based on factors other than professional background. For instance, younger employees are more likely to be enthusiastic about AI-enabled features, with 62 percent of those under 30 saying they welcome AI in the workplace, compared to 35 percent of employees over 50.</p><p>The nature of the company also matters. Employees in startups and innovative companies are more open to AI adoption than those in large, established corporations.</p><p>While there are signs that the acceptance of AI in the workplace is gradually increasing, an employee&#39;s professional background will have little to do with how AI becomes a standard part of work processes. Once AI technologies are fully developed and proven reliable, the early adopters will be the companies and individuals who can adapt quickly and make the most of these new tools.</p><details class="hint-container details"><summary>展开课件中文译文</summary><p>工作场所中人们对人工智能（AI）的态度往往因不同的专业背景而有所不同。一般来说，懂技术的员工比传统行业的员工更有可能接受人工智能技术。不过，这并非绝对规律。</p><p>在使用基于人工智能的工具来完成数据分析和客户服务自动化等任务时，似乎并不存在仅由专业背景决定的明显分歧。员工们的整体反应是复杂的。在一项涵盖多个行业的近期调查中，45% 的员工表示他们愿意使用基于人工智能的系统，而 47% 的员工则表达了担忧或保留意见。</p><p>无论专业背景如何，工作场所中人们对人工智能的态度差异如此之大，这一事实表明人工智能的整合可能会产生很大的影响。并非每个员工现在都准备好接受人工智能——而且在某些情况下，这项技术仍处于试验阶段——但在那些思想开放的员工中，来自不同专业领域的员工表现出了相似程度的兴趣。</p><p>实际上，这完全不足为奇。虽然一些传统行业的员工可能不愿意采用与人工智能相关的新技术，但人工智能为所有类型的员工都带来了实实在在的优势。例如，从事重复性和耗时任务的员工可以从人工智能驱动的自动化中大大受益，这能让他们腾出时间去做更具创造性和战略性的工作。</p><p>考虑到科技行业的员工通常更多地接触新技术，但他们对工作场所中人工智能的态度不一定更积极，这一点就格外有趣了。</p><p>当涉及到工作场所中的人工智能时，态度上的差异更多是基于专业背景之外的因素。例如，年轻员工更有可能对人工智能支持的功能充满热情，30 岁以下的员工中有 62% 表示他们欢迎工作场所中的人工智能，而 50 岁以上的员工中这一比例为 35%。</p><p>公司的性质也很重要。初创企业和创新型公司的员工比大型老牌企业的员工更愿意接受人工智能。</p><p>尽管有迹象表明工作场所对人工智能的接受度正在逐渐提高，但员工的专业背景与人工智能如何成为工作流程标准组成部分几乎没有关系。一旦人工智能技术得到充分发展并被证明是可靠的，早期采用者将是那些能够快速适应并充分利用这些新工具的公司和个人。</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>长句分析（课件原解析）</p><ol><li><p><strong>The fact that</strong> attitudes toward AI in the workplace are so diverse regardless of professional background indicates <strong>how impactful</strong> the integration of AI could be. —— 整句是主谓宾结构；主语是 The fact...background，其中 that... 是同位语从句，解释 the fact；谓语是 indicates；how impactful the integration of AI could be 是 how 引导的宾语从句。</p></li><li><p><strong>While</strong> some employees from traditional industries may be hesitant to adopt new AI-related technologies, AI offers real advantages to all types of workers. —— While... 是让步状语从句，while 意为“尽管”；AI offers... 是主句。</p></li></ol></div><p><strong>The fact ______ he failed the exam again worried his parents. （他又一次考试不及格这一事实使父母担忧。）</strong></p><ul><li>A. which</li><li>B. what</li><li>C. that</li><li>D. why</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（that）</strong> —— that 引导同位语从句，说明 the fact 的具体内容。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 引导定语从句要在从句中充当成分，而 he failed the exam again 主谓宾完整。干扰点：把同位语从句当定语从句处理。</li><li>B ❌ what 不能引导同位语从句，它本身要充当从句成分；且 the fact what ... 结构不成立。</li><li>C ✅ that 引导同位语从句，说明 the fact 的具体内容；从句成分完整、只起连接作用（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ why 引导同位语从句时先行词应是 reason；且从句不缺原因状语，是陈述事实。</li></ul><p><strong>整句翻译</strong>：他又一次考试不及格这一事实使父母担忧。</p><p><strong>词组</strong>：<code>the fact that ...</code> ……这一事实（that 引导同位语从句）；<code>fail the exam</code> 考试不及格</p><p><strong>对比自测</strong>：做完后对照 quiz-p10:4，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 15 · Attitudes toward AI in the Workplace / 课堂练习第 1 题（单句语法题，空所在句））：The fact ______ he failed the exam again worried his parents.</p></details><p><strong>I wonder ______ he will agree to this plan or not. （我想知道他是否会同意这个计划。）</strong></p><ul><li>A. if</li><li>B. whether</li><li>C. that</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（whether）</strong> —— 与 or not 搭配时用 whether。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ if 也能表「是否」，但与 or not 直接连用时习惯上用 whether 更规范（存疑：口语中 if ... or not 可见，考试口径按 whether 取）。干扰点：if 与 whether 的差别只在搭配条件上。</li><li>B ✅ 与 or not 连用表「是否」，用 whether 引导宾语从句（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ that 不表「是否」，句中「会还是不会」本是不确定的选择。</li><li>D ❌ what 要在从句中充当主语或宾语，而 he will agree to this plan 成分完整。</li></ul><p><strong>整句翻译</strong>：我想知道他是否会同意这个计划。</p><p><strong>词组</strong>：<code>agree to a plan</code> 同意一个计划；<code>whether ... or not</code> 是否……（与 or not 连用时用 whether）</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 15 · Attitudes toward AI in the Workplace / 课堂练习第 2 题（单句语法题，空所在句））：I wonder ______ he will agree to this plan or not.</p></details><p><strong>______ he is young, he knows a lot about science. （尽管他年轻，却很懂科学。）</strong></p><ul><li>A. Although</li><li>B. Because</li><li>C. Since</li><li>D. As</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（Although）</strong> —— 前后为让步关系，用 Although；As 表让步时需倒装为 Young as he is。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 前后为让步关系，用 Although 引导让步状语从句（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ Because 表因果，与句意「年轻却懂科学」的转折方向相反。</li><li>C ❌ Since 表「既然/因为」，同样是因果，接不出让步转折。</li><li>D ❌ As 表「尽管」时必须倒装（Young as he is），此处语序正装，不能表让步。干扰点：as 词义多，只记了「虽然」一个义项。</li></ul><p><strong>整句翻译</strong>：尽管他年轻，却很懂科学。</p><p><strong>词组</strong>：<code>although 引导让步状语从句</code> 尽管……（不与 but 连用）；<code>know a lot about science</code> 很懂科学</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:5，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 15 · Attitudes toward AI in the Workplace / 课堂练习第 3 题（单句语法题，空所在句））：______ he is young, he knows a lot about science.</p></details><p><strong>Could you tell me ______ the nearest hospital is? （你能告诉我最近的医院在哪里吗？）</strong></p><ul><li>A. where</li><li>B. what</li><li>C. when</li><li>D. how</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（where）</strong> —— 宾语从句缺地点状语，用 where，并保持陈述语序。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 宾语从句缺地点状语，用连接副词 where；从句保持陈述语序 where the nearest hospital is（来源：课件未附答案，本条为笔记补充解析）。</li><li>B ❌ what 要在从句中充当主语或宾语，而 the nearest hospital is 成分完整。</li><li>C ❌ when 表时间，句中没有时间含义。</li><li>D ❌ how 表方式，「医院在哪里」问的是地点而非方式。干扰点：四个选项都是连接副词，要按「缺什么状语」对号入座。</li></ul><p><strong>整句翻译</strong>：你能告诉我最近的医院在哪里吗？</p><p><strong>词组</strong>：<code>the nearest hospital</code> 最近的医院；<code>宾语从句用陈述语序</code> where the nearest hospital is，不倒装</p><p><strong>对比自测</strong>：做完后对照 quiz-p4:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 15 · Attitudes toward AI in the Workplace / 课堂练习第 4 题（单句语法题，空所在句））：Could you tell me ______ the nearest hospital is?</p></details><p><strong>We have no idea ______ the problem can be solved in such a short time. （我们不知道如何能在这么短的时间内解决问题。）</strong></p><ul><li>A. which</li><li>B. that</li><li>C. how</li><li>D. what</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（how）</strong> —— 从句结构完整但缺方式状语，用 how。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ which 要在从句中充当主语或宾语（还要有可选择的范围），而从句 the problem can be solved ... 成分完整。</li><li>B ❌ that 引导从句时只起连接作用，表不了「如何」的方式义，语义缺失。</li><li>C ✅ 从句结构完整但缺方式状语，用 how 引导同位语从句，说明「不知道」的内容（来源：课件未附答案，本条为笔记补充解析）。</li><li>D ❌ what 要充当从句成分，与完整从句冲突。干扰点：把「解决问题的方法」当成 what 的内容，但英语里方式义由 how 承担。</li></ul><p><strong>整句翻译</strong>：我们不知道如何能在这么短的时间内解决问题。</p><p><strong>词组</strong>：<code>have no idea (that/wh-...)</code> 不知道……（后接同位语从句）；<code>in such a short time</code> 在这么短的时间内</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:3，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 15 · Attitudes toward AI in the Workplace / 课堂练习第 5 题（单句语法题，空所在句））：We have no idea ______ the problem can be solved in such a short time.</p></details><p><strong>______ hard it may be, I’ll carry it out. （无论多困难，我都会完成它。）</strong></p><ul><li>A. Whatever</li><li>B. However</li><li>C. Whenever</li><li>D. Wherever</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（However）</strong> —— However + 形容词/副词 + 主语 + 谓语 表示「无论多么……」。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Whatever 后接名词（whatever difficulties），而空后直接跟形容词 hard，词性对不上。</li><li>B ✅ However + 形容词/副词 + 主语 + 谓语 表示「无论多么……」：However hard it may be = 无论多困难（来源：课件未附答案，本条为笔记补充解析）。</li><li>C ❌ Whenever 表「无论何时」，修饰时间，不能与形容词 hard 连用。</li><li>D ❌ Wherever 表「无论何地」，修饰地点，同样接不了形容词。干扰点：四个选项都是 ever 族，要按后面所接词的词性选。</li></ul><p><strong>整句翻译</strong>：无论多困难，我都会完成它。</p><p><strong>词组</strong>：<code>however + 形容词/副词 + 主语 + 谓语</code> 无论多么……（引导让步状语从句）；<code>carry out</code> 执行；完成</p><p><strong>对比自测</strong>：做完后对照 quiz-p15:2，比较两题的判断依据</p><p><strong>原文定位</strong>（Passage 15 · Attitudes toward AI in the Workplace / 课堂练习第 6 题（单句语法题，空所在句））：______ hard it may be, I’ll carry it out.</p></details><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>翻译练习（课件原题与原译）</p><ol><li><p>The fact that attitudes toward AI in the workplace are so diverse regardless of professional background indicates how impactful the integration of AI could be. 译：无论专业背景如何，工作场所对人工智能的态度如此多样化，这一事实表明，人工智能的整合可能会产生多么大的影响。</p></li><li><p>When it comes to AI in the workplace, differences in attitudes are more significant based on factors other than professional background. 译：当涉及工作场所中的人工智能时，专业背景之外的其他因素对态度差异影响更显著。</p></li><li><p>Employees in startups and innovative companies are more open to AI adoption than those in large, established corporations. 译：初创企业和创新型公司的员工比大型老牌企业的员工更愿意接受人工智能。</p></li></ol></div><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 篇章精读：<strong>标题定向，段首定位；主干先行，修饰后理；题回原文，证据唯一；译文复盘，错因归类。</strong></p><p>遇到长句先找谓语，再划出定语从句、名词性从句、状语从句与非谓语动词。</p><p>做题时联动阅读理解的定位法；处理篇章衔接时联动五选五与文章句子匹配。</p><p>每篇按“词汇 → 原文 → 译文 → 长句 → 练习 → 错因”完成闭环，不只背孤立答案。</p></div>`,481),a(`p`,null,[l[9]||=e(`关联复习：`,-1),o(m,{href:`/courses/zsb-english/l/19/`},{default:i(()=>[...l[5]||=[e(`阅读理解`,-1)]]),_:1}),l[10]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/21/`},{default:i(()=>[...l[6]||=[e(`五选五`,-1)]]),_:1}),l[11]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/22/`},{default:i(()=>[...l[7]||=[e(`文章句子匹配`,-1)]]),_:1}),l[12]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/23/`},{default:i(()=>[...l[8]||=[e(`语法填空`,-1)]]),_:1})]),l[19]||=a(`p`,null,`延伸阅读：篇章阅读 · 完整笔记 · 原始课件 PDF`,-1),l[20]||=a(`p`,null,`有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。`,-1),l[21]||=a(`hr`,null,null,-1),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/19/`},{default:i(()=>[...l[13]||=[e(`← 第 19 课`,-1)]]),_:1}),l[16]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[14]||=[e(`课程目录`,-1)]]),_:1}),l[17]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/21/`},{default:i(()=>[...l[15]||=[e(`第 21 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};